-- Checks and unconditional unique constraints
ALTER TABLE "catalog"."units_of_measure" ADD CONSTRAINT "units_of_measure_name_uq" UNIQUE ("name");
ALTER TABLE "catalog"."units_of_measure" ADD CONSTRAINT "units_of_measure_dimension_ck" CHECK (dimension IN ('count','mass','volume','length'));
ALTER TABLE "catalog"."units_of_measure" ADD CONSTRAINT "units_of_measure_precision_ck" CHECK (decimal_places BETWEEN 0 AND 6);
ALTER TABLE "catalog"."units_of_measure" ADD CONSTRAINT "units_of_measure_status_ck" CHECK (status IN ('active','retired'));
ALTER TABLE "core"."permissions" ADD CONSTRAINT "permissions_risk_ck" CHECK (risk_class IN ('read_only','reversible_write','consequential_write','regulated_external','access_administration'));
ALTER TABLE "core"."permissions" ADD CONSTRAINT "permissions_status_ck" CHECK (status IN ('active','retired'));
ALTER TABLE "core"."users" ADD CONSTRAINT "users_row_version_ck" CHECK (row_version > 0);
ALTER TABLE "core"."users" ADD CONSTRAINT "users_status_ck" CHECK (status IN ('active','disabled','anonymized'));
ALTER TABLE "core"."memberships" ADD CONSTRAINT "memberships_user_uq" UNIQUE ("org_id", "user_id");
ALTER TABLE "core"."memberships" ADD CONSTRAINT "memberships_dates_ck" CHECK ((status = 'invited' AND joined_at IS NULL AND revoked_at IS NULL) OR (status IN ('active','suspended') AND joined_at IS NOT NULL AND revoked_at IS NULL) OR (status = 'revoked' AND revoked_at IS NOT NULL));
ALTER TABLE "core"."memberships" ADD CONSTRAINT "memberships_revocation_ck" CHECK (status <> 'revoked' OR (revoked_at IS NOT NULL AND revocation_reason IS NOT NULL));
ALTER TABLE "core"."memberships" ADD CONSTRAINT "memberships_row_version_ck" CHECK (row_version > 0);
ALTER TABLE "core"."memberships" ADD CONSTRAINT "memberships_status_ck" CHECK (status IN ('invited','active','suspended','revoked'));
ALTER TABLE "core"."organizations" ADD CONSTRAINT "organizations_currency_ck" CHECK (base_currency = 'INR');
ALTER TABLE "core"."organizations" ADD CONSTRAINT "organizations_pan_ck" CHECK (pan IS NULL OR pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$');
ALTER TABLE "core"."organizations" ADD CONSTRAINT "organizations_row_version_ck" CHECK (row_version > 0);
ALTER TABLE "core"."organizations" ADD CONSTRAINT "organizations_status_ck" CHECK (status IN ('provisioning','active','suspended','closed'));
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_dataset_hash_uq" UNIQUE ("dataset_kind", "dataset_sha256");
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_version_uq" UNIQUE ("dataset_kind", "ruleset_version");
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_authority_ck" CHECK ((dataset_kind='ingredient_classification' AND source_authority='cdsco') OR (dataset_kind='hsn_sac_tax' AND source_authority IN ('gst_portal','gst_council','cbic','gstn')) OR (dataset_kind='withholding_rules' AND source_authority IN ('income_tax_department','cbic')) OR (dataset_kind='controlled_movement_rules' AND source_authority IN ('cdsco','revenue_department')) OR (dataset_kind IN ('einvoice_rules','gst_adjustment_rules') AND source_authority IN ('gst_portal','gst_council','cbic','gstn')));
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_count_ck" CHECK (record_count > 0);
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_dates_ck" CHECK (publication_date <= effective_from AND (effective_to IS NULL OR effective_to >= effective_from) AND reviewed_at <= created_at);
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_hash_ck" CHECK (octet_length(source_document_sha256)=32 AND octet_length(dataset_sha256)=32);
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_kind_ck" CHECK (dataset_kind IN ('ingredient_classification','hsn_sac_tax','withholding_rules','controlled_movement_rules','einvoice_rules','gst_adjustment_rules'));
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_status_ck" CHECK (status IN ('staged','active','superseded'));
ALTER TABLE "core"."reference_data_releases" ADD CONSTRAINT "reference_data_releases_text_ck" CHECK (btrim(ruleset_version)<>'' AND btrim(source_uri)<>'' AND btrim(source_storage_bucket)<>'' AND btrim(source_storage_object_path)<>'' AND btrim(dataset_storage_bucket)<>'' AND btrim(dataset_storage_object_path)<>'');
ALTER TABLE "catalog"."categories" ADD CONSTRAINT "categories_code_uq" UNIQUE ("org_id", "code");
ALTER TABLE "catalog"."categories" ADD CONSTRAINT "categories_not_self_ck" CHECK (parent_id IS NULL OR parent_id <> id);
ALTER TABLE "catalog"."categories" ADD CONSTRAINT "categories_row_version_ck" CHECK (row_version > 0);
ALTER TABLE "catalog"."categories" ADD CONSTRAINT "categories_status_ck" CHECK (status IN ('active','inactive'));
ALTER TABLE "catalog"."ingredients" ADD CONSTRAINT "ingredients_dates_ck" CHECK (effective_to IS NULL OR effective_to >= effective_from);
ALTER TABLE "catalog"."ingredients" ADD CONSTRAINT "ingredients_drugs_rules_schedule_ck" CHECK (drugs_rules_schedule IN ('NONE','G','H','H1','X'));
ALTER TABLE "catalog"."ingredients" ADD CONSTRAINT "ingredients_ndps_classification_ck" CHECK (ndps_classification IN ('NONE','NARCOTIC_DRUG','PSYCHOTROPIC_SUBSTANCE','CONTROLLED_SUBSTANCE'));
ALTER TABLE "catalog"."ingredients" ADD CONSTRAINT "ingredients_ruleset_ck" CHECK (btrim(classification_ruleset_version) <> '');
ALTER TABLE "catalog"."ingredients" ADD CONSTRAINT "ingredients_status_ck" CHECK (status IN ('active','retired'));
ALTER TABLE "compliance"."controlled_movement_rule_versions" ADD CONSTRAINT "controlled_movement_rule_versions_identity_uq" UNIQUE ("release_id", "rule_code", "rule_version");
ALTER TABLE "compliance"."controlled_movement_rule_versions" ADD CONSTRAINT "controlled_movement_rule_versions_counterparty_ck" CHECK ((counterparty_required AND btrim(COALESCE(counterparty_license_type_code,''))<>'') OR (NOT counterparty_required AND counterparty_license_type_code IS NULL));
