ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_provider_request_uq" UNIQUE ("org_id", "provider_name", "provider_request_id");
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_version_uq" UNIQUE ("org_id", "tax_document_id", "artifact_version");
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_cancel_ck" CHECK (status <> 'cancelled' OR (cancelled_at IS NOT NULL AND cancelled_by_membership_id IS NOT NULL AND cancellation_reason IS NOT NULL));
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_generated_ck" CHECK (status NOT IN ('generated','cancelled') OR (irn IS NOT NULL AND acknowledgement_number IS NOT NULL AND acknowledged_at IS NOT NULL AND signed_qr_bytes IS NOT NULL));
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_qr_ck" CHECK ((signed_qr_bytes IS NULL AND signed_qr_sha256 IS NULL) OR (signed_qr_bytes IS NOT NULL AND octet_length(signed_qr_sha256) = 32));
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_request_hash_ck" CHECK (octet_length(request_sha256) = 32);
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_response_ck" CHECK ((response_bytes IS NULL AND response_media_type IS NULL AND response_sha256 IS NULL) OR (response_bytes IS NOT NULL AND response_media_type IS NOT NULL AND octet_length(response_sha256) = 32));
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_status_ck" CHECK (status IN ('requested','generated','failed','cancelled'));
ALTER TABLE "tax"."einvoices" ADD CONSTRAINT "einvoices_version_ck" CHECK (artifact_version > 0 AND ((artifact_version = 1 AND supersedes_artifact_id IS NULL) OR (artifact_version > 1 AND supersedes_artifact_id IS NOT NULL)));
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_provider_request_uq" UNIQUE ("org_id", "provider_name", "provider_request_id");
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_cancel_ck" CHECK (status <> 'cancelled' OR (cancelled_at IS NOT NULL AND cancelled_by_membership_id IS NOT NULL AND cancellation_reason IS NOT NULL));
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_generated_ck" CHECK (status NOT IN ('generated','cancelled','expired') OR (eway_bill_number IS NOT NULL AND valid_from_at IS NOT NULL AND valid_until_at > valid_from_at));
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_request_hash_ck" CHECK (octet_length(request_sha256) = 32);
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_response_ck" CHECK ((response_bytes IS NULL AND response_media_type IS NULL AND response_sha256 IS NULL) OR (response_bytes IS NOT NULL AND response_media_type IS NOT NULL AND octet_length(response_sha256) = 32));
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_source_ck" CHECK (inventory_document_id IS NOT NULL);
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_status_ck" CHECK (status IN ('requested','generated','failed','cancelled','expired'));
ALTER TABLE "tax"."eway_bills" ADD CONSTRAINT "eway_bills_version_ck" CHECK (artifact_version > 0 AND ((artifact_version = 1 AND supersedes_artifact_id IS NULL) OR (artifact_version > 1 AND supersedes_artifact_id IS NOT NULL)));
ALTER TABLE "tax"."reconciliation_items" ADD CONSTRAINT "reconciliation_items_confidence_ck" CHECK (confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1);
ALTER TABLE "tax"."reconciliation_items" ADD CONSTRAINT "reconciliation_items_match_ck" CHECK ((match_status IN ('matched','mismatch') AND tax_document_id IS NOT NULL AND portal_document_line_id IS NOT NULL) OR (match_status = 'internal_only' AND tax_document_id IS NOT NULL AND portal_document_line_id IS NULL) OR (match_status = 'portal_only' AND tax_document_id IS NULL AND portal_document_line_id IS NOT NULL));
ALTER TABLE "tax"."reconciliation_items" ADD CONSTRAINT "reconciliation_items_method_ck" CHECK (match_method IN ('gstin_invoice_date','invoice_amount','manual','unmatched'));
ALTER TABLE "tax"."reconciliation_items" ADD CONSTRAINT "reconciliation_items_presence_ck" CHECK (num_nonnulls(tax_document_id,portal_document_line_id) >= 1);
ALTER TABLE "tax"."reconciliation_items" ADD CONSTRAINT "reconciliation_items_resolution_ck" CHECK (resolution_status IN ('unresolved','accepted','corrected','ignored') AND (resolution_status = 'unresolved') = (resolved_at IS NULL AND resolved_by_membership_id IS NULL));
ALTER TABLE "tax"."return_documents" ADD CONSTRAINT "return_documents_role_ck" CHECK (population_role IN ('original','amendment','credit_adjustment','debit_adjustment'));
ALTER TABLE "tax"."withholding_statement_lines" ADD CONSTRAINT "withholding_statement_lines_pair_uq" UNIQUE ("org_id", "statement_id", "withholding_id");
ALTER TABLE "tax"."withholding_statement_lines" ADD CONSTRAINT "withholding_statement_lines_identity_ck" CHECK (statement_id<>withholding_id AND statement_id<>deposit_line_id AND withholding_id<>deposit_line_id);
ALTER TABLE "inventory"."reservations" ADD CONSTRAINT "ck_reservations_quantity" CHECK (quantity>0);
ALTER TABLE "inventory"."reservations" ADD CONSTRAINT "ck_reservations_source" CHECK (num_nonnulls(order_line_id,invoice_line_id)=1);
ALTER TABLE "inventory"."reservations" ADD CONSTRAINT "ck_reservations_status" CHECK (status IN ('active','released','consumed','cancelled','expired'));
ALTER TABLE "inventory"."reservations" ADD CONSTRAINT "ck_reservations_terminal" CHECK ((status='active' AND terminal_at IS NULL AND consumed_by_inventory_document_line_id IS NULL) OR (status='consumed' AND terminal_at IS NOT NULL AND consumed_by_inventory_document_line_id IS NOT NULL) OR (status IN ('released','cancelled','expired') AND terminal_at IS NOT NULL AND consumed_by_inventory_document_line_id IS NULL));
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "uq_stock_ledger_line_location_kind" UNIQUE ("org_id", "inventory_document_line_id", "location_id", "entry_kind");
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "ck_stock_ledger_cost" CHECK (unit_cost>=0 AND ((quantity_delta<>0 AND value_delta=round(quantity_delta*unit_cost,2)) OR (quantity_delta=0 AND entry_kind IN ('value_adjustment','reversal') AND value_delta<>0)));
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "ck_stock_ledger_kind" CHECK (entry_kind IN ('receipt','issue','transfer_in','transfer_out','count_gain','count_loss','value_adjustment','reversal'));
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "ck_stock_ledger_quantity" CHECK ((entry_kind='value_adjustment' AND quantity_delta=0 AND value_delta<>0) OR (entry_kind<>'value_adjustment' AND (quantity_delta<>0 OR (entry_kind='reversal' AND quantity_delta=0 AND value_delta<>0))));
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "ck_stock_ledger_reversal" CHECK ((entry_kind='reversal') = (reverses_entry_id IS NOT NULL));
ALTER TABLE "inventory"."stock_ledger_entries" ADD CONSTRAINT "ck_stock_ledger_sign" CHECK ((entry_kind IN ('receipt','transfer_in','count_gain') AND quantity_delta>0) OR (entry_kind IN ('issue','transfer_out','count_loss') AND quantity_delta<0) OR entry_kind IN ('value_adjustment','reversal'));
ALTER TABLE "tax"."withholding_certificate_lines" ADD CONSTRAINT "withholding_certificate_lines_pair_uq" UNIQUE ("org_id", "certificate_id", "statement_line_id");
ALTER TABLE "tax"."withholding_certificate_lines" ADD CONSTRAINT "withholding_certificate_lines_amount_ck" CHECK (certified_amount>0);
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_ledger_uq" UNIQUE ("org_id", "stock_ledger_entry_id");
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_number_uq" UNIQUE ("org_id", "register_number");
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_authority_ck" CHECK ((authority_document_number IS NULL AND authority_document_date IS NULL) OR (authority_document_number IS NOT NULL AND authority_document_date IS NOT NULL));
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_counterparty_license_ck" CHECK ((counterparty_license_id IS NULL AND counterparty_license_number IS NULL) OR (counterparty_license_id IS NOT NULL AND btrim(counterparty_license_number)<>''));
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_direction_ck" CHECK (direction IN ('in','out'));
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_quantity_ck" CHECK (quantity > 0);
ALTER TABLE "compliance"."controlled_substance_entries" ADD CONSTRAINT "controlled_substance_entries_type_ck" CHECK (entry_type IN ('receipt','dispatch','return_in','return_out','transfer_in','transfer_out','adjustment','destruction'));
ALTER TABLE "inventory"."stock_balances" ADD CONSTRAINT "ck_stock_balances_nonnegative" CHECK (on_hand_quantity >= 0 AND inventory_value >= 0 AND average_unit_cost >= 0);
ALTER TABLE "inventory"."stock_balances" ADD CONSTRAINT "ck_stock_balances_value" CHECK ((on_hand_quantity=0 AND inventory_value=0) OR on_hand_quantity>0);

