-- Partial unique and access-path indexes
CREATE INDEX "units_of_measure_dimension_idx" ON "catalog"."units_of_measure" ("dimension", "name", "code") WHERE status = 'active';
CREATE INDEX "permissions_domain_action_idx" ON "core"."permissions" ("domain", "action", "code") WHERE status = 'active';
CREATE UNIQUE INDEX "users_auth_user_uq" ON "core"."users" ("auth_user_id") WHERE auth_user_id IS NOT NULL;
CREATE INDEX "users_status_idx" ON "core"."users" ("status", "id") WHERE status = 'active';
CREATE INDEX "memberships_active_user_idx" ON "core"."memberships" ("org_id", "user_id", "id") WHERE status = 'active';
CREATE UNIQUE INDEX "organizations_pan_uq" ON "core"."organizations" ("pan") WHERE pan IS NOT NULL;
