CREATE FUNCTION "erp_automation_commands"."guard_capability"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE grant_row automation.agent_grants%ROWTYPE;
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='agent capability consent cannot be deleted';
    END IF;
    IF TG_OP='INSERT' THEN
        SELECT * INTO grant_row FROM automation.agent_grants
         WHERE org_id=NEW.org_id AND id=NEW.agent_grant_id FOR SHARE;
        IF NOT FOUND OR grant_row.status<>'active'
           OR grant_row.expires_at<=pg_catalog.transaction_timestamp() THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='capability requires an active unexpired parent grant';
        END IF;
        IF NEW.status<>'active' OR pg_catalog.btrim(NEW.capability_code)='' THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='new capability must be a named active consent';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status='revoked' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='revoked capability consent is immutable';
    END IF;
    IF ROW(NEW.org_id,NEW.agent_grant_id,NEW.capability_code,NEW.operation_mode,
           NEW.risk_class,NEW.approval_policy,NEW.maximum_amount,NEW.currency_code,
           NEW.allow_sensitive_read,NEW.created_at,NEW.created_by_membership_id)
       IS DISTINCT FROM
       ROW(OLD.org_id,OLD.agent_grant_id,OLD.capability_code,OLD.operation_mode,
           OLD.risk_class,OLD.approval_policy,OLD.maximum_amount,OLD.currency_code,
           OLD.allow_sensitive_read,OLD.created_at,OLD.created_by_membership_id) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed capability consent bounds are immutable';
    END IF;
    IF OLD.status='active' AND NEW.status='revoked' THEN
        IF NEW.revoked_at IS NULL OR NEW.revoked_by_membership_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='capability revocation requires actor and timestamp evidence';
        END IF;
    ELSIF NEW.status IS DISTINCT FROM OLD.status
       OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at
       OR NEW.revoked_by_membership_id IS DISTINCT FROM OLD.revoked_by_membership_id THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invalid capability lifecycle transition';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_automation_commands"."guard_capability"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_automation_commands"."guard_capability"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "agent_grant_capabilities_consent_guard" BEFORE INSERT OR UPDATE OR DELETE ON "automation"."agent_grant_capabilities" FOR EACH ROW EXECUTE FUNCTION "erp_automation_commands"."guard_capability"();
-- Reviewed enforcement: automation.agent_grants:agent_grants_state_expiry_and_revocation
REVOKE ALL ON SCHEMA "erp_stable_invariants" FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_stable_invariants"."guard_agent_grant"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status NOT IN ('pending_consent','active') THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'new agent grant must be pending consent or validly active';
    END IF;
    IF TG_OP = 'UPDATE' AND (
       OLD.status = 'pending_consent' AND NEW.status NOT IN ('pending_consent','active','revoked','expired')
       OR OLD.status = 'active' AND NEW.status NOT IN ('active','suspended','revoked','expired')
       OR OLD.status = 'suspended' AND NEW.status NOT IN ('suspended','active','revoked','expired')
       OR OLD.status IN ('revoked','expired') AND NEW.status IS DISTINCT FROM OLD.status
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid agent grant lifecycle transition';
    END IF;
    IF NEW.status = 'active' AND (
        NEW.consented_by_membership_id IS DISTINCT FROM NEW.subject_membership_id
        OR NEW.consented_at IS NULL
        OR NEW.granted_by_membership_id IS NULL
        OR NEW.granted_at IS NULL
        OR NEW.expires_at <= pg_catalog.transaction_timestamp()
        OR (NEW.authorization_mode = 'admin_approved'
            AND NEW.granted_by_membership_id IS NOT DISTINCT FROM NEW.subject_membership_id)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'active agent grant lacks valid consent or administrator separation';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.status <> 'pending_consent' AND ROW(
        NEW.subject_membership_id, NEW.client_id, NEW.branch_id, NEW.authorization_mode,
        NEW.consent_version, NEW.consent_text_hash, NEW.consented_by_membership_id,
        NEW.consented_at, NEW.granted_by_membership_id, NEW.granted_at, NEW.expires_at
    ) IS DISTINCT FROM ROW(
        OLD.subject_membership_id, OLD.client_id, OLD.branch_id, OLD.authorization_mode,
        OLD.consent_version, OLD.consent_text_hash, OLD.consented_by_membership_id,
        OLD.consented_at, OLD.granted_by_membership_id, OLD.granted_at, OLD.expires_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'consented agent grant scope is immutable';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.status IN ('revoked','expired') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'terminal agent grant is immutable';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_stable_invariants"."guard_agent_grant"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_stable_invariants"."guard_agent_grant"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "agent_grants_state_guard_ct" AFTER INSERT OR UPDATE ON "automation"."agent_grants" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_stable_invariants"."guard_agent_grant"();
CREATE FUNCTION "erp_stable_invariants"."guard_agent_grant_execution"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    grant_row automation.agent_grants%ROWTYPE;
BEGIN
    IF NEW.status = 'executing'
       AND (CASE WHEN TG_OP = 'INSERT' THEN true ELSE OLD.status IS DISTINCT FROM 'executing' END) THEN
        SELECT * INTO grant_row
          FROM automation.agent_grants AS agent_grant
         WHERE agent_grant.org_id = NEW.org_id
           AND agent_grant.id = NEW.agent_grant_id
         FOR SHARE;
        IF NOT FOUND
           OR grant_row.status <> 'active'
           OR grant_row.expires_at <= pg_catalog.transaction_timestamp()
           OR grant_row.consented_by_membership_id IS DISTINCT FROM grant_row.subject_membership_id
           OR (grant_row.authorization_mode = 'admin_approved'
               AND grant_row.granted_by_membership_id IS NOT DISTINCT FROM grant_row.subject_membership_id) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'command execution requires an active unexpired consented agent grant';
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_stable_invariants"."guard_agent_grant_execution"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_stable_invariants"."guard_agent_grant_execution"() FROM PUBLIC, "erp_app", "erp_runtime";
