CREATE FUNCTION "erp_invariants_agent"."guard_command_approval_separation"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    request_row automation.command_requests%ROWTYPE;
