-- Reviewed enforcement: compliance.controlled_movement_rule_versions:controlled_movement_rule_versions_release_authority
CREATE FUNCTION "erp_regulatory_commands"."guard_controlled_movement_rule_version"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'active' OR NOT "erp_regulatory_commands"."scope_active"('reference_import',NEW.release_id) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='controlled_movement_rule_versions requires verified exact-set import provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deployed controlled_movement_rule_versions rows are retained'; END IF;
  IF ROW(NEW.id,NEW.release_id,NEW.rule_code,NEW.rule_version,NEW.drug_schedule,NEW.ndps_scope,NEW.entry_type,NEW.organization_license_type_code,NEW.counterparty_required,NEW.counterparty_license_type_code,NEW.prescription_evidence_required,NEW.authority_document_required,NEW.effective_from,NEW.effective_to,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.release_id,OLD.rule_code,OLD.rule_version,OLD.drug_schedule,OLD.ndps_scope,OLD.entry_type,OLD.organization_license_type_code,OLD.counterparty_required,OLD.counterparty_license_type_code,OLD.prescription_evidence_required,OLD.authority_document_required,OLD.effective_from,OLD.effective_to,OLD.created_at)
     OR OLD.status<>'active' OR NEW.status<>'retired'
     OR NOT "erp_regulatory_commands"."scope_active"('reference_import',OLD.release_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='controlled_movement_rule_versions authority is immutable';
  END IF;
  RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_regulatory_commands"."guard_controlled_movement_rule_version"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_regulatory_commands"."guard_controlled_movement_rule_version"() FROM PUBLIC, "erp_app", "erp_runtime", "erp_regulatory_importer";
CREATE TRIGGER "controlled_movement_rule_versions_release_guard" BEFORE INSERT OR UPDATE OR DELETE ON "compliance"."controlled_movement_rule_versions" FOR EACH ROW EXECUTE FUNCTION "erp_regulatory_commands"."guard_controlled_movement_rule_version"();
CREATE FUNCTION "erp_regulatory_commands"."import_controlled_movement_release"(p_release_id uuid, p_ruleset_version varchar, p_source_authority text, p_source_uri text, p_source_storage_bucket text, p_source_storage_object_path text, p_source_media_type varchar, p_source_bytes bytea, p_source_sha256 bytea, p_dataset_storage_bucket text, p_dataset_storage_object_path text, p_dataset_bytes bytea, p_dataset_sha256 bytea, p_publication_date date, p_effective_from date, p_effective_to date, p_reviewed_by_user_id uuid, p_reviewed_at timestamptz, p_request_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE prior_id uuid; item jsonb; supplied_count integer; dataset_rows jsonb;
BEGIN
  IF p_request_id IS NULL OR NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM p_request_id THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='controlled_movement_rules import requires matching transaction-local request id';
  END IF;
  dataset_rows:=pg_catalog.convert_from(p_dataset_bytes,'UTF8')::jsonb;
  prior_id:="erp_regulatory_commands"."stage_release"(p_release_id,'controlled_movement_rules',p_ruleset_version,
    p_source_authority,p_source_uri,p_source_storage_bucket,p_source_storage_object_path,
    p_source_media_type,p_source_bytes,p_source_sha256,p_dataset_storage_bucket,
    p_dataset_storage_object_path,p_dataset_bytes,p_dataset_sha256,p_publication_date,
    p_effective_from,p_effective_to,p_reviewed_by_user_id,p_reviewed_at);
  supplied_count:=pg_catalog.jsonb_array_length(dataset_rows);
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_array_elements(dataset_rows) AS row(value)
     WHERE pg_catalog.jsonb_typeof(value)<>'object'
        OR NOT value ?& ARRAY['id','rule_code','rule_version','drug_schedule','ndps_scope','entry_type','organization_license_type_code','counterparty_required','counterparty_license_type_code','prescription_evidence_required','authority_document_required','effective_from','effective_to']
        OR value - ARRAY['id','rule_code','rule_version','drug_schedule','ndps_scope','entry_type','organization_license_type_code','counterparty_required','counterparty_license_type_code','prescription_evidence_required','authority_document_required','effective_from','effective_to'] <> '{}'::jsonb
        OR pg_catalog.btrim(value->>'rule_code')=''
        OR pg_catalog.btrim(value->>'rule_version')=''
        OR (value->>'effective_from')::date<p_effective_from
        OR (p_effective_to IS NOT NULL AND COALESCE(NULLIF(value->>'effective_to','')::date,p_effective_to)>p_effective_to)
  ) OR (SELECT count(DISTINCT value->>'id') FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR (SELECT count(DISTINCT (value->>'rule_code',value->>'rule_version')) FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR EXISTS (
      SELECT 1
        FROM pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS left_row(value,ordinality)
        JOIN pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS right_row(value,ordinality)
          ON left_row.ordinality<right_row.ordinality
       WHERE left_row.value->>'drug_schedule'=right_row.value->>'drug_schedule' AND left_row.value->>'ndps_scope'=right_row.value->>'ndps_scope' AND left_row.value->>'entry_type'=right_row.value->>'entry_type'
         AND (left_row.value->>'effective_from')::date<=COALESCE(NULLIF(right_row.value->>'effective_to','')::date,'infinity'::date)
         AND (right_row.value->>'effective_from')::date<=COALESCE(NULLIF(left_row.value->>'effective_to','')::date,'infinity'::date)
    ) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='controlled_movement_rules dataset is not one exact non-overlapping typed set';
  END IF;
  IF prior_id IS NOT NULL THEN UPDATE compliance.controlled_movement_rule_versions SET status='retired' WHERE release_id=prior_id AND status='active'; END IF;
  FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(dataset_rows) ORDER BY value->>'id' LOOP
    INSERT INTO compliance.controlled_movement_rule_versions(id,release_id,rule_code,rule_version,drug_schedule,ndps_scope,entry_type,organization_license_type_code,counterparty_required,counterparty_license_type_code,prescription_evidence_required,authority_document_required,effective_from,effective_to,status) VALUES((item->>'id')::uuid,p_release_id,item->>'rule_code',item->>'rule_version',item->>'drug_schedule',item->>'ndps_scope',item->>'entry_type',item->>'organization_license_type_code',(item->>'counterparty_required')::boolean,NULLIF(item->>'counterparty_license_type_code',''),(item->>'prescription_evidence_required')::boolean,(item->>'authority_document_required')::boolean,(item->>'effective_from')::date,NULLIF(item->>'effective_to','')::date,'active');
  END LOOP;
  IF (SELECT count(*) FROM compliance.controlled_movement_rule_versions WHERE release_id=p_release_id)<>supplied_count THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='controlled_movement_rules exact-set count mismatch';
  END IF;
  PERFORM "erp_regulatory_commands"."finish_release"(p_release_id,prior_id);
  RETURN p_release_id;
END
$function$;
