CREATE FUNCTION "erp_compliance_commands"."post_recall_inventory_action"(organization_id uuid, document_id uuid, actor_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE document inventory.inventory_documents%ROWTYPE; recall compliance.recalls%ROWTYPE;
        claim_id uuid; replay_id uuid; bad_count bigint;
BEGIN
    PERFORM "erp_compliance_commands"."assert_context"(
      organization_id,actor_id,'compliance.recall.execute',NULL::uuid);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM "erp_compliance_commands"."claim"(
      organization_id,actor_id,'compliance.recall.action.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
    SELECT * INTO document FROM inventory.inventory_documents
     WHERE org_id=organization_id AND id=document_id FOR UPDATE;
    IF document.id IS NULL OR document.status<>'approved'
       OR document.document_type NOT IN ('recall_quarantine','recall_recovery','recall_release')
       OR document.recall_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved typed recall inventory action is required';
    END IF;
    PERFORM "erp_compliance_commands"."assert_context"(
      organization_id,actor_id,'inventory.document.post',document.branch_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(organization_id::text||':recall:'||document.recall_id::text,8164201));
    SELECT * INTO recall FROM compliance.recalls
     WHERE org_id=organization_id AND id=document.recall_id FOR UPDATE;
    SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
      LEFT JOIN compliance.recall_batches target ON target.org_id=line.org_id
        AND target.recall_id=document.recall_id AND target.batch_id=line.batch_id
      LEFT JOIN inventory.batches batch ON batch.org_id=line.org_id AND batch.id=line.batch_id
     WHERE line.org_id=organization_id AND line.inventory_document_id=document_id
       AND (target.batch_id IS NULL OR batch.product_id IS DISTINCT FROM recall.product_id);
    IF recall.status NOT IN ('initiated','in_progress') OR document.document_date<recall.initiated_on
       OR bad_count<>0 OR NOT EXISTS (SELECT 1 FROM inventory.inventory_document_lines line
          WHERE line.org_id=organization_id AND line.inventory_document_id=document_id) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='recall action lines require active recall batch provenance';
    END IF;
    PERFORM erp_trade_commands.post_locked_document(organization_id,document_id,actor_id);
    PERFORM "erp_compliance_commands"."refresh_recall_batches"(organization_id,document.recall_id);
    PERFORM "erp_compliance_commands"."finish_claim"(
      organization_id,claim_id,'inventory.inventory_documents',document_id);
    RETURN document_id;
END
$function$;
ALTER FUNCTION "erp_compliance_commands"."post_recall_inventory_action"(organization_id uuid, document_id uuid, actor_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_compliance_commands"."post_recall_inventory_action"(organization_id uuid, document_id uuid, actor_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_compliance_commands"."post_recall_inventory_action"(organization_id uuid, document_id uuid, actor_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz) TO "erp_app", "erp_runtime";
-- Reviewed enforcement: compliance.recalls:recalls_cross_row_guard
CREATE FUNCTION "erp_finance_invariants"."guard_recall"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='recall evidence is retained'; END IF;
    IF TG_OP='UPDATE' AND OLD.status IN ('closed','cancelled') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='terminal recall is immutable';
    END IF;
    IF NEW.status='closed' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'closed') AND (
       NOT EXISTS (SELECT 1 FROM compliance.recall_batches WHERE org_id=NEW.org_id AND recall_id=NEW.id)
       OR EXISTS (SELECT 1 FROM compliance.recall_batches WHERE org_id=NEW.org_id AND recall_id=NEW.id
            AND (status NOT IN ('recovered','destroyed','released')
                 OR recovered_quantity+destroyed_quantity+released_quantity<>affected_quantity))) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='recall cannot close before every batch is terminal and quantity-reconciled';
    END IF;
    IF NEW.status='cancelled' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'cancelled')
       AND EXISTS (SELECT 1 FROM compliance.recall_batches WHERE org_id=NEW.org_id AND recall_id=NEW.id
          AND (quarantined_quantity>0 OR recovered_quantity>0 OR destroyed_quantity>0)) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='acted-on recall cannot be cancelled';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_invariants"."guard_recall"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_invariants"."guard_recall"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "recalls_guard_ct" AFTER UPDATE OR DELETE ON "compliance"."recalls" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_invariants"."guard_recall"();
-- Reviewed enforcement: compliance.storage_rule_versions:storage_rule_versions_effective_guard
CREATE FUNCTION "erp_compliance_commands"."guard_storage_rule"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='reviewed storage rules are retained'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'active' OR NOT "erp_compliance_commands"."scope_active"('storage_rule_manage',NEW.org_id,NEW.id) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='storage rule requires reviewed command provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.org_id,NEW.id,NEW.subject_kind,NEW.product_id,NEW.location_id,NEW.minimum_celsius,
         NEW.maximum_celsius,NEW.minimum_humidity_percent,NEW.maximum_humidity_percent,
         NEW.effective_from,NEW.effective_to,NEW.evidence_attachment_id,NEW.reviewed_by_membership_id,
         NEW.reviewed_at,NEW.created_at,NEW.created_by_membership_id)
     IS DISTINCT FROM
     ROW(OLD.org_id,OLD.id,OLD.subject_kind,OLD.product_id,OLD.location_id,OLD.minimum_celsius,
         OLD.maximum_celsius,OLD.minimum_humidity_percent,OLD.maximum_humidity_percent,
         OLD.effective_from,OLD.effective_to,OLD.evidence_attachment_id,OLD.reviewed_by_membership_id,
         OLD.reviewed_at,OLD.created_at,OLD.created_by_membership_id)
     OR OLD.status<>'active' OR NEW.status<>'retired'
     OR NOT "erp_compliance_commands"."scope_active"('storage_rule_manage',OLD.org_id,OLD.id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='storage rule may only be retired by reviewed supersession';
  END IF;
  RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_compliance_commands"."guard_storage_rule"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_compliance_commands"."guard_storage_rule"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "storage_rule_versions_command_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "compliance"."storage_rule_versions" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_compliance_commands"."guard_storage_rule"();
CREATE FUNCTION "erp_compliance_commands"."activate_storage_rule"(organization_id uuid, rule_id uuid, actor_id uuid, reviewed_by_membership_id uuid, subject_kind text, product_id uuid, location_id uuid, minimum_celsius numeric, maximum_celsius numeric, minimum_humidity_percent numeric, maximum_humidity_percent numeric, effective_from date, effective_to date, evidence_attachment_id uuid, reviewed_at timestamptz, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE claim_id uuid; replay_id uuid; prior_id uuid;
BEGIN
  PERFORM "erp_compliance_commands"."assert_context"(organization_id,actor_id,'compliance.license.manage',NULL::uuid);
  SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM "erp_compliance_commands"."claim"(
    organization_id,actor_id,'compliance.storage_rule.activate',key_hash,request_hash,expires_at);
  IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
  IF actor_id=reviewed_by_membership_id OR reviewed_at>pg_catalog.transaction_timestamp()
     OR NOT EXISTS (SELECT 1 FROM core.memberships WHERE org_id=organization_id
          AND id=reviewed_by_membership_id AND status='active')
     OR NOT EXISTS (SELECT 1 FROM core.attachments WHERE org_id=organization_id
          AND id=evidence_attachment_id AND status IN ('verified','retained')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='storage rule requires retained evidence and distinct active reviewer';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    organization_id::text||':'||subject_kind||':'||COALESCE(product_id,location_id)::text,8164201));
  SELECT rule_row.id INTO prior_id FROM compliance.storage_rule_versions AS rule_row
   WHERE rule_row.org_id=organization_id AND rule_row.status='active'
     AND rule_row.product_id IS NOT DISTINCT FROM product_id
     AND rule_row.location_id IS NOT DISTINCT FROM location_id
     AND rule_row.effective_from<=COALESCE(effective_to,'infinity'::date)
     AND effective_from<=COALESCE(rule_row.effective_to,'infinity'::date)
   ORDER BY rule_row.effective_from DESC LIMIT 1 FOR UPDATE;
  INSERT INTO "erp_compliance_commands"."command_scopes" VALUES
    (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'storage_rule_manage',organization_id,rule_id);
  IF prior_id IS NOT NULL THEN
    INSERT INTO "erp_compliance_commands"."command_scopes" VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'storage_rule_manage',organization_id,prior_id);
    UPDATE compliance.storage_rule_versions SET status='retired' WHERE org_id=organization_id AND id=prior_id;
  END IF;
  INSERT INTO compliance.storage_rule_versions(org_id,id,subject_kind,product_id,location_id,
    minimum_celsius,maximum_celsius,minimum_humidity_percent,maximum_humidity_percent,
    effective_from,effective_to,evidence_attachment_id,reviewed_by_membership_id,reviewed_at,
    status,created_by_membership_id)
  VALUES(organization_id,rule_id,subject_kind,product_id,location_id,minimum_celsius,maximum_celsius,
    minimum_humidity_percent,maximum_humidity_percent,effective_from,effective_to,evidence_attachment_id,
    reviewed_by_membership_id,reviewed_at,'active',actor_id);
  DELETE FROM "erp_compliance_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
    AND transaction_id=pg_catalog.txid_current() AND scope='storage_rule_manage' AND org_id=organization_id;
  PERFORM "erp_compliance_commands"."finish_claim"(organization_id,claim_id,'compliance.storage_rule_versions',rule_id);
  RETURN rule_id;
END
$function$;
ALTER FUNCTION "erp_compliance_commands"."activate_storage_rule"(organization_id uuid, rule_id uuid, actor_id uuid, reviewed_by_membership_id uuid, subject_kind text, product_id uuid, location_id uuid, minimum_celsius numeric, maximum_celsius numeric, minimum_humidity_percent numeric, maximum_humidity_percent numeric, effective_from date, effective_to date, evidence_attachment_id uuid, reviewed_at timestamptz, key_hash bytea, request_hash bytea, expires_at timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_compliance_commands"."activate_storage_rule"(organization_id uuid, rule_id uuid, actor_id uuid, reviewed_by_membership_id uuid, subject_kind text, product_id uuid, location_id uuid, minimum_celsius numeric, maximum_celsius numeric, minimum_humidity_percent numeric, maximum_humidity_percent numeric, effective_from date, effective_to date, evidence_attachment_id uuid, reviewed_at timestamptz, key_hash bytea, request_hash bytea, expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
