REVOKE ALL ON FUNCTION "erp_core_commands"."allocate_document_number"(organization_id uuid, sequence_id uuid, idempotency_key_hash bytea, idempotency_expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
