-- Reviewed enforcement: core.settings:settings_state_transition
CREATE FUNCTION "erp_core_commands"."guard_setting"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='setting versions cannot be deleted'; END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.status<>'active' THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='new setting version must start active';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='UPDATE' THEN
        IF OLD.status='retired' AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='retired setting version is immutable';
        END IF;
        IF OLD.status='active' AND NEW.status NOT IN ('active','retired') THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invalid setting lifecycle transition';
        END IF;
        IF ROW(NEW.org_id,NEW.id,NEW.scope_kind,NEW.branch_id,NEW.namespace,NEW.key,NEW.value_type,
               NEW.value_text,NEW.value_numeric,NEW.value_boolean,NEW.value_date,NEW.value_timestamptz,
               NEW.created_at,NEW.created_by_membership_id)
           IS DISTINCT FROM
           ROW(OLD.org_id,OLD.id,OLD.scope_kind,OLD.branch_id,OLD.namespace,OLD.key,OLD.value_type,
               OLD.value_text,OLD.value_numeric,OLD.value_boolean,OLD.value_date,OLD.value_timestamptz,
               OLD.created_at,OLD.created_by_membership_id) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='setting values are replaced by a new version, never updated in place';
        END IF;
        IF NEW.status='retired' AND OLD.status='active'
           AND NOT "erp_core_commands"."scope_active"('setting_replace',NEW.org_id,NEW.id) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='setting retirement requires atomic replacement command lineage';
        END IF;
        IF NEW.row_version<>OLD.row_version+1 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='setting row version must advance exactly once';
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_core_commands"."guard_setting"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_core_commands"."guard_setting"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "settings_version_guard" BEFORE INSERT OR UPDATE OR DELETE ON "core"."settings" FOR EACH ROW EXECUTE FUNCTION "erp_core_commands"."guard_setting"();
CREATE FUNCTION "erp_core_commands"."replace_setting"(organization_id uuid, setting_id uuid, replacement_id uuid, expected_row_version bigint, value_type text, value_text text, value_numeric numeric, value_boolean boolean, value_date date, value_timestamptz timestamptz, idempotency_key_hash bytea, idempotency_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE actor_id uuid; source core.settings%ROWTYPE; claim core.idempotency_keys%ROWTYPE;
        request_document jsonb; response_document jsonb;
BEGIN
    actor_id := "erp_core_commands"."assert_context"(organization_id,NULL,NULL::uuid);
    SELECT * INTO source FROM core.settings WHERE org_id=organization_id AND id=setting_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='setting version not found'; END IF;
    PERFORM "erp_core_commands"."assert_context"(organization_id,'core.settings.manage',source.branch_id);
    request_document := pg_catalog.jsonb_build_object(
      'operation','core.setting.replace','organization_id',organization_id,'setting_id',setting_id,
      'replacement_id',replacement_id,'expected_row_version',expected_row_version,'value_type',value_type,
      'value_text',value_text,'value_numeric',value_numeric,'value_boolean',value_boolean,
      'value_date',value_date,'value_timestamptz',value_timestamptz
    );
    claim := "erp_core_commands"."claim"(organization_id,actor_id,'core.setting.replace',idempotency_key_hash,
      request_document,idempotency_expires_at);
    IF claim.status='succeeded' THEN RETURN claim.resource_id; END IF;
    IF source.status<>'active' OR expected_row_version IS NULL
       OR source.row_version<>expected_row_version OR replacement_id=setting_id
       OR pg_catalog.num_nonnulls(value_text,value_numeric,value_boolean,value_date,value_timestamptz)<>1
       OR NOT ((value_type='text')=(value_text IS NOT NULL)
           AND (value_type='numeric')=(value_numeric IS NOT NULL)
           AND (value_type='boolean')=(value_boolean IS NOT NULL)
           AND (value_type='date')=(value_date IS NOT NULL)
           AND (value_type='timestamptz')=(value_timestamptz IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='setting replacement version or typed value is invalid';
    END IF;
    INSERT INTO "erp_core_commands"."command_scopes" VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'setting_replace',organization_id,setting_id);
    UPDATE core.settings SET status='retired',updated_at=pg_catalog.transaction_timestamp(),
      updated_by_membership_id=actor_id,row_version=row_version+1
      WHERE org_id=organization_id AND id=setting_id AND status='active' AND row_version=expected_row_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='setting version changed before replacement';
    END IF;
    INSERT INTO core.settings(org_id,id,scope_kind,branch_id,namespace,key,value_type,value_text,
      value_numeric,value_boolean,value_date,value_timestamptz,created_by_membership_id,
      updated_by_membership_id)
    VALUES(organization_id,replacement_id,source.scope_kind,source.branch_id,source.namespace,source.key,
      value_type,value_text,value_numeric,value_boolean,value_date,value_timestamptz,actor_id,actor_id);
    DELETE FROM "erp_core_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
      AND transaction_id=pg_catalog.txid_current() AND scope='setting_replace'
      AND org_id=organization_id AND entity_id=setting_id;
    response_document := pg_catalog.jsonb_build_object('setting_id',replacement_id,'replaces_setting_id',setting_id);
    PERFORM "erp_core_commands"."finish_claim"(organization_id,claim.id,'core.settings',replacement_id,response_document);
    RETURN replacement_id;
END
$function$;
ALTER FUNCTION "erp_core_commands"."replace_setting"(organization_id uuid, setting_id uuid, replacement_id uuid, expected_row_version bigint, value_type text, value_text text, value_numeric numeric, value_boolean boolean, value_date date, value_timestamptz timestamptz, idempotency_key_hash bytea, idempotency_expires_at timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_core_commands"."replace_setting"(organization_id uuid, setting_id uuid, replacement_id uuid, expected_row_version bigint, value_type text, value_text text, value_numeric numeric, value_boolean boolean, value_date date, value_timestamptz timestamptz, idempotency_key_hash bytea, idempotency_expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_core_commands"."replace_setting"(organization_id uuid, setting_id uuid, replacement_id uuid, expected_row_version bigint, value_type text, value_text text, value_numeric numeric, value_boolean boolean, value_date date, value_timestamptz timestamptz, idempotency_key_hash bytea, idempotency_expires_at timestamptz) TO "erp_app";
-- Reviewed enforcement: core.users:users_state_transition
CREATE FUNCTION "erp_stable_invariants"."guard_user_transition"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
BEGIN
    IF OLD.status = 'active' AND NEW.status NOT IN ('active','disabled','anonymized')
       OR OLD.status = 'disabled' AND NEW.status NOT IN ('disabled','active','anonymized')
       OR OLD.status = 'anonymized' AND NEW.status IS DISTINCT FROM 'anonymized' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid user lifecycle transition';
    END IF;
    IF NEW.status = 'anonymized' AND NEW.auth_user_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'anonymized user cannot remain mapped to Auth';
    END IF;
    IF OLD.status = 'anonymized' AND NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'anonymized user cannot be remapped to Auth';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_stable_invariants"."guard_user_transition"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_stable_invariants"."guard_user_transition"() FROM PUBLIC, "erp_app", "erp_runtime";
