BEGIN
    RETURN EXISTS (
        SELECT 1 FROM "erp_finance_commands"."command_scopes" AS token
         WHERE token.backend_pid=pg_catalog.pg_backend_pid()
           AND token.transaction_id=pg_catalog.txid_current()
           AND token.scope=requested_scope
