REVOKE ALL ON FUNCTION "erp_compliance_commands"."post_expense_claim"(organization_id uuid, expense_claim_id uuid, journal_entry_id uuid, accounting_event_id uuid, actor_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
