-- Reviewed enforcement: finance.journal_entries:journal_entries_cross_row_guard
CREATE FUNCTION "erp_finance_invariants"."guard_journal_entry"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE line_count bigint; td numeric(20,2); tc numeric(20,2); fd numeric(20,2); fc numeric(20,2); original finance.journal_entries%ROWTYPE;
BEGIN
    IF TG_OP='INSERT' AND NEW.status<>'draft' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='journal must be composed from draft';
    END IF;
    IF TG_OP = 'DELETE' AND OLD.status <> 'draft' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'non-draft journal is immutable';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    IF TG_OP = 'UPDATE' AND OLD.status IN ('posted','reversed','cancelled') AND ROW(
       NEW.journal_number,NEW.posting_date,NEW.transaction_currency,NEW.functional_currency,NEW.fx_rate,
       NEW.transaction_debit_total,NEW.transaction_credit_total,NEW.functional_debit_total,
       NEW.functional_credit_total,NEW.reversal_of_journal_entry_id,NEW.posted_at,NEW.posted_by_membership_id
    ) IS DISTINCT FROM ROW(
       OLD.journal_number,OLD.posting_date,OLD.transaction_currency,OLD.functional_currency,OLD.fx_rate,
       OLD.transaction_debit_total,OLD.transaction_credit_total,OLD.functional_debit_total,
       OLD.functional_credit_total,OLD.reversal_of_journal_entry_id,OLD.posted_at,OLD.posted_by_membership_id
    ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted journal financial fields are immutable'; END IF;
    IF TG_OP='UPDATE' AND ((OLD.status='draft' AND NEW.status NOT IN ('draft','posted','cancelled'))
       OR (OLD.status='posted' AND NEW.status NOT IN ('posted','reversed'))
       OR (OLD.status IN ('reversed','cancelled') AND NEW.status<>OLD.status)) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invalid journal lifecycle transition';
    END IF;
    IF NEW.status = 'posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted') THEN
        SELECT count(*),coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0),
               coalesce(sum(functional_debit),0),coalesce(sum(functional_credit),0)
          INTO line_count,td,tc,fd,fc FROM finance.journal_lines
         WHERE org_id=NEW.org_id AND journal_entry_id=NEW.id;
        IF line_count < 2 OR ROW(td,tc,fd,fc) IS DISTINCT FROM ROW(NEW.transaction_debit_total,
           NEW.transaction_credit_total,NEW.functional_debit_total,NEW.functional_credit_total)
           OR td<>tc OR fd<>fc OR EXISTS (
             SELECT 1 FROM finance.journal_lines WHERE org_id=NEW.org_id AND journal_entry_id=NEW.id
              AND (functional_debit<>round(transaction_debit*NEW.fx_rate,2)
                   OR functional_credit<>round(transaction_credit*NEW.fx_rate,2))) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='journal lines do not exactly balance and reconcile to header/fx';
        END IF;
        IF NEW.reversal_of_journal_entry_id IS NOT NULL THEN
            SELECT * INTO original FROM finance.journal_entries WHERE org_id=NEW.org_id AND id=NEW.reversal_of_journal_entry_id FOR UPDATE;
            IF NOT FOUND OR original.status<>'posted' OR original.transaction_currency<>NEW.transaction_currency
               OR original.functional_currency<>NEW.functional_currency OR original.fx_rate<>NEW.fx_rate
               OR EXISTS (SELECT 1 FROM finance.journal_lines AS old_line FULL JOIN finance.journal_lines AS new_line
                    ON new_line.org_id=NEW.org_id AND new_line.journal_entry_id=NEW.id AND new_line.line_number=old_line.line_number
                   WHERE old_line.org_id=NEW.org_id AND old_line.journal_entry_id=original.id
                     AND (new_line.id IS NULL OR ROW(new_line.account_id,new_line.branch_id,new_line.party_id,new_line.transaction_debit,new_line.transaction_credit,new_line.functional_debit,new_line.functional_credit)
                       IS DISTINCT FROM ROW(old_line.account_id,old_line.branch_id,old_line.party_id,old_line.transaction_credit,old_line.transaction_debit,old_line.functional_credit,old_line.functional_debit)))
               OR (SELECT count(*) FROM finance.journal_lines WHERE org_id=NEW.org_id AND journal_entry_id=NEW.id)
                  <> (SELECT count(*) FROM finance.journal_lines WHERE org_id=NEW.org_id AND journal_entry_id=original.id) THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='journal reversal is not an exact sign inversion';
            END IF;
            UPDATE finance.journal_entries SET status='reversed' WHERE org_id=original.org_id AND id=original.id;
        END IF;
    END IF;
    IF TG_OP='UPDATE' AND NEW.status='reversed' AND OLD.status<>'reversed'
       AND NOT EXISTS (SELECT 1 FROM finance.journal_entries AS reversal WHERE reversal.org_id=NEW.org_id
                        AND reversal.reversal_of_journal_entry_id=NEW.id AND reversal.status='posted') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='journal can be reversed only by a posted compensating journal';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_invariants"."guard_journal_entry"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_invariants"."guard_journal_entry"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "journal_entries_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "finance"."journal_entries" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_invariants"."guard_journal_entry"();
-- Reviewed enforcement: finance.journal_lines:journal_lines_cross_row_guard
CREATE FUNCTION "erp_finance_invariants"."guard_journal_line"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_status text;
BEGIN
    SELECT status INTO parent_status FROM finance.journal_entries
     WHERE org_id=COALESCE(NEW.org_id,OLD.org_id) AND id=COALESCE(NEW.journal_entry_id,OLD.journal_entry_id) FOR UPDATE;
    IF NOT FOUND AND TG_OP='DELETE' THEN RETURN OLD; END IF;
    IF parent_status IS DISTINCT FROM 'draft' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='journal lines may change only while parent is draft';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_invariants"."guard_journal_line"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_invariants"."guard_journal_line"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "journal_lines_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "finance"."journal_lines" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_invariants"."guard_journal_line"();
-- Reviewed enforcement: finance.open_items:open_items_cross_row_guard
CREATE FUNCTION "erp_finance_invariants"."guard_open_item"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE allocated numeric(20,2); event_journal_status text;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='open items are retained'; END IF;
    IF TG_OP='INSERT' AND (NEW.status<>'open' OR NEW.settled_at IS NOT NULL OR NEW.reversed_at IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='new open item must start open';
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.accounting_event_id,NEW.party_id,NEW.item_side,NEW.currency_code,
       NEW.principal_amount,NEW.functional_principal_amount) IS DISTINCT FROM ROW(OLD.accounting_event_id,
       OLD.party_id,OLD.item_side,OLD.currency_code,OLD.principal_amount,OLD.functional_principal_amount) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='open item financial facts are immutable';
    END IF;
    SELECT coalesce(sum(a.amount),0) INTO allocated FROM finance.allocations AS a
     WHERE a.org_id=NEW.org_id AND a.open_item_id=NEW.id AND a.status='posted'
       AND NOT EXISTS (SELECT 1 FROM finance.allocations AS r WHERE r.org_id=a.org_id AND r.reversal_of_allocation_id=a.id);
    IF allocated>NEW.principal_amount OR (NEW.status='settled') IS DISTINCT FROM (allocated=NEW.principal_amount) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='open item status does not match active allocation total';
    END IF;
    IF NEW.status='reversed' THEN
        SELECT journal.status INTO event_journal_status FROM finance.accounting_events AS event
        JOIN finance.journal_entries AS journal ON journal.org_id=event.org_id AND journal.id=event.journal_entry_id
        WHERE event.org_id=NEW.org_id AND event.id=NEW.accounting_event_id;
        IF event_journal_status IS DISTINCT FROM 'reversed' THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='open item reversal requires a reversed source journal';
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_invariants"."guard_open_item"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_invariants"."guard_open_item"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "open_items_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "finance"."open_items" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_invariants"."guard_open_item"();
-- Reviewed enforcement: finance.payments:payments_cross_row_guard
CREATE FUNCTION "erp_finance_commands"."guard_payment_command"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
    IF TG_OP='DELETE' AND OLD.status<>'draft' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='non-draft payment evidence is retained';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    IF TG_OP='UPDATE' AND OLD.status IN ('posted','reversed') AND ROW(
       NEW.payment_number,NEW.payment_date,NEW.direction,NEW.party_id,NEW.branch_id,
       NEW.bank_account_id,NEW.settlement_account_id,
       NEW.payment_method,NEW.currency_code,NEW.amount,NEW.functional_amount,NEW.fx_rate,
       NEW.external_reference,NEW.reversal_of_payment_id,NEW.reversal_reason,
       NEW.approved_at,NEW.approved_by_membership_id,NEW.posted_at,NEW.posted_by_membership_id
    ) IS DISTINCT FROM ROW(
       OLD.payment_number,OLD.payment_date,OLD.direction,OLD.party_id,OLD.branch_id,
       OLD.bank_account_id,OLD.settlement_account_id,
       OLD.payment_method,OLD.currency_code,OLD.amount,OLD.functional_amount,OLD.fx_rate,
       OLD.external_reference,OLD.reversal_of_payment_id,OLD.reversal_reason,
       OLD.approved_at,OLD.approved_by_membership_id,OLD.posted_at,OLD.posted_by_membership_id
    ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted payment facts are immutable'; END IF;
    IF TG_OP='UPDATE' AND NEW.status IN ('posted','reversed') AND NEW.status IS DISTINCT FROM OLD.status
       AND NOT "erp_finance_commands"."scope_active"('payment',NEW.org_id,NEW.id) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='payment posting and reversal require the reviewed command';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_commands"."guard_payment_command"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_commands"."guard_payment_command"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "payments_command_guard_ct" AFTER UPDATE OR DELETE ON "finance"."payments" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_commands"."guard_payment_command"();
CREATE FUNCTION "erp_finance_commands"."post_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE payment finance.payments%ROWTYPE; journal finance.journal_entries%ROWTYPE;
        settlement finance.accounts%ROWTYPE; bank finance.bank_accounts%ROWTYPE;
        actor uuid; posted_time timestamptz; existing_event uuid; settlement_line_count integer;
BEGIN
    IF organization_id IS DISTINCT FROM erp_security.current_org_id() THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='payment posting permission denied';
    END IF;
    actor:=erp_security.current_membership_id();
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||payment_id::text,672001));
    SELECT * INTO payment FROM finance.payments WHERE org_id=organization_id AND id=payment_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='payment not found'; END IF;
    SELECT id INTO existing_event FROM finance.accounting_events WHERE org_id=organization_id AND payment_id=payment_id;
    IF payment.status='posted' AND existing_event=event_id THEN RETURN payment_id; END IF;
    IF payment.status<>'approved' OR payment.reversal_of_payment_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='only an approved original payment may be posted';
    END IF;
    IF NOT erp_security.can_access_branch(payment.branch_id)
       OR NOT erp_security.has_permission('finance.payment.manage',payment.branch_id)
       OR NOT erp_security.has_permission('finance.journal.post',payment.branch_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='payment branch permission denied';
    END IF;
    SELECT * INTO settlement FROM finance.accounts
     WHERE org_id=organization_id AND id=payment.settlement_account_id FOR SHARE;
    IF settlement.id IS NULL OR settlement.status<>'active' OR settlement.account_type<>'asset'
       OR settlement.currency_code<>payment.currency_code THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='payment settlement account must be an active matching-currency asset';
    END IF;
    IF payment.payment_method='cash' THEN
      IF payment.bank_account_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cash payment cannot reference a bank account';
      END IF;
    ELSE
      SELECT * INTO bank FROM finance.bank_accounts
       WHERE org_id=organization_id AND id=payment.bank_account_id FOR SHARE;
      IF bank.id IS NULL OR bank.status<>'active' OR bank.account_id<>settlement.id
         OR bank.currency_code<>payment.currency_code THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='non-cash payment bank identity must own the settlement account';
      END IF;
    END IF;
    IF payment.payment_purpose='supplier_advance'
       AND NOT "erp_finance_commands"."scope_active"('supplier_advance_payment',organization_id,payment_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='supplier advance must use the typed gross-advance posting command';
    END IF;
    SELECT * INTO journal FROM finance.journal_entries WHERE org_id=organization_id AND id=journal_id FOR UPDATE;
    IF NOT FOUND OR journal.status<>'draft' OR journal.reversal_of_journal_entry_id IS NOT NULL
       OR journal.transaction_currency<>payment.currency_code
       OR journal.transaction_debit_total<>payment.amount
       OR journal.functional_debit_total<>payment.functional_amount THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='payment journal does not exactly match payment amounts';
    END IF;
    SELECT count(*) INTO settlement_line_count FROM finance.journal_lines line
     WHERE line.org_id=organization_id AND line.journal_entry_id=journal_id
       AND line.branch_id=payment.branch_id AND line.account_id=payment.settlement_account_id
       AND ((payment.direction='receipt' AND line.transaction_debit=payment.amount
             AND line.transaction_credit=0 AND line.functional_debit=payment.functional_amount
             AND line.functional_credit=0)
         OR (payment.direction='disbursement' AND line.transaction_credit=payment.amount
             AND line.transaction_debit=0 AND line.functional_credit=payment.functional_amount
             AND line.functional_debit=0));
    IF settlement_line_count<>1 OR EXISTS(
      SELECT 1 FROM finance.journal_lines line
       WHERE line.org_id=organization_id AND line.journal_entry_id=journal_id
         AND line.branch_id<>payment.branch_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='payment journal settlement line or branch does not match payment';
    END IF;
    posted_time:=pg_catalog.transaction_timestamp();
    INSERT INTO "erp_finance_commands"."command_scopes" VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'payment',organization_id,payment_id);
    UPDATE finance.journal_entries SET status='posted',posted_at=posted_time,posted_by_membership_id=actor,
           updated_at=posted_time,updated_by_membership_id=actor,row_version=row_version+1
     WHERE org_id=organization_id AND id=journal_id;
    UPDATE finance.payments SET status='posted',posted_at=posted_time,posted_by_membership_id=actor,
           updated_at=posted_time,updated_by_membership_id=actor,row_version=row_version+1
     WHERE org_id=organization_id AND id=payment_id;
    INSERT INTO finance.accounting_events(org_id,id,event_type,payment_id,journal_entry_id,
        occurred_at,source_posted_at,created_by_membership_id)
      VALUES(organization_id,event_id,'payment',payment_id,journal_id,posted_time,posted_time,actor);
    DELETE FROM "erp_finance_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
      AND transaction_id=pg_catalog.txid_current() AND scope='payment' AND org_id=organization_id AND entity_id=payment_id;
    RETURN payment_id;
END
$function$;
ALTER FUNCTION "erp_finance_commands"."post_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_commands"."post_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_finance_commands"."post_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid) TO "erp_app";
CREATE FUNCTION "erp_finance_commands"."post_supplier_advance_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid, advance_allocations jsonb)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE payment finance.payments%ROWTYPE; item jsonb; actor uuid; allocated numeric(20,2):=0;
        line_payload_gross numeric(20,2); existing_line_gross numeric(20,2);
        line procurement.purchase_order_lines%ROWTYPE; purchase_order procurement.purchase_orders%ROWTYPE;
        supplier parties.supplier_accounts%ROWTYPE;
BEGIN
    IF pg_catalog.jsonb_typeof(advance_allocations)<>'array' OR pg_catalog.jsonb_array_length(advance_allocations)=0 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='typed supplier advance allocations are required';
    END IF;
    actor:=erp_security.current_membership_id();
    SELECT * INTO payment FROM finance.payments WHERE org_id=organization_id AND id=payment_id FOR UPDATE;
    IF payment.status<>'approved' OR payment.direction<>'disbursement' OR payment.currency_code<>'INR'
       OR payment.payment_purpose<>'supplier_advance' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier advance requires approved INR disbursement';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      organization_id::text||':supplier-advance-line:'||ordered.line_id::text,672004))
      FROM (SELECT DISTINCT (payload.value->>'purchase_order_line_id')::uuid AS line_id
              FROM pg_catalog.jsonb_array_elements(advance_allocations) payload(value)
             ORDER BY line_id) ordered;
    FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(advance_allocations) LOOP
      SELECT * INTO line FROM procurement.purchase_order_lines WHERE org_id=organization_id AND id=(item->>'purchase_order_line_id')::uuid FOR SHARE;
      SELECT * INTO purchase_order FROM procurement.purchase_orders WHERE org_id=organization_id AND id=line.purchase_order_id FOR SHARE;
      SELECT * INTO supplier FROM parties.supplier_accounts WHERE org_id=organization_id AND id=purchase_order.supplier_account_id FOR SHARE;
      SELECT coalesce(sum((payload.value->>'gross_advance_amount')::numeric),0) INTO line_payload_gross
       FROM pg_catalog.jsonb_array_elements(advance_allocations) payload(value)
       WHERE (payload.value->>'purchase_order_line_id')::uuid=line.id;
      SELECT coalesce(sum(prior.gross_advance_amount),0) INTO existing_line_gross
       FROM procurement.purchase_order_advance_allocations prior
       WHERE prior.org_id=organization_id AND prior.purchase_order_line_id=line.id AND prior.status='posted'
         AND NOT EXISTS(SELECT 1 FROM procurement.purchase_order_advance_allocations reversal
           WHERE reversal.org_id=prior.org_id AND reversal.reversal_of_allocation_id=prior.id);
      IF line.line_kind<>'product' OR purchase_order.status NOT IN ('approved','partially_received','received')
        OR purchase_order.branch_id<>payment.branch_id
        OR supplier.party_id<>payment.party_id OR (item->>'cash_disbursed_amount')::numeric<=0
        OR (item->>'gross_advance_amount')::numeric<(item->>'cash_disbursed_amount')::numeric
        OR existing_line_gross+line_payload_gross>line.net_value_amount THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='advance allocation must reference approved pharma-goods PO line for payment supplier';
      END IF;
      allocated:=allocated+(item->>'cash_disbursed_amount')::numeric;
    END LOOP;
    IF allocated<>payment.amount THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='advance allocations must equal payment'; END IF;
    INSERT INTO "erp_finance_commands"."command_scopes" VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'supplier_advance_payment',organization_id,payment_id);
    PERFORM "erp_finance_commands"."post_payment"(organization_id,payment_id,journal_id,event_id);
    FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(advance_allocations) LOOP
      SELECT * INTO line FROM procurement.purchase_order_lines WHERE org_id=organization_id AND id=(item->>'purchase_order_line_id')::uuid;
      SELECT * INTO purchase_order FROM procurement.purchase_orders WHERE org_id=organization_id AND id=line.purchase_order_id;
      INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,
        document_date,due_date,currency_code,principal_amount,functional_principal_amount,created_by_membership_id)
      VALUES(organization_id,(item->>'prepayment_open_item_id')::uuid,event_id,payment.party_id,'receivable',
        payment.payment_number,payment.payment_date,payment.payment_date,'INR',(item->>'gross_advance_amount')::numeric,
        (item->>'gross_advance_amount')::numeric,actor);
      INSERT INTO procurement.purchase_order_advance_allocations(org_id,id,payment_id,purchase_order_line_id,
        supplier_account_id,branch_id,cash_disbursed_amount,withheld_amount,gross_advance_amount,
        functional_gross_advance_amount,allocation_date,prepayment_open_item_id,withholding_id,created_by_membership_id)
      VALUES(organization_id,(item->>'id')::uuid,payment_id,line.id,purchase_order.supplier_account_id,
        purchase_order.branch_id,(item->>'cash_disbursed_amount')::numeric,
        coalesce((item->>'withheld_amount')::numeric,0),(item->>'gross_advance_amount')::numeric,
        (item->>'gross_advance_amount')::numeric,payment.payment_date,
        (item->>'prepayment_open_item_id')::uuid,(item->>'withholding_id')::uuid,actor);
      IF coalesce((item->>'withheld_amount')::numeric,0)>0 THEN
        PERFORM erp_compliance_commands.post_withholding(
          organization_id,(item->>'withholding_id')::uuid,actor,NULL::uuid,(item->>'id')::uuid,
          (item->>'withholding_journal_id')::uuid,(item->>'withholding_event_id')::uuid,NULL::uuid,
          pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'id',item->>'withholding_basis_line_id','purchase_order_advance_allocation_id',item->>'id')),
          pg_catalog.decode(item->>'withholding_key_hash','hex'),
          pg_catalog.decode(item->>'withholding_request_hash','hex'),
          (item->>'withholding_expires_at')::timestamptz);
      ELSE
        PERFORM erp_compliance_commands.assert_no_advance_withholding_required(
          organization_id,(item->>'id')::uuid);
      END IF;
    END LOOP;
    DELETE FROM "erp_finance_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
      AND transaction_id=pg_catalog.txid_current() AND scope='supplier_advance_payment'
      AND org_id=organization_id AND entity_id=payment_id;
    RETURN payment_id;
END
$function$;
ALTER FUNCTION "erp_finance_commands"."post_supplier_advance_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid, advance_allocations jsonb) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_commands"."post_supplier_advance_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid, advance_allocations jsonb) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_finance_commands"."post_supplier_advance_payment"(organization_id uuid, payment_id uuid, journal_id uuid, event_id uuid, advance_allocations jsonb) TO "erp_app";
CREATE FUNCTION "erp_finance_commands"."reverse_payment"(organization_id uuid, original_payment_id uuid, reversal_payment_id uuid, reversal_payment_number varchar, reversal_journal_id uuid, reversal_journal_number varchar, reversal_event_id uuid, reason text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE original finance.payments%ROWTYPE; original_journal finance.journal_entries%ROWTYPE;
        actor uuid; reversed_time timestamptz; existing uuid; advance record;
        reversal_withholding_id uuid; reversal_open_item_id uuid;
BEGIN
    IF organization_id IS DISTINCT FROM erp_security.current_org_id()
       OR reason IS NULL OR pg_catalog.btrim(reason)='' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='payment reversal permission or reason missing';
    END IF;
    actor:=erp_security.current_membership_id();
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||original_payment_id::text,672002));
    SELECT * INTO original FROM finance.payments WHERE org_id=organization_id AND id=original_payment_id FOR UPDATE;
    SELECT id INTO existing FROM finance.payments WHERE org_id=organization_id AND reversal_of_payment_id=original_payment_id;
    IF existing=reversal_payment_id AND original.status='reversed' THEN RETURN reversal_payment_id; END IF;
    IF original.status<>'posted' OR original.reversal_of_payment_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='only an unreversed posted payment may be reversed';
    END IF;
    IF NOT erp_security.can_access_branch(original.branch_id)
       OR NOT erp_security.has_permission('finance.payment.manage',original.branch_id)
       OR NOT erp_security.has_permission('finance.journal.post',original.branch_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='payment reversal branch permission denied';
    END IF;
    IF original.payment_purpose='withholding_deposit' AND EXISTS(
      SELECT 1 FROM tax.withholding_deposits deposit
       WHERE deposit.org_id=organization_id AND deposit.payment_id=original_payment_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='statutory deposit payment is retained after challan allocation; use a typed refund deposit correction';
    END IF;
    SELECT journal.* INTO original_journal FROM finance.accounting_events event
      JOIN finance.journal_entries journal ON journal.org_id=event.org_id AND journal.id=event.journal_entry_id
     WHERE event.org_id=organization_id AND event.payment_id=original_payment_id FOR UPDATE OF journal;
    IF original_journal.status<>'posted' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='original payment journal is not posted'; END IF;
    reversed_time:=pg_catalog.transaction_timestamp();
    INSERT INTO "erp_finance_commands"."command_scopes" VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'payment',organization_id,original_payment_id),
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'payment',organization_id,reversal_payment_id);
    INSERT INTO finance.payments(org_id,id,payment_number,payment_date,direction,party_id,branch_id,
      bank_account_id,settlement_account_id,
      payment_method,payment_purpose,currency_code,amount,functional_amount,fx_rate,external_reference,memo,
      reversal_of_payment_id,reversal_reason,status,approved_at,approved_by_membership_id,
      created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,reversal_payment_id,reversal_payment_number,original.payment_date,
      CASE original.direction WHEN 'receipt' THEN 'disbursement' ELSE 'receipt' END,
      original.party_id,original.branch_id,original.bank_account_id,original.settlement_account_id,
      original.payment_method,original.payment_purpose,original.currency_code,
      original.amount,original.functional_amount,original.fx_rate,original.external_reference,
      original.memo,original_payment_id,reason,'approved',reversed_time,actor,actor,actor);
    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,
      transaction_currency,functional_currency,fx_rate,transaction_debit_total,transaction_credit_total,
      functional_debit_total,functional_credit_total,reversal_of_journal_entry_id,reversal_reason,status,
      created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,reversal_journal_id,reversal_journal_number,original_journal.posting_date,
      'Payment reversal: '||reason,original_journal.transaction_currency,original_journal.functional_currency,
      original_journal.fx_rate,original_journal.transaction_credit_total,original_journal.transaction_debit_total,
      original_journal.functional_credit_total,original_journal.functional_debit_total,
      original_journal.id,reason,'draft',actor,actor);
    INSERT INTO finance.journal_lines(org_id,id,journal_entry_id,line_number,account_id,branch_id,party_id,
      description,transaction_debit,transaction_credit,functional_debit,functional_credit,created_by_membership_id)
    SELECT organization_id,gen_random_uuid(),reversal_journal_id,line_number,account_id,branch_id,party_id,
      description,transaction_credit,transaction_debit,functional_credit,functional_debit,actor
      FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=original_journal.id ORDER BY line_number;
    UPDATE finance.journal_entries SET status='posted',posted_at=reversed_time,posted_by_membership_id=actor,
      updated_at=reversed_time,updated_by_membership_id=actor,row_version=row_version+1
      WHERE org_id=organization_id AND id=reversal_journal_id;
    UPDATE finance.payments SET status='posted',posted_at=reversed_time,posted_by_membership_id=actor,
      updated_at=reversed_time,updated_by_membership_id=actor,row_version=row_version+1
      WHERE org_id=organization_id AND id=reversal_payment_id;
    INSERT INTO finance.accounting_events(org_id,id,event_type,payment_id,journal_entry_id,
      occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,reversal_event_id,'payment',reversal_payment_id,reversal_journal_id,
      reversed_time,reversed_time,actor);
    INSERT INTO finance.allocations(org_id,id,payment_id,open_item_id,allocation_date,currency_code,
      amount,functional_amount,fx_rate,reversal_of_allocation_id,reversal_reason,status,reversed_at,
      reversed_by_membership_id,created_by_membership_id)
    SELECT organization_id,gen_random_uuid(),allocation.payment_id,allocation.open_item_id,
      original.payment_date,allocation.currency_code,allocation.amount,allocation.functional_amount,
      allocation.fx_rate,allocation.id,reason,'reversed',reversed_time,actor,actor
      FROM finance.allocations allocation
     WHERE allocation.org_id=organization_id AND allocation.payment_id=original_payment_id
       AND allocation.status='posted'
       AND NOT EXISTS (SELECT 1 FROM finance.allocations reversal
                        WHERE reversal.org_id=allocation.org_id AND reversal.reversal_of_allocation_id=allocation.id);
    FOR advance IN SELECT * FROM procurement.purchase_order_advance_allocations a
      WHERE a.org_id=organization_id AND a.payment_id=original_payment_id AND a.status='posted' FOR UPDATE LOOP
      PERFORM erp_compliance_commands.assert_advance_withholding_reversible(organization_id,advance.id);
      reversal_withholding_id:=NULL;
      IF advance.withholding_id IS NOT NULL THEN
        reversal_withholding_id:=gen_random_uuid();
        PERFORM erp_compliance_commands.reverse_withholding(
          organization_id,advance.withholding_id,reversal_withholding_id,actor,gen_random_uuid(),gen_random_uuid(),NULL::uuid,
          reason,extensions.digest(pg_catalog.convert_to('advance-reversal:'||advance.id::text,'UTF8'),'sha256'),
          extensions.digest(pg_catalog.convert_to(reason||':'||advance.id::text,'UTF8'),'sha256'),reversed_time+interval '1 hour');
      END IF;
      reversal_open_item_id:=gen_random_uuid();
      INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,
        currency_code,principal_amount,functional_principal_amount,status,reversed_at,created_by_membership_id)
      VALUES(organization_id,reversal_open_item_id,reversal_event_id,original.party_id,'receivable',reversal_payment_number,
        original.payment_date,original.payment_date,'INR',advance.gross_advance_amount,advance.gross_advance_amount,'reversed',reversed_time,actor);
      INSERT INTO procurement.purchase_order_advance_allocations(org_id,id,payment_id,purchase_order_line_id,supplier_account_id,
        branch_id,cash_disbursed_amount,withheld_amount,gross_advance_amount,functional_gross_advance_amount,allocation_date,
        prepayment_open_item_id,withholding_id,reversal_of_allocation_id,reversal_reason,status,created_by_membership_id)
      VALUES(organization_id,gen_random_uuid(),reversal_payment_id,advance.purchase_order_line_id,advance.supplier_account_id,
        advance.branch_id,advance.cash_disbursed_amount,advance.withheld_amount,advance.gross_advance_amount,
        advance.functional_gross_advance_amount,original.payment_date,reversal_open_item_id,reversal_withholding_id,
        advance.id,reason,'reversed',actor);
      UPDATE finance.open_items SET status='reversed',reversed_at=reversed_time
       WHERE org_id=organization_id AND id=advance.prepayment_open_item_id AND status='open';
    END LOOP;
    UPDATE finance.payments SET status='reversed',updated_at=reversed_time,
      updated_by_membership_id=actor,row_version=row_version+1
      WHERE org_id=organization_id AND id=original_payment_id;
    DELETE FROM "erp_finance_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
      AND transaction_id=pg_catalog.txid_current() AND scope='payment' AND org_id=organization_id
      AND entity_id IN (original_payment_id,reversal_payment_id);
    RETURN reversal_payment_id;
END
$function$;
ALTER FUNCTION "erp_finance_commands"."reverse_payment"(organization_id uuid, original_payment_id uuid, reversal_payment_id uuid, reversal_payment_number varchar, reversal_journal_id uuid, reversal_journal_number varchar, reversal_event_id uuid, reason text) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_commands"."reverse_payment"(organization_id uuid, original_payment_id uuid, reversal_payment_id uuid, reversal_payment_number varchar, reversal_journal_id uuid, reversal_journal_number varchar, reversal_event_id uuid, reason text) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_finance_commands"."reverse_payment"(organization_id uuid, original_payment_id uuid, reversal_payment_id uuid, reversal_payment_number varchar, reversal_journal_id uuid, reversal_journal_number varchar, reversal_event_id uuid, reason text) TO "erp_app";
CREATE FUNCTION "erp_finance_commands"."apply_supplier_advance"(organization_id uuid, advance_allocation_id uuid, supplier_invoice_line_id uuid, invoice_open_item_id uuid, allocation_id uuid, journal_id uuid, journal_number varchar, event_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE advance procurement.purchase_order_advance_allocations%ROWTYPE;
        invoice_line procurement.supplier_invoice_lines%ROWTYPE;
        invoice procurement.supplier_invoices%ROWTYPE; advance_item finance.open_items%ROWTYPE;
        invoice_item finance.open_items%ROWTYPE; actor uuid; payable_account uuid; prepayment_account uuid;
        posted_time timestamptz:=pg_catalog.transaction_timestamp(); existing_event uuid;
BEGIN
    IF organization_id IS DISTINCT FROM erp_security.current_org_id()
       OR NOT erp_security.has_permission('finance.payment.manage',NULL::uuid)
       OR NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='supplier advance application permission denied';
    END IF;
    actor:=erp_security.current_membership_id();
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||advance_allocation_id::text,672003));
    SELECT id INTO existing_event FROM finance.accounting_events
     WHERE org_id=organization_id AND purchase_order_advance_allocation_id=advance_allocation_id;
    IF existing_event=event_id THEN RETURN advance_allocation_id; END IF;
    IF existing_event IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='supplier advance was already applied'; END IF;
    SELECT * INTO STRICT advance FROM procurement.purchase_order_advance_allocations
     WHERE org_id=organization_id AND id=advance_allocation_id FOR UPDATE;
    SELECT * INTO STRICT advance_item FROM finance.open_items
     WHERE org_id=organization_id AND id=advance.prepayment_open_item_id FOR UPDATE;
    SELECT * INTO STRICT invoice_line FROM procurement.supplier_invoice_lines
     WHERE org_id=organization_id AND id=supplier_invoice_line_id FOR SHARE;
    SELECT * INTO STRICT invoice FROM procurement.supplier_invoices
     WHERE org_id=organization_id AND id=invoice_line.supplier_invoice_id FOR SHARE;
    SELECT * INTO STRICT invoice_item FROM finance.open_items
     WHERE org_id=organization_id AND id=invoice_open_item_id FOR UPDATE;
    IF advance.status<>'posted' OR advance.reversal_of_allocation_id IS NOT NULL
       OR advance_item.status<>'open' OR advance_item.item_side<>'receivable'
       OR advance_item.principal_amount<>advance.gross_advance_amount
       OR invoice.status<>'posted' OR invoice_line.line_kind<>'product'
       OR invoice_line.purchase_order_line_id IS DISTINCT FROM advance.purchase_order_line_id
       OR invoice.supplier_account_id IS DISTINCT FROM advance.supplier_account_id
       OR invoice.branch_id IS DISTINCT FROM advance.branch_id
       OR invoice_item.status<>'open' OR invoice_item.item_side<>'payable'
       OR invoice_item.party_id IS DISTINCT FROM advance_item.party_id
       OR invoice_item.currency_code<>'INR' OR invoice_item.principal_amount<advance.gross_advance_amount
       OR invoice_line.net_value_amount<advance.gross_advance_amount THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier advance and posted invoice provenance do not match';
    END IF;
    IF EXISTS (SELECT 1 FROM tax.withholding_basis_lines invoice_basis
                WHERE invoice_basis.org_id=organization_id
                  AND invoice_basis.supplier_invoice_line_id=supplier_invoice_line_id)
       AND advance.withholding_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice line already has withholding basis for an earlier paid advance';
    END IF;
    payable_account:=erp_commercial_commands.resolve_role_account(
      organization_id,advance.branch_id,'accounts_payable','liability','INR',true);
    prepayment_account:=erp_commercial_commands.resolve_role_account(
      organization_id,advance.branch_id,'supplier_prepayment','asset','INR',true);
    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,
      transaction_currency,functional_currency,fx_rate,transaction_debit_total,transaction_credit_total,
      functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,invoice.invoice_date,'Supplier advance application','INR','INR',1,
      advance.gross_advance_amount,advance.gross_advance_amount,advance.functional_gross_advance_amount,
      advance.functional_gross_advance_amount,'draft',actor,actor);
    INSERT INTO finance.journal_lines(org_id,id,journal_entry_id,line_number,account_id,branch_id,party_id,
      description,transaction_debit,transaction_credit,functional_debit,functional_credit,created_by_membership_id)
    VALUES
      (organization_id,gen_random_uuid(),journal_id,1,payable_account,advance.branch_id,advance_item.party_id,
       'Apply supplier prepayment',advance.gross_advance_amount,0,advance.functional_gross_advance_amount,0,actor),
      (organization_id,gen_random_uuid(),journal_id,2,prepayment_account,advance.branch_id,advance_item.party_id,
       'Clear supplier prepayment',0,advance.gross_advance_amount,0,advance.functional_gross_advance_amount,actor);
    UPDATE finance.journal_entries SET status='posted',posted_at=posted_time,posted_by_membership_id=actor,
      updated_at=posted_time,updated_by_membership_id=actor,row_version=row_version+1
     WHERE org_id=organization_id AND id=journal_id;
    INSERT INTO finance.accounting_events(org_id,id,event_type,purchase_order_advance_allocation_id,journal_entry_id,
      occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,event_id,'supplier_advance_application',advance.id,journal_id,posted_time,invoice.posted_at,actor);
    INSERT INTO finance.allocations(org_id,id,purchase_order_advance_allocation_id,open_item_id,allocation_date,
      currency_code,amount,functional_amount,fx_rate,status,created_by_membership_id)
    VALUES(organization_id,allocation_id,advance.id,invoice_item.id,invoice.invoice_date,'INR',advance.gross_advance_amount,
      advance.functional_gross_advance_amount,1,'posted',actor);
    UPDATE finance.open_items SET status='settled',settled_at=posted_time
     WHERE org_id=organization_id AND id=advance_item.id AND status='open';
    RETURN advance_allocation_id;
END
$function$;
ALTER FUNCTION "erp_finance_commands"."apply_supplier_advance"(organization_id uuid, advance_allocation_id uuid, supplier_invoice_line_id uuid, invoice_open_item_id uuid, allocation_id uuid, journal_id uuid, journal_number varchar, event_id uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_commands"."apply_supplier_advance"(organization_id uuid, advance_allocation_id uuid, supplier_invoice_line_id uuid, invoice_open_item_id uuid, allocation_id uuid, journal_id uuid, journal_number varchar, event_id uuid) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_finance_commands"."apply_supplier_advance"(organization_id uuid, advance_allocation_id uuid, supplier_invoice_line_id uuid, invoice_open_item_id uuid, allocation_id uuid, journal_id uuid, journal_number varchar, event_id uuid) TO "erp_app";
-- Reviewed enforcement: finance.reconciliation_matches:reconciliation_matches_cross_row_guard
CREATE FUNCTION "erp_finance_invariants"."guard_reconciliation_match"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE statement_line_amount numeric(20,2); bank_ledger_id uuid; statement_currency char(3);
        journal finance.journal_entries%ROWTYPE; journal_bank_amount numeric(20,2); journal_bank_line_count bigint;
        line_matched numeric(20,2); journal_matched numeric(20,2); original finance.reconciliation_matches%ROWTYPE;
BEGIN
    IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='reconciliation matches are append-only'; END IF;
    SELECT line.amount,bank.account_id,statement.currency_code INTO statement_line_amount,bank_ledger_id,statement_currency
      FROM finance.bank_statement_lines line JOIN finance.bank_statements statement ON statement.org_id=line.org_id AND statement.id=line.bank_statement_id
      JOIN finance.bank_accounts bank ON bank.org_id=statement.org_id AND bank.id=statement.bank_account_id
     WHERE line.org_id=NEW.org_id AND line.id=NEW.bank_statement_line_id FOR UPDATE OF line,statement;
    SELECT * INTO journal FROM finance.journal_entries WHERE org_id=NEW.org_id AND id=NEW.journal_entry_id FOR UPDATE;
    SELECT count(*),coalesce(sum(transaction_debit+transaction_credit),0) INTO journal_bank_line_count,journal_bank_amount FROM finance.journal_lines
     WHERE org_id=NEW.org_id AND journal_entry_id=NEW.journal_entry_id AND account_id=bank_ledger_id;
    IF journal.status IS DISTINCT FROM 'posted' OR NEW.currency_code<>statement_currency OR NEW.currency_code<>journal.transaction_currency
       OR journal_bank_line_count<>1 OR journal_bank_amount=0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='match requires the posted bank ledger in the statement currency';
    END IF;
    IF NEW.reversal_of_match_id IS NOT NULL THEN
        SELECT * INTO original FROM finance.reconciliation_matches WHERE org_id=NEW.org_id AND id=NEW.reversal_of_match_id FOR UPDATE;
        IF NOT FOUND OR original.status<>'matched' OR ROW(NEW.bank_statement_line_id,NEW.journal_entry_id,NEW.matched_amount,NEW.currency_code)
           IS DISTINCT FROM ROW(original.bank_statement_line_id,original.journal_entry_id,original.matched_amount,original.currency_code) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='match reversal must copy original facts';
        END IF;
    ELSE
        SELECT coalesce(sum(m.matched_amount),0) INTO line_matched FROM finance.reconciliation_matches m WHERE m.org_id=NEW.org_id AND m.bank_statement_line_id=NEW.bank_statement_line_id AND m.status='matched' AND NOT EXISTS (SELECT 1 FROM finance.reconciliation_matches r WHERE r.org_id=m.org_id AND r.reversal_of_match_id=m.id);
        SELECT coalesce(sum(m.matched_amount),0) INTO journal_matched FROM finance.reconciliation_matches m WHERE m.org_id=NEW.org_id AND m.journal_entry_id=NEW.journal_entry_id AND m.status='matched' AND NOT EXISTS (SELECT 1 FROM finance.reconciliation_matches r WHERE r.org_id=m.org_id AND r.reversal_of_match_id=m.id);
        IF line_matched>statement_line_amount OR journal_matched>journal_bank_amount THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='reconciliation match exceeds an owner amount';
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_finance_invariants"."guard_reconciliation_match"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_finance_invariants"."guard_reconciliation_match"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "reconciliation_matches_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "finance"."reconciliation_matches" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_finance_invariants"."guard_reconciliation_match"();
-- Reviewed enforcement: hr.employees:employees_state_transition
CREATE FUNCTION "erp_stable_invariants"."guard_employee"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    cycle_found boolean;
BEGIN
    IF TG_OP = 'UPDATE' AND (
        OLD.status = 'draft' AND NEW.status NOT IN ('draft','active','separated')
        OR OLD.status = 'active' AND NEW.status NOT IN ('active','suspended','separated')
        OR OLD.status = 'suspended' AND NEW.status NOT IN ('suspended','active','separated')
        OR OLD.status = 'separated' AND NEW.status IS DISTINCT FROM 'separated'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid employee lifecycle transition';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(NEW.org_id::text, 329742019)
    );
    IF NEW.manager_employee_id IS NOT NULL THEN
        WITH RECURSIVE managers(id) AS (
            SELECT NEW.manager_employee_id
            UNION
            SELECT employee.manager_employee_id
              FROM hr.employees AS employee
              JOIN managers ON employee.org_id = NEW.org_id AND employee.id = managers.id
             WHERE employee.manager_employee_id IS NOT NULL
        )
        SELECT EXISTS (SELECT 1 FROM managers WHERE id = NEW.id) INTO cycle_found;
        IF cycle_found THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'employee manager assignment creates a reporting cycle';
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_stable_invariants"."guard_employee"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_stable_invariants"."guard_employee"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "employees_state_manager_guard_ct" AFTER INSERT OR UPDATE ON "hr"."employees" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_stable_invariants"."guard_employee"();
-- Reviewed enforcement: inventory.batches:inventory_batches_invariant_1
REVOKE ALL ON SCHEMA "erp_trade_invariants" FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_invariants"."guard_batch"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    mrp_conversion_count integer;
    validate_mrp_conversion boolean;
BEGIN
    validate_mrp_conversion:=TG_OP='INSERT';
    IF TG_OP='UPDATE' THEN
        validate_mrp_conversion:=ROW(
            NEW.product_id, NEW.mrp, NEW.mrp_uom_conversion_id, NEW.created_at
        ) IS DISTINCT FROM ROW(
            OLD.product_id, OLD.mrp, OLD.mrp_uom_conversion_id, OLD.created_at
        );
    END IF;
    IF validate_mrp_conversion THEN
        SELECT count(*) INTO mrp_conversion_count
          FROM catalog.uom_conversions AS conversion
          JOIN catalog.products AS product
            ON product.org_id=conversion.org_id
           AND product.id=conversion.product_id
         WHERE conversion.org_id=NEW.org_id
           AND conversion.id=NEW.mrp_uom_conversion_id
           AND conversion.product_id=NEW.product_id
           AND conversion.to_uom_code=product.base_uom_code
           AND conversion.status='active'
           AND conversion.valid_from<=NEW.created_at::date
           AND (conversion.valid_until IS NULL OR conversion.valid_until>=NEW.created_at::date);
        IF mrp_conversion_count<>1 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='batch MRP requires the effective marketed-pack to base-UOM conversion for its product';
        END IF;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF (
            OLD.status = 'quarantined' AND NEW.status NOT IN ('quarantined','released','blocked','recalled','expired')
            OR OLD.status = 'released' AND NEW.status NOT IN ('released','blocked','recalled','expired','exhausted')
            OR OLD.status = 'blocked' AND NEW.status NOT IN ('blocked','released','recalled','expired')
            OR OLD.status IN ('recalled','expired','exhausted') AND NEW.status IS DISTINCT FROM OLD.status
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid batch lifecycle transition';
        END IF;
        IF OLD.status='released' AND NEW.status='blocked'
           AND NOT EXISTS (
             SELECT 1 FROM erp_compliance_commands.command_scopes scope
              WHERE scope.backend_pid=pg_catalog.pg_backend_pid()
                AND scope.transaction_id=pg_catalog.txid_current()
                AND scope.scope='temperature_batch_block'
                AND scope.org_id=NEW.org_id AND scope.entity_id=NEW.id
           ) THEN
          RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='released batch blocking requires exact cold-chain command provenance';
        END IF;
        IF ROW(
            NEW.product_id, NEW.batch_number, NEW.lot_kind,
            NEW.manufactured_on, NEW.expires_on, NEW.mrp, NEW.mrp_uom_conversion_id
        ) IS DISTINCT FROM ROW(
            OLD.product_id, OLD.batch_number, OLD.lot_kind,
            OLD.manufactured_on, OLD.expires_on, OLD.mrp, OLD.mrp_uom_conversion_id
        ) AND EXISTS (
            SELECT 1 FROM inventory.stock_ledger_entries AS entry
             WHERE entry.org_id = OLD.org_id AND entry.batch_id = OLD.id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted batch identity, MRP, and marketed-pack basis are immutable';
        END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_batch"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_batch"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "batches_state_identity_guard_ct" AFTER INSERT OR UPDATE ON "inventory"."batches" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_batch"();
-- Reviewed enforcement: inventory.inventory_document_lines:inventory_inventory_document_lines_invariant_1
REVOKE ALL ON SCHEMA "erp_trade_commands" FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."assert_context"(p_org_id uuid, p_actor_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
BEGIN
    IF NULLIF(pg_catalog.current_setting('app.org_id', true), '')::uuid IS DISTINCT FROM p_org_id
       OR NULLIF(pg_catalog.current_setting('app.membership_id', true), '')::uuid IS DISTINCT FROM p_actor_id
       OR NOT EXISTS (
           SELECT 1 FROM core.memberships AS membership
            WHERE membership.org_id=p_org_id AND membership.id=p_actor_id
              AND membership.status='active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='trade command context is not an active exact organization membership';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."assert_context"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."assert_context"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."claim"(p_org_id uuid, p_actor_id uuid, p_operation varchar, p_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz, OUT p_claim_id uuid, OUT p_replay_resource_id uuid)
RETURNS record
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE existing core.idempotency_keys%ROWTYPE;
BEGIN
    IF pg_catalog.octet_length(p_key_hash)<>32 OR pg_catalog.octet_length(p_request_hash)<>32
       OR p_expires_at<=pg_catalog.transaction_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid command idempotency hashes or expiry';
    END IF;
    INSERT INTO core.idempotency_keys(
        org_id,actor_membership_id,operation,idempotency_key_hash,request_hash,expires_at
    ) VALUES (p_org_id,p_actor_id,p_operation,p_key_hash,p_request_hash,p_expires_at)
    ON CONFLICT (org_id,actor_membership_id,operation,idempotency_key_hash) DO NOTHING;

    SELECT * INTO existing FROM core.idempotency_keys
     WHERE org_id=p_org_id AND actor_membership_id=p_actor_id AND operation=p_operation
       AND idempotency_key_hash=p_key_hash FOR UPDATE;
    IF existing.request_hash IS DISTINCT FROM p_request_hash THEN
        RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency key was claimed with a different request hash';
    END IF;
    IF existing.status='succeeded' THEN
        p_claim_id := existing.id;
        p_replay_resource_id := existing.resource_id;
        RETURN;
    END IF;
    IF existing.status<>'claimed' OR existing.expires_at<=pg_catalog.transaction_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='idempotency claim is not executable';
    END IF;
    p_claim_id := existing.id;
    p_replay_resource_id := NULL;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."claim"(uuid,uuid,varchar,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."claim"(uuid,uuid,varchar,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."assert_permission"(p_permission_code text, p_branch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
BEGIN
    IF NOT erp_security.can_access_branch(p_branch_id)
       OR NOT erp_security.has_permission(p_permission_code,p_branch_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='trade command permission or branch scope is not active';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."assert_permission"(text,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."assert_permission"(text,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."finish_claim"(p_org_id uuid, p_claim_id uuid, p_resource_type varchar, p_resource_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE terminal_response_body bytea;
BEGIN
    terminal_response_body := pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'resource_type',p_resource_type,'resource_id',p_resource_id
      )::text,'UTF8');
    UPDATE core.idempotency_keys
       SET status='succeeded',resource_type=p_resource_type,resource_id=p_resource_id,
           response_status=200,response_media_type='application/json',
           response_body=terminal_response_body,
           response_hash=extensions.digest(terminal_response_body,'sha256'),
           completed_at=pg_catalog.transaction_timestamp()
     WHERE org_id=p_org_id AND id=p_claim_id AND status='claimed';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='idempotency claim could not be completed exactly once';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."finish_claim"(uuid,uuid,varchar,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."finish_claim"(uuid,uuid,varchar,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."assert_inventory_document"(p_org_id uuid, p_document_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE doc inventory.inventory_documents%ROWTYPE; bad_count bigint; expected_lines bigint;
BEGIN
    SELECT * INTO STRICT doc FROM inventory.inventory_documents
     WHERE org_id=p_org_id AND id=p_document_id FOR UPDATE;
    IF doc.status<>'approved' OR doc.costing_method_snapshot<>'moving_weighted_average'
       OR doc.document_type='cost_adjustment' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory command requires an approved non-landed-cost MWA document';
    END IF;
    PERFORM erp_trade_commands.assert_physical_logistics(p_org_id,p_document_id);
    SELECT count(*) INTO expected_lines FROM inventory.inventory_document_lines
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF expected_lines=0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory document has no lines';
    END IF;

    SELECT count(*) INTO bad_count
      FROM inventory.inventory_document_lines AS line
      JOIN inventory.batches AS batch ON batch.org_id=line.org_id AND batch.id=line.batch_id
      JOIN catalog.products AS product ON product.org_id=line.org_id AND product.id=line.product_id
      LEFT JOIN inventory.locations AS from_location ON from_location.org_id=line.org_id AND from_location.id=line.from_location_id
      LEFT JOIN inventory.locations AS to_location ON to_location.org_id=line.org_id AND to_location.id=line.to_location_id
     WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
       AND (batch.product_id IS DISTINCT FROM line.product_id
         OR (from_location.id IS NOT NULL AND from_location.branch_id IS DISTINCT FROM doc.branch_id)
         OR (to_location.id IS NOT NULL AND to_location.branch_id IS DISTINCT FROM
              CASE WHEN doc.document_type='transfer' THEN doc.destination_branch_id ELSE doc.branch_id END)
         OR (doc.document_type IN ('sales_issue','purchase_return_issue','transfer')
             AND (batch.lot_kind<>'manufacturer_batch' OR batch.status<>'released'
                  OR batch.released_at IS NULL OR batch.expires_on IS NULL
                  OR NOT (doc.document_date < batch.expires_on)))
         OR (line.movement_kind<>'count_adjustment' AND line.movement_kind<>'value_adjustment'
             AND line.extended_cost IS DISTINCT FROM pg_catalog.round(line.base_quantity*line.unit_cost,2))
         OR (doc.document_type IN ('opening_receipt','transfer','adjustment','stock_count')
             AND (line.uom_code IS DISTINCT FROM product.base_uom_code
                  OR (line.movement_kind<>'count_adjustment' AND line.base_quantity IS DISTINCT FROM line.entered_quantity)))
         OR (line.movement_kind='count_adjustment'
             AND (line.base_quantity IS DISTINCT FROM pg_catalog.abs(line.variance_quantity)
                  OR line.entered_quantity IS DISTINCT FROM pg_catalog.abs(line.variance_quantity))));
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory line product, batch, branch, UOM, quantity, or cost snapshot is inconsistent';
    END IF;

    IF doc.document_type='purchase_receipt' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        LEFT JOIN procurement.goods_receipt_lines source
          ON source.org_id=line.org_id AND source.id=line.goods_receipt_line_id
        WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
          AND (doc.goods_receipt_id IS NULL OR line.movement_kind<>'receipt'
            OR source.goods_receipt_id IS DISTINCT FROM doc.goods_receipt_id
            OR ROW(source.product_id,source.batch_id,source.location_id,source.uom_code,
                   source.base_accepted_quantity+source.base_free_quantity,source.unit_cost,source.extended_cost)
               IS DISTINCT FROM ROW(line.product_id,line.batch_id,line.to_location_id,line.uom_code,
                   line.base_quantity,line.unit_cost,line.extended_cost));
    ELSIF doc.document_type='sales_issue' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        LEFT JOIN sales.dispatch_lines dispatch_line
          ON dispatch_line.org_id=line.org_id AND dispatch_line.id=line.sales_dispatch_line_id
        LEFT JOIN sales.invoice_lines invoice_line
          ON invoice_line.org_id=line.org_id AND invoice_line.id=line.sales_invoice_line_id
        WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
          AND (line.movement_kind<>'issue' OR NOT (
             (doc.sales_dispatch_id IS NOT NULL AND dispatch_line.dispatch_id=doc.sales_dispatch_id
              AND ROW(dispatch_line.product_id,dispatch_line.batch_id,dispatch_line.from_location_id,dispatch_line.uom_code,
                      dispatch_line.base_billed_quantity+dispatch_line.base_free_quantity)
                  IS NOT DISTINCT FROM ROW(line.product_id,line.batch_id,line.from_location_id,line.uom_code,line.base_quantity))
             OR
             (doc.sales_invoice_id IS NOT NULL AND invoice_line.invoice_id=doc.sales_invoice_id
              AND invoice_line.line_kind='product' AND invoice_line.product_id=line.product_id
              AND invoice_line.uom_code=line.uom_code
              AND invoice_line.base_billed_quantity+invoice_line.base_free_quantity=line.base_quantity)
          ));
    ELSIF doc.document_type='sales_return_receipt' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        LEFT JOIN sales.return_lines source ON source.org_id=line.org_id AND source.id=line.sales_return_line_id
        WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
          AND (doc.sales_return_id IS NULL OR line.movement_kind<>'receipt' OR source.return_id IS DISTINCT FROM doc.sales_return_id
            OR ROW(source.product_id,source.batch_id,source.disposition_location_id,
                   source.base_billed_quantity+source.base_free_quantity)
               IS DISTINCT FROM ROW(line.product_id,line.batch_id,line.to_location_id,line.base_quantity));
    ELSIF doc.document_type='purchase_return_issue' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        LEFT JOIN procurement.purchase_return_lines source ON source.org_id=line.org_id AND source.id=line.purchase_return_line_id
        WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
          AND (doc.purchase_return_id IS NULL OR line.movement_kind<>'issue' OR source.purchase_return_id IS DISTINCT FROM doc.purchase_return_id
            OR ROW(source.product_id,source.batch_id,source.from_location_id,
                   source.base_billed_quantity+source.base_free_quantity)
               IS DISTINCT FROM ROW(line.product_id,line.batch_id,line.from_location_id,line.base_quantity));
    ELSIF doc.document_type='transfer' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        LEFT JOIN inventory.locations source_location ON source_location.org_id=line.org_id AND source_location.id=line.from_location_id
        LEFT JOIN inventory.locations destination_location ON destination_location.org_id=line.org_id AND destination_location.id=line.to_location_id
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
           AND (line.movement_kind<>'transfer' OR doc.destination_branch_id IS NULL
             OR doc.destination_branch_id=doc.branch_id
             OR source_location.branch_id IS DISTINCT FROM doc.branch_id
             OR destination_location.branch_id IS DISTINCT FROM doc.destination_branch_id);
    ELSIF doc.document_type='stock_count' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id AND line.movement_kind<>'count_adjustment';
    ELSIF doc.document_type='opening_receipt' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id AND line.movement_kind<>'receipt';
    ELSIF doc.document_type IN ('recall_quarantine','recall_release') THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        JOIN inventory.batches batch ON batch.org_id=line.org_id AND batch.id=line.batch_id
        JOIN compliance.recalls recall ON recall.org_id=doc.org_id AND recall.id=doc.recall_id
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
           AND (line.movement_kind<>'transfer' OR batch.product_id IS DISTINCT FROM recall.product_id
             OR recall.status NOT IN ('initiated','in_progress'));
        IF doc.recall_id IS NULL THEN bad_count:=bad_count+1; END IF;
    ELSIF doc.document_type='recall_recovery' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
        JOIN inventory.batches batch ON batch.org_id=line.org_id AND batch.id=line.batch_id
        JOIN compliance.recalls recall ON recall.org_id=doc.org_id AND recall.id=doc.recall_id
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
           AND (line.movement_kind<>'receipt' OR batch.product_id IS DISTINCT FROM recall.product_id
             OR recall.status NOT IN ('initiated','in_progress'));
        IF doc.recall_id IS NULL THEN bad_count:=bad_count+1; END IF;
    ELSIF doc.document_type='destruction' THEN
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id AND line.movement_kind<>'issue';
        IF doc.destruction_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM compliance.destructions d WHERE d.org_id=p_org_id AND d.id=doc.destruction_id
              AND d.inventory_document_id=doc.id AND d.status='posted'
        ) THEN bad_count := bad_count+1; END IF;
    ELSIF doc.document_type='reversal' THEN
        IF doc.reverses_document_id IS NULL OR EXISTS (
            SELECT 1 FROM inventory.inventory_documents original
             WHERE original.org_id=p_org_id AND original.id=doc.reverses_document_id
               AND (original.status<>'posted' OR original.document_type IN ('cost_adjustment','destruction','transfer')
                 OR original.recall_id IS NOT NULL)
        ) OR EXISTS (
            SELECT 1 FROM finance.accounting_events event
             WHERE event.org_id=p_org_id AND event.inventory_document_id=doc.reverses_document_id
        ) OR (SELECT count(*) FROM inventory.inventory_document_lines line
              WHERE line.org_id=p_org_id AND line.inventory_document_id=doc.id)
           <> (SELECT count(*) FROM inventory.inventory_document_lines line
               WHERE line.org_id=p_org_id AND line.inventory_document_id=doc.reverses_document_id)
        THEN bad_count := 1; ELSE bad_count := 0; END IF;
        IF bad_count=0 AND EXISTS (
            SELECT 1 FROM inventory.inventory_document_lines reversal_line
            JOIN inventory.inventory_document_lines original_line
              ON original_line.org_id=reversal_line.org_id
             AND original_line.inventory_document_id=doc.reverses_document_id
             AND original_line.line_number=reversal_line.line_number
            WHERE reversal_line.org_id=p_org_id AND reversal_line.inventory_document_id=doc.id
              AND ROW(reversal_line.product_id,reversal_line.batch_id,reversal_line.base_quantity,
                      reversal_line.unit_cost,reversal_line.extended_cost)
                 IS DISTINCT FROM ROW(original_line.product_id,original_line.batch_id,
                      original_line.base_quantity,original_line.unit_cost,original_line.extended_cost)
        ) THEN bad_count := 1; END IF;
    ELSE
        SELECT count(*) INTO bad_count FROM inventory.inventory_document_lines line
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
           AND line.movement_kind NOT IN ('receipt','issue','count_adjustment');
    END IF;
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory document type and typed source-line evidence do not match';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."assert_inventory_document"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."assert_inventory_document"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
-- Reviewed enforcement: inventory.inventory_document_lines:inventory_inventory_document_lines_invariant_2
CREATE FUNCTION "erp_trade_commands"."project_entry"(p_org_id uuid, p_entry_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE entry inventory.stock_ledger_entries%ROWTYPE; balance inventory.stock_balances%ROWTYPE;
        new_quantity numeric(20,6); new_value numeric(20,2); new_average numeric(20,4);
BEGIN
    SELECT * INTO STRICT entry FROM inventory.stock_ledger_entries
     WHERE org_id=p_org_id AND id=p_entry_id FOR SHARE;
    SELECT * INTO balance FROM inventory.stock_balances
     WHERE org_id=entry.org_id AND location_id=entry.location_id
       AND product_id=entry.product_id AND batch_id=entry.batch_id FOR UPDATE;
    new_quantity := COALESCE(balance.on_hand_quantity,0)+entry.quantity_delta;
    new_value := COALESCE(balance.inventory_value,0)+entry.value_delta;
    IF new_quantity<0 OR new_value<0 OR (new_quantity=0 AND new_value<>0) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='ledger projection would create negative or stranded inventory value';
    END IF;
    new_average := CASE WHEN new_quantity=0 THEN 0 ELSE pg_catalog.round(new_value/new_quantity,4) END;
    INSERT INTO inventory.stock_balances(
        org_id,branch_id,location_id,product_id,batch_id,on_hand_quantity,
        inventory_value,average_unit_cost,last_ledger_entry_id,projected_at,row_version
    ) VALUES (
        entry.org_id,entry.branch_id,entry.location_id,entry.product_id,entry.batch_id,
        new_quantity,new_value,new_average,entry.id,entry.posted_at,1
    ) ON CONFLICT (org_id,location_id,product_id,batch_id) DO UPDATE SET
        branch_id=EXCLUDED.branch_id,on_hand_quantity=EXCLUDED.on_hand_quantity,
        inventory_value=EXCLUDED.inventory_value,average_unit_cost=EXCLUDED.average_unit_cost,
        last_ledger_entry_id=EXCLUDED.last_ledger_entry_id,projected_at=EXCLUDED.projected_at,
        row_version=inventory.stock_balances.row_version+1;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."project_entry"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."project_entry"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."emit_entry"(p_org_id uuid, p_document_id uuid, p_line_id uuid, p_kind text, p_location_id uuid, p_quantity numeric, p_unit_cost numeric, p_value numeric, p_reverses_entry_id uuid, p_actor_id uuid, p_posted_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE new_id uuid; branch_id uuid;
BEGIN
    SELECT location.branch_id INTO STRICT branch_id FROM inventory.locations AS location
     WHERE location.org_id=p_org_id AND location.id=p_location_id FOR SHARE;
    INSERT INTO inventory.stock_ledger_entries(
        org_id,branch_id,inventory_document_id,inventory_document_line_id,entry_kind,
        location_id,product_id,batch_id,quantity_delta,unit_cost,value_delta,
        reverses_entry_id,posted_at,posted_by_membership_id
    ) SELECT p_org_id,branch_id,p_document_id,line.id,p_kind,p_location_id,
             line.product_id,line.batch_id,p_quantity,p_unit_cost,p_value,
             p_reverses_entry_id,p_posted_at,p_actor_id
        FROM inventory.inventory_document_lines AS line
       WHERE line.org_id=p_org_id AND line.id=p_line_id
    RETURNING id INTO new_id;
    PERFORM erp_trade_commands.project_entry(p_org_id,new_id);
    RETURN new_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."emit_entry"(uuid,uuid,uuid,text,uuid,numeric,numeric,numeric,uuid,uuid,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."emit_entry"(uuid,uuid,uuid,text,uuid,numeric,numeric,numeric,uuid,uuid,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."emit_document"(p_org_id uuid, p_document_id uuid, p_actor_id uuid, p_posted_at timestamptz)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE doc inventory.inventory_documents%ROWTYPE; line inventory.inventory_document_lines%ROWTYPE;
        balance inventory.stock_balances%ROWTYPE; original_entry inventory.stock_ledger_entries%ROWTYPE;
        cost numeric(20,4); value numeric(20,2); expected_count bigint; actual_count bigint;
BEGIN
    SELECT * INTO STRICT doc FROM inventory.inventory_documents
     WHERE org_id=p_org_id AND id=p_document_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM inventory.stock_ledger_entries WHERE org_id=p_org_id AND inventory_document_id=p_document_id) THEN
        RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='inventory document already owns ledger evidence';
    END IF;

    FOR line IN SELECT * FROM inventory.inventory_document_lines
                 WHERE org_id=p_org_id AND inventory_document_id=p_document_id ORDER BY line_number,id
    LOOP
        IF doc.document_type='reversal' THEN
            FOR original_entry IN
                SELECT entry.* FROM inventory.stock_ledger_entries entry
                JOIN inventory.inventory_document_lines original_line
                  ON original_line.org_id=entry.org_id AND original_line.id=entry.inventory_document_line_id
                WHERE entry.org_id=p_org_id AND entry.inventory_document_id=doc.reverses_document_id
                  AND original_line.line_number=line.line_number ORDER BY entry.location_id,entry.id
            LOOP
                IF ROW(line.product_id,line.batch_id) IS DISTINCT FROM
                   ROW(original_entry.product_id,original_entry.batch_id) THEN
                    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='reversal line stock identity differs from original ledger evidence';
                END IF;
                PERFORM erp_trade_commands.emit_entry(
                    p_org_id,p_document_id,line.id,'reversal',original_entry.location_id,
                    -original_entry.quantity_delta,original_entry.unit_cost,-original_entry.value_delta,
                    original_entry.id,p_actor_id,p_posted_at
                );
            END LOOP;
            CONTINUE;
        END IF;

        IF line.movement_kind IN ('issue','transfer')
           OR (line.movement_kind='count_adjustment' AND line.variance_quantity<0) THEN
            SELECT * INTO STRICT balance FROM inventory.stock_balances
             WHERE org_id=p_org_id AND location_id=line.from_location_id
               AND product_id=line.product_id AND batch_id=line.batch_id FOR UPDATE;
            cost := balance.average_unit_cost;
            value := CASE WHEN line.base_quantity=balance.on_hand_quantity
                          THEN balance.inventory_value
                          ELSE pg_catalog.round(line.base_quantity*cost,2) END;
            IF line.unit_cost IS DISTINCT FROM cost OR line.extended_cost IS DISTINCT FROM value THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='outbound line cost is not the locked moving weighted average';
            END IF;
        ELSE
            cost := line.unit_cost; value := line.extended_cost;
        END IF;

        CASE line.movement_kind
          WHEN 'receipt' THEN
            PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'receipt',line.to_location_id,line.base_quantity,cost,value,NULL,p_actor_id,p_posted_at);
          WHEN 'issue' THEN
            PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'issue',line.from_location_id,-line.base_quantity,cost,-value,NULL,p_actor_id,p_posted_at);
          WHEN 'transfer' THEN
            PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'transfer_out',line.from_location_id,-line.base_quantity,cost,-value,NULL,p_actor_id,p_posted_at);
            PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'transfer_in',line.to_location_id,line.base_quantity,cost,value,NULL,p_actor_id,p_posted_at);
          WHEN 'count_adjustment' THEN
            IF line.variance_quantity>0 THEN
                PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'count_gain',line.from_location_id,line.base_quantity,cost,value,NULL,p_actor_id,p_posted_at);
            ELSIF line.variance_quantity<0 THEN
                PERFORM erp_trade_commands.emit_entry(p_org_id,p_document_id,line.id,'count_loss',line.from_location_id,-line.base_quantity,cost,-value,NULL,p_actor_id,p_posted_at);
            END IF;
          ELSE
            RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='landed-cost value adjustment remains blocked';
        END CASE;
    END LOOP;
    SELECT COALESCE(sum(CASE WHEN movement_kind='transfer' THEN 2
                             WHEN movement_kind='count_adjustment' AND variance_quantity=0 THEN 0 ELSE 1 END),0)
      INTO expected_count FROM inventory.inventory_document_lines
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF doc.document_type='reversal' THEN
        SELECT count(*) INTO expected_count FROM inventory.stock_ledger_entries
         WHERE org_id=p_org_id AND inventory_document_id=doc.reverses_document_id;
    END IF;
    SELECT count(*) INTO actual_count FROM inventory.stock_ledger_entries
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF actual_count<>expected_count THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory ledger cardinality is not exact';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."emit_document"(uuid,uuid,uuid,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."emit_document"(uuid,uuid,uuid,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
-- Reviewed enforcement: inventory.inventory_document_lines:inventory_inventory_document_lines_landed_cost_allocation
REVOKE ALL ON SCHEMA "erp_trade_commands_v2" FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands_v2"."eligible_landed_cost_pool"(p_org_id uuid, p_supplier_invoice_line_id uuid)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE source procurement.supplier_invoice_lines%ROWTYPE;
        invoice_status text;
        allocated_billed numeric(20,6);
        allocated_free numeric(20,6);
        receipt_cost numeric;
BEGIN
    SELECT line.* INTO source
      FROM procurement.supplier_invoice_lines AS line
      JOIN procurement.supplier_invoices AS invoice
        ON invoice.org_id=line.org_id AND invoice.id=line.supplier_invoice_id
     WHERE line.org_id=p_org_id AND line.id=p_supplier_invoice_line_id
     FOR SHARE OF line, invoice;
    SELECT invoice.status INTO invoice_status
      FROM procurement.supplier_invoices AS invoice
     WHERE invoice.org_id=p_org_id AND invoice.id=source.supplier_invoice_id;
    IF source.id IS NULL OR invoice_status<>'posted' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed cost requires a posted supplier invoice line';
    END IF;
    IF source.inventory_cost_treatment<>'capitalize' THEN
        RETURN 0;
    END IF;
    IF source.line_kind='charge' THEN
        RETURN source.net_value_amount;
    END IF;

    SELECT COALESCE(sum(allocation.allocated_base_billed_quantity),0),
           COALESCE(sum(allocation.allocated_base_free_quantity),0),
           COALESCE(sum(pg_catalog.round(
               (allocation.allocated_base_billed_quantity+allocation.allocated_base_free_quantity)
               * receipt.unit_cost, 2
           )),0)
      INTO allocated_billed,allocated_free,receipt_cost
      FROM procurement.supplier_invoice_receipt_allocations AS allocation
      JOIN procurement.goods_receipt_lines AS receipt
        ON receipt.org_id=allocation.org_id AND receipt.id=allocation.goods_receipt_line_id
     WHERE allocation.org_id=p_org_id
       AND allocation.supplier_invoice_line_id=p_supplier_invoice_line_id;
    IF allocated_billed IS DISTINCT FROM source.base_billed_quantity
       OR allocated_free IS DISTINCT FROM source.base_free_quantity THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='capitalized product cost requires complete receipt allocation';
    END IF;
    RETURN source.net_value_amount-receipt_cost;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."eligible_landed_cost_pool"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."eligible_landed_cost_pool"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands_v2"."assert_landed_cost_document"(p_org_id uuid, p_document_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE doc inventory.inventory_documents%ROWTYPE;
        source_line record;
        bad_count bigint;
        source_count bigint;
        expected_count bigint;
        pool numeric;
        locked_supplier_invoice_id uuid;
BEGIN
    SELECT * INTO STRICT doc FROM inventory.inventory_documents
     WHERE org_id=p_org_id AND id=p_document_id FOR UPDATE;
    IF doc.status<>'approved' OR doc.document_type<>'cost_adjustment'
       OR doc.supplier_invoice_id IS NULL
       OR doc.costing_method_snapshot<>'moving_weighted_average' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost command requires an approved typed MWA cost adjustment';
    END IF;
    SELECT id INTO locked_supplier_invoice_id FROM procurement.supplier_invoices
     WHERE org_id=p_org_id AND id=doc.supplier_invoice_id AND status='posted'
     FOR SHARE;
    IF locked_supplier_invoice_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost source supplier invoice is not posted';
    END IF;
    SELECT count(*) INTO source_count FROM inventory.inventory_document_lines
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF source_count=0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost document has no allocation lines';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_org_id::text||':landed-cost:'||p_document_id::text,82410617)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(lock_key,82410618))
      FROM (
        SELECT DISTINCT p_org_id::text||':'||line.from_location_id::text||':'||line.product_id::text||':'||line.batch_id::text AS lock_key
          FROM inventory.inventory_document_lines AS line
         WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
         ORDER BY lock_key
      ) AS locked;
    PERFORM balance.location_id
      FROM inventory.stock_balances AS balance
      JOIN (
        SELECT DISTINCT from_location_id,product_id,batch_id
          FROM inventory.inventory_document_lines
         WHERE org_id=p_org_id AND inventory_document_id=p_document_id
      ) AS target
        ON target.from_location_id=balance.location_id
       AND target.product_id=balance.product_id AND target.batch_id=balance.batch_id
     WHERE balance.org_id=p_org_id
     ORDER BY balance.location_id,balance.product_id,balance.batch_id
     FOR UPDATE OF balance;

    SELECT count(*) INTO bad_count
      FROM inventory.inventory_document_lines AS line
      JOIN inventory.batches AS batch
        ON batch.org_id=line.org_id AND batch.id=line.batch_id
      JOIN inventory.locations AS location
        ON location.org_id=line.org_id AND location.id=line.from_location_id
      LEFT JOIN inventory.stock_balances AS balance
        ON balance.org_id=line.org_id AND balance.location_id=line.from_location_id
       AND balance.product_id=line.product_id AND balance.batch_id=line.batch_id
      JOIN procurement.supplier_invoice_lines AS supplier_line
        ON supplier_line.org_id=line.org_id AND supplier_line.id=line.supplier_invoice_line_id
     WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
       AND (line.movement_kind<>'value_adjustment'
         OR supplier_line.supplier_invoice_id IS DISTINCT FROM doc.supplier_invoice_id
         OR supplier_line.inventory_cost_treatment<>'capitalize'
         OR batch.product_id IS DISTINCT FROM line.product_id
         OR location.branch_id IS DISTINCT FROM doc.branch_id
         OR balance.on_hand_quantity IS NULL OR balance.on_hand_quantity<=0
         OR balance.inventory_value+line.extended_cost<0
         OR (line.cost_allocation_method='quantity_weighted'
             AND line.cost_allocation_basis_quantity IS DISTINCT FROM balance.on_hand_quantity)
         OR (line.cost_allocation_method='value_weighted'
             AND line.cost_allocation_basis_value IS DISTINCT FROM balance.inventory_value)
         OR NOT EXISTS (
             SELECT 1
               FROM procurement.supplier_invoice_receipt_allocations AS allocation
               JOIN procurement.goods_receipt_lines AS receipt
                 ON receipt.org_id=allocation.org_id AND receipt.id=allocation.goods_receipt_line_id
               JOIN procurement.supplier_invoice_lines AS allocated_line
                 ON allocated_line.org_id=allocation.org_id AND allocated_line.id=allocation.supplier_invoice_line_id
              WHERE allocation.org_id=line.org_id
                AND allocated_line.supplier_invoice_id=doc.supplier_invoice_id
                AND receipt.product_id=line.product_id
                AND receipt.batch_id=line.batch_id
                AND receipt.location_id=line.from_location_id
                AND (supplier_line.line_kind='charge'
                     OR allocated_line.id=supplier_line.id)
         ));
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost target is not positive on-hand stock from the supplier invoice receipt lineage';
    END IF;

    FOR source_line IN
        SELECT supplier_line.id,
               count(line.id) AS allocation_count,
               min(line.cost_allocation_method) AS allocation_method,
               max(line.cost_allocation_method) AS max_allocation_method,
               sum(line.cost_allocation_weight) AS weight_total
          FROM procurement.supplier_invoice_lines AS supplier_line
          JOIN inventory.inventory_document_lines AS line
            ON line.org_id=supplier_line.org_id AND line.supplier_invoice_line_id=supplier_line.id
         WHERE supplier_line.org_id=p_org_id
           AND supplier_line.supplier_invoice_id=doc.supplier_invoice_id
           AND line.inventory_document_id=p_document_id
         GROUP BY supplier_line.id
         ORDER BY supplier_line.id
    LOOP
        pool := erp_trade_commands_v2.eligible_landed_cost_pool(p_org_id,source_line.id);
        IF pool=0 OR source_line.allocation_method IS DISTINCT FROM source_line.max_allocation_method
           OR source_line.weight_total IS DISTINCT FROM 1
           OR (source_line.allocation_method='direct' AND source_line.allocation_count<>1) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost source pool, method, or exact weight total is invalid';
        END IF;

        SELECT count(*) INTO bad_count
          FROM (
            SELECT line.id,line.line_number,line.extended_cost,line.cost_allocation_method,
                   line.cost_allocation_weight,
                   CASE line.cost_allocation_method
                     WHEN 'quantity_weighted' THEN line.cost_allocation_basis_quantity
                     WHEN 'value_weighted' THEN line.cost_allocation_basis_value
                     ELSE 1
                   END AS basis,
                   sum(CASE line.cost_allocation_method
                         WHEN 'quantity_weighted' THEN line.cost_allocation_basis_quantity
                         WHEN 'value_weighted' THEN line.cost_allocation_basis_value
                         ELSE 1
                       END) OVER () AS basis_total,
                   row_number() OVER (ORDER BY line.line_number,line.id) AS allocation_position,
                   count(*) OVER () AS allocation_total
              FROM inventory.inventory_document_lines AS line
             WHERE line.org_id=p_org_id AND line.inventory_document_id=p_document_id
               AND line.supplier_invoice_line_id=source_line.id
          ) AS allocation
         WHERE allocation.cost_allocation_weight IS DISTINCT FROM
                 CASE WHEN allocation.cost_allocation_method='direct' THEN 1
                      WHEN allocation.allocation_position<allocation.allocation_total
                      THEN pg_catalog.round(allocation.basis/allocation.basis_total,12)
                      ELSE 1-COALESCE((
                          SELECT sum(pg_catalog.round(prior.basis/prior.basis_total,12))
                            FROM (
                              SELECT CASE earlier.cost_allocation_method
                                       WHEN 'quantity_weighted' THEN earlier.cost_allocation_basis_quantity
                                       WHEN 'value_weighted' THEN earlier.cost_allocation_basis_value
                                       ELSE 1
                                     END AS basis,
                                     sum(CASE earlier.cost_allocation_method
                                           WHEN 'quantity_weighted' THEN earlier.cost_allocation_basis_quantity
                                           WHEN 'value_weighted' THEN earlier.cost_allocation_basis_value
                                           ELSE 1
                                         END) OVER () AS basis_total,
                                     row_number() OVER (ORDER BY earlier.line_number,earlier.id) AS position
                                FROM inventory.inventory_document_lines AS earlier
                               WHERE earlier.org_id=p_org_id
                                 AND earlier.inventory_document_id=p_document_id
                                 AND earlier.supplier_invoice_line_id=source_line.id
                            ) AS prior
                           WHERE prior.position<allocation.allocation_total
                      ),0) END
            OR allocation.extended_cost IS DISTINCT FROM
                 CASE WHEN allocation.allocation_position<allocation.allocation_total
                      THEN pg_catalog.round(pool*allocation.cost_allocation_weight,2)
                      ELSE pool-COALESCE((
                          SELECT sum(pg_catalog.round(pool*prior.cost_allocation_weight,2))
                            FROM (
                              SELECT earlier.cost_allocation_weight,
                                     row_number() OVER (ORDER BY earlier.line_number,earlier.id) AS position
                                FROM inventory.inventory_document_lines AS earlier
                               WHERE earlier.org_id=p_org_id
                                 AND earlier.inventory_document_id=p_document_id
                                 AND earlier.supplier_invoice_line_id=source_line.id
                            ) AS prior
                           WHERE prior.position<allocation.allocation_total
                      ),0) END;
        IF bad_count<>0 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost weights or deterministic final-paise allocation do not match the eligible pool';
        END IF;
    END LOOP;

    SELECT count(*) INTO source_count
      FROM (
        SELECT DISTINCT supplier_invoice_line_id
          FROM inventory.inventory_document_lines
         WHERE org_id=p_org_id AND inventory_document_id=p_document_id
      ) AS sources;
    SELECT count(*) INTO expected_count
      FROM procurement.supplier_invoice_lines AS line
     WHERE line.org_id=p_org_id AND line.supplier_invoice_id=doc.supplier_invoice_id
       AND line.inventory_cost_treatment='capitalize'
       AND erp_trade_commands_v2.eligible_landed_cost_pool(p_org_id,line.id)<>0;
    IF source_count<>expected_count THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost document does not allocate every and only nonzero capitalized source pool';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."assert_landed_cost_document"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."assert_landed_cost_document"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands_v2"."guard_posted_landed_allocation"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE target_org uuid; target_document uuid; target_status text; target_type text;
BEGIN
    target_org := CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
    target_document := CASE WHEN TG_OP='DELETE' THEN OLD.inventory_document_id ELSE NEW.inventory_document_id END;
    SELECT status,document_type INTO target_status,target_type FROM inventory.inventory_documents
     WHERE org_id=target_org AND id=target_document;
    IF target_status IN ('posted','reversed') AND target_type='cost_adjustment' THEN
        PERFORM erp_trade_commands_v2.assert_landed_cost_document(target_org,target_document);
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."guard_posted_landed_allocation"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."guard_posted_landed_allocation"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "landed_cost_allocations_exact_ct" AFTER INSERT OR UPDATE OR DELETE ON "inventory"."inventory_document_lines" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands_v2"."guard_posted_landed_allocation"();
-- Reviewed enforcement: inventory.inventory_documents:inventory_inventory_documents_invariant_1
CREATE FUNCTION "erp_trade_commands"."post_locked_document"(p_org_id uuid, p_document_id uuid, p_actor_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE quantity_total numeric(20,6); value_total numeric(20,2); command_posted_at timestamptz;
BEGIN
    PERFORM erp_trade_commands.assert_inventory_document(p_org_id,p_document_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_org_id::text||':inventory-document:'||p_document_id::text,74139017)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(lock_key,74139018)
    ) FROM (
        SELECT DISTINCT p_org_id::text||':'||location_id::text||':'||product_id::text||':'||batch_id::text AS lock_key
        FROM (
          SELECT from_location_id AS location_id,product_id,batch_id FROM inventory.inventory_document_lines
           WHERE org_id=p_org_id AND inventory_document_id=p_document_id AND from_location_id IS NOT NULL
          UNION
          SELECT to_location_id,product_id,batch_id FROM inventory.inventory_document_lines
           WHERE org_id=p_org_id AND inventory_document_id=p_document_id AND to_location_id IS NOT NULL
        ) identities ORDER BY lock_key
    ) ordered_locks;
    SELECT COALESCE(sum(pg_catalog.abs(base_quantity)),0),COALESCE(sum(pg_catalog.abs(extended_cost)),0)
      INTO quantity_total,value_total FROM inventory.inventory_document_lines
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF EXISTS (SELECT 1 FROM inventory.inventory_documents WHERE org_id=p_org_id AND id=p_document_id
               AND (total_abs_base_quantity IS DISTINCT FROM quantity_total OR total_value IS DISTINCT FROM value_total)) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='inventory header totals do not equal locked line totals';
    END IF;
    command_posted_at := pg_catalog.transaction_timestamp();
    PERFORM erp_trade_commands.emit_document(p_org_id,p_document_id,p_actor_id,command_posted_at);
    UPDATE inventory.inventory_documents SET status='posted',posted_at=command_posted_at,
           posted_by_membership_id=p_actor_id,updated_at=command_posted_at,
           updated_by_membership_id=p_actor_id,row_version=row_version+1
     WHERE org_id=p_org_id AND id=p_document_id AND status='approved';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='inventory state transition lost its lock'; END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."post_locked_document"(uuid,uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."post_locked_document"(uuid,uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."post_inventory_document"(p_org_id uuid, p_document_id uuid, p_actor_id uuid, p_idempotency_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE claim_id uuid; replay_id uuid; source_count integer; document_branch_id uuid;
        document_recall_id uuid; locked_document_type text;
BEGIN
    PERFORM erp_trade_commands.assert_context(p_org_id,p_actor_id);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      p_org_id,p_actor_id,'inventory.document.post',p_idempotency_key_hash,p_request_hash,p_expires_at
    );
    IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
    SELECT document_row.branch_id,num_nonnulls(document_row.sales_dispatch_id,document_row.sales_invoice_id,
                        document_row.sales_return_id,document_row.goods_receipt_id,document_row.supplier_invoice_id,
                        document_row.purchase_return_id,document_row.destruction_id),document_row.recall_id,document_row.document_type
      INTO document_branch_id,source_count,document_recall_id,locked_document_type
      FROM inventory.inventory_documents document_row
     WHERE document_row.org_id=p_org_id AND document_row.id=p_document_id FOR UPDATE;
    IF source_count IS NULL OR source_count<>0 OR document_recall_id IS NOT NULL
       OR locked_document_type IN ('stock_count','transfer') THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='typed source documents must use their owning domain command';
    END IF;
    PERFORM erp_trade_commands.assert_permission('inventory.document.post',document_branch_id);
    PERFORM erp_trade_commands.post_locked_document(p_org_id,p_document_id,p_actor_id);
    PERFORM erp_trade_commands.finish_claim(p_org_id,claim_id,'inventory.inventory_documents',p_document_id);
    RETURN p_document_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."post_inventory_document"(uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."post_inventory_document"(uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT USAGE ON SCHEMA "erp_trade_commands" TO "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_trade_commands"."post_inventory_document"(uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands"."guard_inventory_evidence"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_status text;
BEGIN
    IF TG_TABLE_NAME='inventory_documents' THEN
        IF TG_OP='DELETE' AND OLD.status IN ('posted','reversed') THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted inventory evidence is immutable';
        END IF;
        IF TG_OP='UPDATE' AND OLD.status IN ('posted','reversed') AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted inventory evidence is immutable';
        END IF;
        IF TG_OP<>'DELETE' AND NEW.status IN ('posted','reversed')
           AND current_user<>'erp_migration_owner' THEN
            RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='only the inventory command may post or reverse evidence';
        END IF;
        RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
    END IF;
    SELECT status INTO parent_status FROM inventory.inventory_documents
     WHERE org_id=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
       AND id=CASE WHEN TG_OP='DELETE' THEN OLD.inventory_document_id ELSE NEW.inventory_document_id END;
    IF parent_status IN ('posted','reversed') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted inventory lines are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."guard_inventory_evidence"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."guard_inventory_evidence"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "inventory_documents_command_guard" BEFORE INSERT OR UPDATE OR DELETE ON "inventory"."inventory_documents" FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands"."guard_inventory_evidence"();
CREATE TRIGGER "inventory_document_lines_command_guard" BEFORE INSERT OR UPDATE OR DELETE ON "inventory"."inventory_document_lines" FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands"."guard_inventory_evidence"();
CREATE UNIQUE INDEX "uq_inventory_documents_reverses_once" ON "inventory"."inventory_documents" (org_id,reverses_document_id) WHERE reverses_document_id IS NOT NULL;
-- Reviewed enforcement: inventory.inventory_documents:inventory_inventory_documents_invariant_2
CREATE FUNCTION "erp_trade_commands_v2"."assert_source_inventory_ownership"(p_source_kind text, p_org_id uuid, p_source_id uuid, p_source_status text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE owned_count bigint; reversal_count bigint; expected_count bigint := 1; owned_id uuid;
BEGIN
    IF p_source_status NOT IN ('posted','reversed') THEN RETURN; END IF;
    CASE p_source_kind
      WHEN 'sales_dispatch' THEN
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND sales_dispatch_id=p_source_id AND document_type='sales_issue' AND status IN ('posted','reversed');
      WHEN 'sales_invoice' THEN
        expected_count := CASE WHEN EXISTS (
            SELECT 1 FROM sales.invoice_lines line
             WHERE line.org_id=p_org_id AND line.invoice_id=p_source_id AND line.line_kind='product'
               AND NOT EXISTS (
                   SELECT 1 FROM sales.invoice_dispatch_allocations allocation
                    WHERE allocation.org_id=line.org_id AND allocation.invoice_line_id=line.id
               )
        ) THEN 1 ELSE 0 END;
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND sales_invoice_id=p_source_id AND document_type='sales_issue' AND status IN ('posted','reversed');
      WHEN 'sales_return' THEN
        expected_count := CASE WHEN EXISTS (
            SELECT 1 FROM sales.return_lines WHERE org_id=p_org_id AND return_id=p_source_id AND disposition='return_to_stock'
        ) THEN 1 ELSE 0 END;
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND sales_return_id=p_source_id AND document_type='sales_return_receipt' AND status IN ('posted','reversed');
      WHEN 'goods_receipt' THEN
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND goods_receipt_id=p_source_id AND document_type='purchase_receipt' AND status IN ('posted','reversed');
      WHEN 'purchase_return' THEN
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND purchase_return_id=p_source_id AND document_type='purchase_return_issue' AND status IN ('posted','reversed');
      WHEN 'destruction' THEN
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND destruction_id=p_source_id AND document_type='destruction' AND status IN ('posted','reversed');
      WHEN 'supplier_invoice' THEN
        SELECT count(*) INTO expected_count FROM procurement.supplier_invoice_lines AS line
         WHERE line.org_id=p_org_id AND line.supplier_invoice_id=p_source_id
           AND line.inventory_cost_treatment='capitalize'
           AND erp_trade_commands_v2.eligible_landed_cost_pool(p_org_id,line.id)<>0;
        expected_count := CASE WHEN expected_count>0 THEN 1 ELSE 0 END;
        SELECT count(*),(pg_catalog.array_agg(id))[1] INTO owned_count,owned_id FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND supplier_invoice_id=p_source_id AND document_type='cost_adjustment' AND status IN ('posted','reversed');
      ELSE
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='unknown typed inventory source kind';
    END CASE;
    IF owned_count IS DISTINCT FROM expected_count THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted typed source does not own exactly its required canonical inventory document';
    END IF;
    IF p_source_status='reversed' AND owned_id IS NOT NULL THEN
        SELECT count(*) INTO reversal_count FROM inventory.inventory_documents
         WHERE org_id=p_org_id AND reverses_document_id=owned_id AND status='posted';
        IF reversal_count<>1 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='reversed typed source does not own exactly one posted inverse inventory document';
        END IF;
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."assert_source_inventory_ownership"(text,uuid,uuid,text) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."assert_source_inventory_ownership"(text,uuid,uuid,text) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands_v2"."guard_source_inventory_ownership"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE source_org uuid; source_id uuid; source_status text; original inventory.inventory_documents%ROWTYPE;
BEGIN
    IF TG_TABLE_SCHEMA='inventory' THEN
        IF TG_OP='DELETE' THEN
            original := OLD;
        ELSE
            original := NEW;
        END IF;
        IF original.sales_dispatch_id IS NOT NULL THEN
            SELECT status INTO source_status FROM sales.dispatches WHERE org_id=original.org_id AND id=original.sales_dispatch_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_dispatch',original.org_id,original.sales_dispatch_id,source_status);
        ELSIF original.sales_invoice_id IS NOT NULL THEN
            SELECT status INTO source_status FROM sales.invoices WHERE org_id=original.org_id AND id=original.sales_invoice_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_invoice',original.org_id,original.sales_invoice_id,source_status);
        ELSIF original.sales_return_id IS NOT NULL THEN
            SELECT status INTO source_status FROM sales.returns WHERE org_id=original.org_id AND id=original.sales_return_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_return',original.org_id,original.sales_return_id,source_status);
        ELSIF original.goods_receipt_id IS NOT NULL THEN
            SELECT status INTO source_status FROM procurement.goods_receipts WHERE org_id=original.org_id AND id=original.goods_receipt_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('goods_receipt',original.org_id,original.goods_receipt_id,source_status);
        ELSIF original.purchase_return_id IS NOT NULL THEN
            SELECT status INTO source_status FROM procurement.purchase_returns WHERE org_id=original.org_id AND id=original.purchase_return_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('purchase_return',original.org_id,original.purchase_return_id,source_status);
        ELSIF original.destruction_id IS NOT NULL THEN
            SELECT status INTO source_status FROM compliance.destructions WHERE org_id=original.org_id AND id=original.destruction_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('destruction',original.org_id,original.destruction_id,source_status);
        ELSIF original.supplier_invoice_id IS NOT NULL THEN
            SELECT status INTO source_status FROM procurement.supplier_invoices WHERE org_id=original.org_id AND id=original.supplier_invoice_id;
            PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('supplier_invoice',original.org_id,original.supplier_invoice_id,source_status);
        ELSIF original.reverses_document_id IS NOT NULL THEN
            SELECT * INTO original FROM inventory.inventory_documents WHERE org_id=original.org_id AND id=original.reverses_document_id;
            IF original.sales_dispatch_id IS NOT NULL THEN
                SELECT status INTO source_status FROM sales.dispatches WHERE org_id=original.org_id AND id=original.sales_dispatch_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_dispatch',original.org_id,original.sales_dispatch_id,source_status);
            ELSIF original.sales_invoice_id IS NOT NULL THEN
                SELECT status INTO source_status FROM sales.invoices WHERE org_id=original.org_id AND id=original.sales_invoice_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_invoice',original.org_id,original.sales_invoice_id,source_status);
            ELSIF original.sales_return_id IS NOT NULL THEN
                SELECT status INTO source_status FROM sales.returns WHERE org_id=original.org_id AND id=original.sales_return_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('sales_return',original.org_id,original.sales_return_id,source_status);
            ELSIF original.goods_receipt_id IS NOT NULL THEN
                SELECT status INTO source_status FROM procurement.goods_receipts WHERE org_id=original.org_id AND id=original.goods_receipt_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('goods_receipt',original.org_id,original.goods_receipt_id,source_status);
            ELSIF original.purchase_return_id IS NOT NULL THEN
                SELECT status INTO source_status FROM procurement.purchase_returns WHERE org_id=original.org_id AND id=original.purchase_return_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('purchase_return',original.org_id,original.purchase_return_id,source_status);
            ELSIF original.destruction_id IS NOT NULL THEN
                SELECT status INTO source_status FROM compliance.destructions WHERE org_id=original.org_id AND id=original.destruction_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('destruction',original.org_id,original.destruction_id,source_status);
            ELSIF original.supplier_invoice_id IS NOT NULL THEN
                SELECT status INTO source_status FROM procurement.supplier_invoices WHERE org_id=original.org_id AND id=original.supplier_invoice_id;
                PERFORM erp_trade_commands_v2.assert_source_inventory_ownership('supplier_invoice',original.org_id,original.supplier_invoice_id,source_status);
            END IF;
        END IF;
        RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
    END IF;

    source_org := CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
    source_id := CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
    source_status := CASE WHEN TG_OP='DELETE' THEN OLD.status ELSE NEW.status END;
    PERFORM erp_trade_commands_v2.assert_source_inventory_ownership(TG_ARGV[0],source_org,source_id,source_status);
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."guard_source_inventory_ownership"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."guard_source_inventory_ownership"() FROM PUBLIC, "erp_app", "erp_runtime";
