-- Reviewed enforcement: inventory.inventory_documents:inventory_inventory_documents_landed_cost
CREATE FUNCTION "erp_trade_commands_v2"."post_landed_cost_adjustment"(p_org_id uuid, p_document_id uuid, p_actor_id uuid, p_idempotency_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE claim_id uuid; replay_id uuid; doc inventory.inventory_documents%ROWTYPE;
        line inventory.inventory_document_lines%ROWTYPE;
        original_line inventory.inventory_document_lines%ROWTYPE;
        original_entry inventory.stock_ledger_entries%ROWTYPE;
        balance inventory.stock_balances%ROWTYPE;
        new_average numeric(20,4); command_posted_at timestamptz;
        quantity_total numeric(20,6); value_total numeric(20,2); actual_count bigint;
        original_document_id uuid;
BEGIN
    PERFORM erp_trade_commands.assert_context(p_org_id,p_actor_id);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      p_org_id,p_actor_id,'inventory.landed_cost.post',p_idempotency_key_hash,p_request_hash,p_expires_at
    );
    IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
    SELECT * INTO STRICT doc FROM inventory.inventory_documents
     WHERE org_id=p_org_id AND id=p_document_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('inventory.document.post',doc.branch_id);
    command_posted_at := pg_catalog.transaction_timestamp();

    IF doc.document_type='cost_adjustment' THEN
        PERFORM erp_trade_commands_v2.assert_landed_cost_document(p_org_id,p_document_id);
        FOR line IN SELECT * FROM inventory.inventory_document_lines
                     WHERE org_id=p_org_id AND inventory_document_id=p_document_id
                     ORDER BY line_number,id
        LOOP
            SELECT * INTO STRICT balance FROM inventory.stock_balances
             WHERE org_id=p_org_id AND location_id=line.from_location_id
               AND product_id=line.product_id AND batch_id=line.batch_id FOR UPDATE;
            IF balance.on_hand_quantity<=0 OR balance.inventory_value+line.extended_cost<0 THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost adjustment would create empty or negative-value inventory';
            END IF;
            new_average := pg_catalog.round(
                (balance.inventory_value+line.extended_cost)/balance.on_hand_quantity,4
            );
            PERFORM erp_trade_commands.emit_entry(
                p_org_id,p_document_id,line.id,'value_adjustment',line.from_location_id,
                0,new_average,line.extended_cost,NULL,p_actor_id,command_posted_at
            );
        END LOOP;
    ELSIF doc.document_type='reversal' THEN
        SELECT original.id INTO original_document_id FROM inventory.inventory_documents AS original
         WHERE original.org_id=p_org_id AND original.id=doc.reverses_document_id
           AND original.document_type='cost_adjustment' AND original.status='posted'
         FOR UPDATE;
        IF doc.reverses_document_id IS NULL OR original_document_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost reversal requires a posted cost-adjustment source';
        END IF;
        IF (SELECT count(*) FROM inventory.inventory_document_lines WHERE org_id=p_org_id AND inventory_document_id=p_document_id)
           <> (SELECT count(*) FROM inventory.inventory_document_lines WHERE org_id=p_org_id AND inventory_document_id=doc.reverses_document_id) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost reversal line cardinality differs from its source';
        END IF;
        FOR line IN SELECT * FROM inventory.inventory_document_lines
                     WHERE org_id=p_org_id AND inventory_document_id=p_document_id
                     ORDER BY line_number,id
        LOOP
            SELECT * INTO STRICT original_line FROM inventory.inventory_document_lines
             WHERE org_id=p_org_id AND inventory_document_id=doc.reverses_document_id
               AND line_number=line.line_number;
            SELECT * INTO STRICT original_entry FROM inventory.stock_ledger_entries
             WHERE org_id=p_org_id AND inventory_document_line_id=original_line.id
               AND entry_kind='value_adjustment' FOR SHARE;
            IF ROW(line.movement_kind,line.product_id,line.batch_id,line.from_location_id,
                   line.supplier_invoice_line_id,line.extended_cost)
               IS DISTINCT FROM ROW('value_adjustment',original_line.product_id,original_line.batch_id,
                   original_line.from_location_id,original_line.supplier_invoice_line_id,original_line.extended_cost) THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost reversal line differs from immutable source allocation';
            END IF;
            SELECT * INTO STRICT balance FROM inventory.stock_balances
             WHERE org_id=p_org_id AND location_id=original_entry.location_id
               AND product_id=original_entry.product_id AND batch_id=original_entry.batch_id FOR UPDATE;
            IF balance.on_hand_quantity<=0 OR balance.inventory_value-original_entry.value_delta<0 THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost reversal would create empty or negative-value inventory';
            END IF;
            new_average := pg_catalog.round(
                (balance.inventory_value-original_entry.value_delta)/balance.on_hand_quantity,4
            );
            PERFORM erp_trade_commands.emit_entry(
                p_org_id,p_document_id,line.id,'reversal',original_entry.location_id,
                0,new_average,-original_entry.value_delta,original_entry.id,p_actor_id,command_posted_at
            );
        END LOOP;
    ELSE
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost command accepts only cost adjustments and their reversals';
    END IF;

    SELECT COALESCE(sum(pg_catalog.abs(base_quantity)),0),COALESCE(sum(pg_catalog.abs(extended_cost)),0)
      INTO quantity_total,value_total FROM inventory.inventory_document_lines
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF quantity_total<>0 OR doc.total_abs_base_quantity IS DISTINCT FROM 0
       OR doc.total_value IS DISTINCT FROM value_total THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost header totals do not equal exact absolute allocation totals';
    END IF;
    SELECT count(*) INTO actual_count FROM inventory.stock_ledger_entries
     WHERE org_id=p_org_id AND inventory_document_id=p_document_id;
    IF actual_count<>(SELECT count(*) FROM inventory.inventory_document_lines WHERE org_id=p_org_id AND inventory_document_id=p_document_id) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='landed-cost ledger cardinality is not exact';
    END IF;
    UPDATE inventory.inventory_documents SET status='posted',posted_at=command_posted_at,
           posted_by_membership_id=p_actor_id,updated_at=command_posted_at,
           updated_by_membership_id=p_actor_id,row_version=row_version+1
     WHERE org_id=p_org_id AND id=p_document_id AND status='approved';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='landed-cost state transition lost its lock';
    END IF;
    PERFORM erp_trade_commands.finish_claim(p_org_id,claim_id,'inventory.inventory_documents',p_document_id);
    RETURN p_document_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."post_landed_cost_adjustment"(uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."post_landed_cost_adjustment"(uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT USAGE ON SCHEMA "erp_trade_commands_v2" TO "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_trade_commands_v2"."post_landed_cost_adjustment"(uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
-- Reviewed enforcement: inventory.inventory_documents:inventory_inventory_documents_physical_logistics
CREATE FUNCTION "erp_trade_commands"."assert_physical_logistics"(p_org_id uuid, p_document_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE doc inventory.inventory_documents%ROWTYPE; source_status text; destination_status text; transporter_status text;
BEGIN
    SELECT * INTO STRICT doc FROM inventory.inventory_documents
     WHERE org_id=p_org_id AND id=p_document_id FOR SHARE;
    IF NOT doc.physical_movement_required THEN RETURN; END IF;
    SELECT status INTO source_status FROM core.branches
     WHERE org_id=p_org_id AND id=doc.branch_id FOR SHARE;
    IF source_status<>'active' OR doc.movement_started_at>pg_catalog.transaction_timestamp()
       OR (doc.transport_mode<>'in_person' AND pg_catalog.num_nonnulls(
             doc.transporter_party_id,doc.transporter_name_snapshot)=0) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='physical movement snapshot lacks active source, carrier, or valid start time';
    END IF;
    IF doc.document_type='transfer' THEN
      SELECT status INTO destination_status FROM core.branches
       WHERE org_id=p_org_id AND id=doc.destination_branch_id FOR SHARE;
      IF doc.destination_branch_id IS NULL OR doc.destination_branch_id=doc.branch_id OR destination_status<>'active' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='interbranch transfer requires a distinct active destination branch'; END IF;
    ELSIF doc.destination_branch_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='external physical issue cannot claim an internal destination branch';
    END IF;
    IF doc.transporter_party_id IS NOT NULL THEN
      SELECT status INTO transporter_status FROM parties.parties
       WHERE org_id=p_org_id AND id=doc.transporter_party_id FOR SHARE;
      IF transporter_status<>'active' OR doc.transporter_name_snapshot IS NULL
         OR pg_catalog.btrim(doc.transporter_name_snapshot)='' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='transporter snapshot requires the exact active party and frozen name'; END IF;
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."assert_physical_logistics"(uuid,uuid) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."assert_physical_logistics"(uuid,uuid) FROM PUBLIC, "erp_app", "erp_runtime";
-- Reviewed enforcement: inventory.locations:inventory_locations_invariant_1
CREATE FUNCTION "erp_trade_invariants"."guard_location_branch"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    expected_branch uuid;
BEGIN
    IF TG_TABLE_NAME = 'locations' THEN
        IF NEW.branch_id IS DISTINCT FROM OLD.branch_id AND (
            EXISTS (SELECT 1 FROM inventory.stock_ledger_entries e WHERE e.org_id=OLD.org_id AND e.location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM inventory.stock_balances b WHERE b.org_id=OLD.org_id AND b.location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM inventory.reservations r WHERE r.org_id=OLD.org_id AND r.location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM inventory.inventory_document_lines l WHERE l.org_id=OLD.org_id AND (l.from_location_id=OLD.id OR l.to_location_id=OLD.id))
            OR EXISTS (SELECT 1 FROM sales.dispatch_lines l WHERE l.org_id=OLD.org_id AND l.from_location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM sales.return_lines l WHERE l.org_id=OLD.org_id AND l.disposition_location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM procurement.goods_receipt_lines l WHERE l.org_id=OLD.org_id AND l.location_id=OLD.id)
            OR EXISTS (SELECT 1 FROM procurement.purchase_return_lines l WHERE l.org_id=OLD.org_id AND l.from_location_id=OLD.id)
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'referenced inventory location branch is immutable';
        END IF;
        RETURN NEW;
    END IF;
    SELECT location.branch_id INTO expected_branch
      FROM inventory.locations AS location
     WHERE location.org_id = NEW.org_id AND location.id = NEW.location_id
     FOR SHARE;
    IF expected_branch IS NULL OR NEW.branch_id IS DISTINCT FROM expected_branch THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'stock fact branch does not match its location';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_location_branch"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_location_branch"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "locations_branch_guard_ct" AFTER UPDATE ON "inventory"."locations" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_location_branch"();
CREATE CONSTRAINT TRIGGER "stock_ledger_location_branch_guard_ct" AFTER INSERT OR UPDATE ON "inventory"."stock_ledger_entries" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_location_branch"();
CREATE CONSTRAINT TRIGGER "stock_balances_location_branch_guard_ct" AFTER INSERT OR UPDATE ON "inventory"."stock_balances" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_location_branch"();
