    UPDATE parties.supplier_accounts SET payment_days=change_supplier_terms.payment_days,
      updated_at=pg_catalog.transaction_timestamp(),updated_by_membership_id=actor_id,row_version=row_version+1
      WHERE org_id=organization_id AND id=supplier_account_id AND row_version=expected_row_version;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='supplier account changed before term update';
    END IF;
    DELETE FROM "erp_core_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid()
      AND transaction_id=pg_catalog.txid_current() AND scope='supplier_terms'
      AND org_id=organization_id AND entity_id=supplier_account_id;
    PERFORM "erp_core_commands"."finish_claim"(organization_id,claim.id,'parties.supplier_accounts',supplier_account_id,
      pg_catalog.jsonb_build_object('supplier_account_id',supplier_account_id,'row_version',expected_row_version+1));
    RETURN supplier_account_id;
END
$function$;
ALTER FUNCTION "erp_core_commands"."change_supplier_terms"(organization_id uuid, supplier_account_id uuid, expected_row_version bigint, payment_days integer, idempotency_key_hash bytea, idempotency_expires_at timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_core_commands"."change_supplier_terms"(organization_id uuid, supplier_account_id uuid, expected_row_version bigint, payment_days integer, idempotency_key_hash bytea, idempotency_expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_core_commands"."change_supplier_terms"(organization_id uuid, supplier_account_id uuid, expected_row_version bigint, payment_days integer, idempotency_key_hash bytea, idempotency_expires_at timestamptz) TO "erp_app";
-- Reviewed enforcement: parties.tax_registrations:tax_registrations_state_and_period
CREATE FUNCTION "erp_stable_invariants"."guard_tax_registration"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
BEGIN
    IF OLD.status = 'pending_verification' AND NEW.status NOT IN ('pending_verification','active','cancelled','expired')
       OR OLD.status = 'active' AND NEW.status NOT IN ('active','suspended','cancelled','expired')
       OR OLD.status = 'suspended' AND NEW.status NOT IN ('suspended','active','cancelled','expired')
       OR OLD.status IN ('cancelled','expired') AND NEW.status IS DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invalid tax registration lifecycle transition';
    END IF;
    IF OLD.verified_at IS NOT NULL AND ROW(
        NEW.party_id, NEW.registration_type, NEW.registration_number, NEW.registered_legal_name,
        NEW.state_code, NEW.taxpayer_type, NEW.valid_from, NEW.valid_until, NEW.verified_at
    ) IS DISTINCT FROM ROW(
        OLD.party_id, OLD.registration_type, OLD.registration_number, OLD.registered_legal_name,
        OLD.state_code, OLD.taxpayer_type, OLD.valid_from, OLD.valid_until, OLD.verified_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'verified statutory identity history is immutable';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_stable_invariants"."guard_tax_registration"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_stable_invariants"."guard_tax_registration"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "tax_registrations_state_guard_ct" AFTER UPDATE ON "parties"."tax_registrations" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_stable_invariants"."guard_tax_registration"();
-- Reviewed enforcement: procurement.goods_receipt_lines:procurement_goods_receipt_lines_invariant_1
CREATE FUNCTION "erp_trade_invariants"."guard_goods_receipt_line"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    source procurement.purchase_order_lines%ROWTYPE;
    receipt procurement.goods_receipts%ROWTYPE;
    batch_product uuid;
    location_branch uuid;
    billed_total numeric(20,6);
    free_total numeric(20,6);
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT * INTO receipt FROM procurement.goods_receipts WHERE org_id=OLD.org_id AND id=OLD.goods_receipt_id FOR SHARE;
        IF receipt.status IN ('posted','reversed') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted goods receipt line is immutable';
        END IF;
        RETURN OLD;
    END IF;
    SELECT * INTO receipt FROM procurement.goods_receipts WHERE org_id=NEW.org_id AND id=NEW.goods_receipt_id FOR SHARE;
    IF receipt.status IN ('posted','reversed')
       AND (TG_OP = 'INSERT' OR NEW IS DISTINCT FROM OLD) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted goods receipt line is immutable';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':' || NEW.purchase_order_line_id::text, 95703173));
    SELECT * INTO source FROM procurement.purchase_order_lines WHERE org_id=NEW.org_id AND id=NEW.purchase_order_line_id FOR SHARE;
    SELECT product_id INTO batch_product FROM inventory.batches WHERE org_id=NEW.org_id AND id=NEW.batch_id FOR SHARE;
    SELECT branch_id INTO location_branch FROM inventory.locations WHERE org_id=NEW.org_id AND id=NEW.location_id FOR SHARE;
    IF source.id IS NULL OR source.line_kind <> 'product'
       OR source.product_id IS DISTINCT FROM NEW.product_id
       OR batch_product IS DISTINCT FROM NEW.product_id
       OR location_branch IS DISTINCT FROM receipt.branch_id
       OR source.uom_code IS DISTINCT FROM NEW.uom_code
       OR NEW.base_accepted_quantity IS DISTINCT FROM round(NEW.accepted_quantity * source.uom_conversion_factor, 6)
       OR NEW.base_free_quantity IS DISTINCT FROM round(NEW.free_quantity * source.uom_conversion_factor, 6) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'receipt line does not match ordered product, lot, branch, or UOM facts';
    END IF;
    SELECT COALESCE(sum(line.base_accepted_quantity),0),
           COALESCE(sum(line.base_free_quantity),0)
      INTO billed_total, free_total
      FROM procurement.goods_receipt_lines AS line
      JOIN procurement.goods_receipts AS parent ON parent.org_id=line.org_id AND parent.id=line.goods_receipt_id
      JOIN procurement.purchase_order_lines AS source_line ON source_line.org_id=line.org_id AND source_line.id=line.purchase_order_line_id
     WHERE line.org_id=NEW.org_id AND line.purchase_order_line_id=NEW.purchase_order_line_id
       AND (parent.status='posted' OR parent.id=NEW.goods_receipt_id);
    IF billed_total > source.base_billed_quantity OR free_total > source.base_free_quantity THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'cumulative receipt exceeds ordered billed or free quantity';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_goods_receipt_line"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_goods_receipt_line"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "goods_receipt_lines_source_cap_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "procurement"."goods_receipt_lines" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_goods_receipt_line"();
-- Reviewed enforcement: procurement.goods_receipts:procurement_goods_receipts_invariant_1
CREATE FUNCTION "erp_trade_commands"."guard_typed_source_posting"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
BEGIN
    IF TG_OP='DELETE' AND OLD.status IN ('posted','reversed') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted trade source evidence is immutable';
    END IF;
    IF TG_OP='UPDATE' AND OLD.status IN ('posted','reversed') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted trade source evidence is immutable';
    END IF;
    IF TG_OP<>'DELETE' AND NEW.status IN ('posted','reversed')
       AND current_user<>'erp_migration_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='typed trade source may post only through its canonical command';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."guard_typed_source_posting"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."guard_typed_source_posting"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "goods_receipts_command_guard" BEFORE INSERT OR UPDATE OR DELETE ON "procurement"."goods_receipts" FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands"."guard_typed_source_posting"();
CREATE FUNCTION "erp_trade_commands"."post_goods_receipt"(p_org_id uuid, p_goods_receipt_id uuid, p_inventory_document_id uuid, p_actor_id uuid, p_idempotency_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE claim_id uuid; replay_id uuid; source procurement.goods_receipts%ROWTYPE;
        v_purchase_order_id uuid; purchase_order_count integer; remaining_count integer;
BEGIN
    PERFORM erp_trade_commands.assert_context(p_org_id,p_actor_id);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      p_org_id,p_actor_id,'procurement.receipt.post',p_idempotency_key_hash,p_request_hash,p_expires_at
    );
    IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
    SELECT * INTO STRICT source FROM procurement.goods_receipts WHERE org_id=p_org_id AND id=p_goods_receipt_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('procurement.receipt.post',source.branch_id);
    PERFORM erp_trade_commands.assert_permission('inventory.document.post',source.branch_id);
    SELECT count(DISTINCT line.purchase_order_id)
      INTO purchase_order_count
      FROM procurement.goods_receipt_lines receipt_line
      JOIN procurement.purchase_order_lines line ON line.org_id=receipt_line.org_id
       AND line.id=receipt_line.purchase_order_line_id
     WHERE receipt_line.org_id=p_org_id AND receipt_line.goods_receipt_id=p_goods_receipt_id;
    SELECT line.purchase_order_id INTO v_purchase_order_id
      FROM procurement.goods_receipt_lines receipt_line
      JOIN procurement.purchase_order_lines line ON line.org_id=receipt_line.org_id
       AND line.id=receipt_line.purchase_order_line_id
     WHERE receipt_line.org_id=p_org_id AND receipt_line.goods_receipt_id=p_goods_receipt_id
     LIMIT 1;
    PERFORM 1 FROM procurement.purchase_orders purchase_order
     WHERE purchase_order.org_id=p_org_id AND purchase_order.id=v_purchase_order_id
       AND purchase_order.branch_id=source.branch_id
       AND purchase_order.supplier_account_id=source.supplier_account_id
       AND purchase_order.status IN ('approved','partially_received')
     FOR UPDATE;
    IF purchase_order_count<>1 OR NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='goods receipt must own lines from one exact receivable purchase order';
    END IF;
    IF EXISTS (
      SELECT 1 FROM procurement.purchase_order_lines ordered
       WHERE ordered.org_id=p_org_id AND ordered.purchase_order_id=v_purchase_order_id
         AND ordered.line_kind='product' AND (
           COALESCE((SELECT sum(receipt_line.base_accepted_quantity)
                       FROM procurement.goods_receipt_lines receipt_line
                       JOIN procurement.goods_receipts receipt ON receipt.org_id=receipt_line.org_id
                        AND receipt.id=receipt_line.goods_receipt_id
                      WHERE receipt_line.org_id=ordered.org_id
                        AND receipt_line.purchase_order_line_id=ordered.id
                        AND (receipt.status='posted' OR receipt.id=p_goods_receipt_id)),0)>ordered.base_billed_quantity
           OR COALESCE((SELECT sum(receipt_line.base_free_quantity)
                          FROM procurement.goods_receipt_lines receipt_line
                          JOIN procurement.goods_receipts receipt ON receipt.org_id=receipt_line.org_id
                           AND receipt.id=receipt_line.goods_receipt_id
                         WHERE receipt_line.org_id=ordered.org_id
                           AND receipt_line.purchase_order_line_id=ordered.id
                           AND (receipt.status='posted' OR receipt.id=p_goods_receipt_id)),0)>ordered.base_free_quantity
         )
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='goods receipt exceeds the locked accepted billed or free purchase-order ceiling';
    END IF;
    IF source.status<>'approved' OR NOT EXISTS (
        SELECT 1 FROM inventory.inventory_documents doc WHERE doc.org_id=p_org_id AND doc.id=p_inventory_document_id
          AND doc.goods_receipt_id=p_goods_receipt_id AND doc.document_type='purchase_receipt' AND doc.status='approved'
    ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='goods receipt requires one approved typed inventory receipt'; END IF;
    PERFORM erp_trade_commands.post_locked_document(p_org_id,p_inventory_document_id,p_actor_id);
    UPDATE procurement.goods_receipts SET status='posted',posted_at=pg_catalog.transaction_timestamp(),posted_by_membership_id=p_actor_id,
      updated_at=pg_catalog.transaction_timestamp(),updated_by_membership_id=p_actor_id,row_version=row_version+1
      WHERE org_id=p_org_id AND id=p_goods_receipt_id AND status='approved';
    SELECT count(*) INTO remaining_count
      FROM procurement.purchase_order_lines ordered
     WHERE ordered.org_id=p_org_id AND ordered.purchase_order_id=v_purchase_order_id
       AND ordered.line_kind='product' AND (
         COALESCE((SELECT sum(receipt_line.base_accepted_quantity)
                     FROM procurement.goods_receipt_lines receipt_line
                     JOIN procurement.goods_receipts receipt ON receipt.org_id=receipt_line.org_id
                      AND receipt.id=receipt_line.goods_receipt_id
                    WHERE receipt_line.org_id=ordered.org_id
                      AND receipt_line.purchase_order_line_id=ordered.id
                      AND receipt.status='posted'),0)<ordered.base_billed_quantity
         OR COALESCE((SELECT sum(receipt_line.base_free_quantity)
                        FROM procurement.goods_receipt_lines receipt_line
                        JOIN procurement.goods_receipts receipt ON receipt.org_id=receipt_line.org_id
                         AND receipt.id=receipt_line.goods_receipt_id
                       WHERE receipt_line.org_id=ordered.org_id
                         AND receipt_line.purchase_order_line_id=ordered.id
                         AND receipt.status='posted'),0)<ordered.base_free_quantity
       );
    UPDATE procurement.purchase_orders
       SET status=CASE WHEN remaining_count=0 THEN 'received' ELSE 'partially_received' END,
           updated_at=pg_catalog.transaction_timestamp(),updated_by_membership_id=p_actor_id,
           row_version=row_version+1
     WHERE org_id=p_org_id AND id=v_purchase_order_id AND status IN ('approved','partially_received');
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='purchase order receipt lifecycle changed during posting';
    END IF;
    PERFORM erp_trade_commands.finish_claim(p_org_id,claim_id,'procurement.goods_receipts',p_goods_receipt_id);
    RETURN p_goods_receipt_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."post_goods_receipt"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."post_goods_receipt"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_trade_commands"."post_goods_receipt"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
-- Reviewed enforcement: procurement.purchase_order_advance_allocations:purchase_order_advance_allocations_cross_row_guard
CREATE FUNCTION "erp_trade_commands_v2"."guard_purchase_order_advance_allocation"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE payment finance.payments%ROWTYPE; line procurement.purchase_order_lines%ROWTYPE;
        purchase_order procurement.purchase_orders%ROWTYPE; supplier parties.supplier_accounts%ROWTYPE;
        item finance.open_items%ROWTYPE; original procurement.purchase_order_advance_allocations%ROWTYPE; allocated numeric(20,2);
BEGIN
    IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier advance allocations are append-only'; END IF;
    SELECT * INTO payment FROM finance.payments WHERE org_id=NEW.org_id AND id=NEW.payment_id FOR UPDATE;
    SELECT * INTO line FROM procurement.purchase_order_lines WHERE org_id=NEW.org_id AND id=NEW.purchase_order_line_id FOR SHARE;
    SELECT * INTO purchase_order FROM procurement.purchase_orders WHERE org_id=NEW.org_id AND id=line.purchase_order_id FOR SHARE;
    SELECT * INTO supplier FROM parties.supplier_accounts WHERE org_id=NEW.org_id AND id=NEW.supplier_account_id FOR SHARE;
    SELECT * INTO item FROM finance.open_items WHERE org_id=NEW.org_id AND id=NEW.prepayment_open_item_id FOR SHARE;
    IF NEW.status='reversed' THEN
      SELECT * INTO original FROM procurement.purchase_order_advance_allocations
       WHERE org_id=NEW.org_id AND id=NEW.reversal_of_allocation_id FOR SHARE;
      IF original.status<>'posted' OR payment.status<>'posted' OR payment.direction<>'receipt'
         OR item.status<>'reversed' OR ROW(NEW.purchase_order_line_id,NEW.supplier_account_id,NEW.branch_id,
            NEW.cash_disbursed_amount,NEW.withheld_amount,NEW.gross_advance_amount)
            IS DISTINCT FROM ROW(original.purchase_order_line_id,original.supplier_account_id,original.branch_id,
            original.cash_disbursed_amount,original.withheld_amount,original.gross_advance_amount)
         OR (NEW.withholding_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tax.withholdings reversal
             WHERE reversal.org_id=NEW.org_id AND reversal.id=NEW.withholding_id AND reversal.status='reversed'
               AND reversal.reversal_of_withholding_id=original.withholding_id)) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier advance reversal must exactly compensate immutable original';
      END IF;
      RETURN NEW;
    END IF;
    IF payment.status<>'posted' OR payment.direction<>'disbursement' OR payment.currency_code<>'INR'
       OR line.line_kind<>'product' OR line.product_id IS NULL
       OR purchase_order.status NOT IN ('approved','partially_received','received')
       OR purchase_order.supplier_account_id<>NEW.supplier_account_id OR purchase_order.branch_id<>NEW.branch_id
       OR supplier.party_id<>payment.party_id OR NEW.allocation_date<>payment.payment_date
       OR NEW.gross_advance_amount<>NEW.functional_gross_advance_amount
       OR NEW.gross_advance_amount<>NEW.cash_disbursed_amount+NEW.withheld_amount
       OR item.item_side<>'receivable' OR item.party_id<>payment.party_id OR item.currency_code<>'INR'
       OR item.principal_amount<>NEW.gross_advance_amount OR item.functional_principal_amount<>NEW.gross_advance_amount
       OR NOT EXISTS (SELECT 1 FROM finance.accounting_events event WHERE event.org_id=NEW.org_id
                       AND event.id=item.accounting_event_id AND event.payment_id=payment.id)
       OR (NEW.withheld_amount>0 AND NOT EXISTS (
           SELECT 1 FROM tax.withholdings withholding WHERE withholding.org_id=NEW.org_id
            AND withholding.id=NEW.withholding_id AND withholding.status='deducted'
            AND withholding.purchase_order_advance_allocation_id=NEW.id
            AND withholding.triggered_by_payment_id=payment.id
            AND withholding.withheld_amount=NEW.withheld_amount)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier advance lacks exact posted goods-payment and prepayment provenance';
    END IF;
    SELECT coalesce(sum(a.cash_disbursed_amount),0) INTO allocated
      FROM procurement.purchase_order_advance_allocations a
     WHERE a.org_id=NEW.org_id AND a.payment_id=NEW.payment_id AND a.status='posted';
    IF allocated<>payment.amount THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted payment must be fully allocated to typed goods advances'; END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."guard_purchase_order_advance_allocation"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."guard_purchase_order_advance_allocation"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "purchase_order_advance_allocations_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "procurement"."purchase_order_advance_allocations" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands_v2"."guard_purchase_order_advance_allocation"();
-- Reviewed enforcement: procurement.purchase_order_lines:procurement_purchase_order_lines_invariant_1
CREATE FUNCTION "erp_trade_commands_v2"."assert_purchase_order_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header procurement.purchase_orders%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM procurement.purchase_orders
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status<>'submitted' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated order is no longer submitted';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'procurement.purchase_order.approve'
       OR p_input->>'resource_type'<>'purchase_order'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'operation'<>'procurement.purchase_order.approve'
       OR p_output->>'resource_type'<>'purchase_order'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted order';
    END IF;

    SELECT count(*) INTO expected_lines FROM procurement.purchase_order_lines
     WHERE org_id=p_org_id AND purchase_order_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM procurement.purchase_order_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.purchase_order_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR tax_version.ruleset_version IS DISTINCT FROM header.calculation_ruleset_version
         OR header.order_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.order_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."assert_purchase_order_artifact"(uuid,uuid,jsonb,jsonb) OWNER TO "erp_migration_owner";
