CREATE FUNCTION "erp_trade_commands_v2"."guard_approved_purchase_order_lines"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_id uuid; parent_status text;
BEGIN
    parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.purchase_order_id ELSE NEW.purchase_order_id END;
    SELECT status INTO STRICT parent_status FROM procurement.purchase_orders
     WHERE org_id=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
       AND id=parent_id FOR SHARE;
    IF parent_status IN ('approved','partially_received','received') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved commercial lines are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
