-- Reviewed enforcement: procurement.purchase_returns:procurement_purchase_returns_invariant_1
CREATE FUNCTION "erp_commercial_commands"."assert_purchase_return_artifact"(organization_id uuid, resource_id uuid, input_doc jsonb, output_doc jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header procurement.purchase_returns%ROWTYPE; original procurement.supplier_invoices%ROWTYPE;
        expected_lines bigint; bad_count bigint; cumulative_grand numeric(20,2); cumulative_rounding numeric(20,2);
BEGIN
    SELECT * INTO STRICT header FROM procurement.purchase_returns WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    IF header.status NOT IN ('draft','approved','posted') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return is not postable or posted'; END IF;
    IF header.return_source_kind='invoiced' THEN
      SELECT * INTO STRICT original FROM procurement.supplier_invoices WHERE org_id=organization_id AND id=header.supplier_invoice_id FOR UPDATE;
    END IF;
    IF header.return_source_kind='invoiced' THEN PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||original.id::text,734821)); END IF;
    PERFORM erp_calculation_authority.assert_input_schema(input_doc);
    PERFORM erp_calculation_authority.assert_output_schema(output_doc);
    IF input_doc->>'calculation_kind'<>'reversal' OR input_doc->>'operation'<>'procurement.purchase_return.post'
       OR input_doc#>>'{reversal,gst_tax_treatment}' IS DISTINCT FROM header.gst_tax_treatment
       OR output_doc->>'gst_tax_treatment' IS DISTINCT FROM header.gst_tax_treatment
       OR input_doc->>'resource_type'<>'purchase_return' OR input_doc->>'resource_id'<>resource_id::text
       OR (input_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'operation'<>'procurement.purchase_return.post' OR output_doc->>'resource_type'<>'purchase_return'
       OR output_doc->>'resource_id'<>resource_id::text
       OR (output_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR ROW((output_doc#>>'{totals,net_value_total}')::numeric,(output_doc#>>'{totals,gst_taxable_total}')::numeric,
              (output_doc#>>'{totals,cgst_total}')::numeric,(output_doc#>>'{totals,sgst_total}')::numeric,
              (output_doc#>>'{totals,igst_total}')::numeric,(output_doc#>>'{totals,cess_total}')::numeric,
              (output_doc#>>'{totals,recipient_assessed_tax_total}')::numeric,(output_doc#>>'{totals,rounding_adjustment}')::numeric,
              (output_doc#>>'{totals,grand_total}')::numeric)
          IS DISTINCT FROM ROW(header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,
              header.igst_total,header.cess_total,header.recipient_assessed_tax_total,header.rounding_adjustment,header.grand_total)
       OR (header.return_source_kind='invoiced' AND (header.supplier_account_id IS DISTINCT FROM original.supplier_account_id OR
           header.zero_rated_payment_mode IS DISTINCT FROM original.zero_rated_payment_mode
           OR header.tax_charge_mechanism IS DISTINCT FROM original.tax_charge_mechanism
           OR header.rounding_policy IS DISTINCT FROM original.rounding_policy
           OR header.calculation_ruleset_version IS DISTINCT FROM original.calculation_ruleset_version
           OR input_doc#>>'{original,resource_id}' IS DISTINCT FROM original.id::text
           OR ROW((input_doc#>>'{original,totals,net_value_total}')::numeric,(input_doc#>>'{original,totals,gst_taxable_total}')::numeric,
                  (input_doc#>>'{original,totals,cgst_total}')::numeric,(input_doc#>>'{original,totals,sgst_total}')::numeric,
                  (input_doc#>>'{original,totals,igst_total}')::numeric,(input_doc#>>'{original,totals,cess_total}')::numeric,
                  (input_doc#>>'{original,totals,rounding_adjustment}')::numeric,(input_doc#>>'{original,totals,grand_total}')::numeric)
              IS DISTINCT FROM ROW(original.net_value_total,original.gst_taxable_total,original.cgst_total,original.sgst_total,
                  original.igst_total,original.cess_total,original.rounding_adjustment,original.grand_total))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact header or original snapshot differs';
    END IF;
    SELECT count(*) INTO expected_lines FROM procurement.purchase_return_lines WHERE org_id=organization_id AND purchase_return_id=resource_id;
    IF expected_lines=0 OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,products}')<>expected_lines
       OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,charges}')<>0
       OR pg_catalog.jsonb_array_length(output_doc->'lines')<>expected_lines THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line cardinality differs';
    END IF;
    WITH reversal_input AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,products}')),
         reversal_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(output_doc->'lines')),
         original_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{original,lines}'))
    SELECT count(*) INTO bad_count
      FROM procurement.purchase_return_lines line
      LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id LEFT JOIN procurement.goods_receipt_lines receipt ON receipt.org_id=line.org_id AND receipt.id=line.goods_receipt_line_id LEFT JOIN inventory.locations return_location ON return_location.org_id=line.org_id AND return_location.id=line.from_location_id
      LEFT JOIN procurement.supplier_invoice_lines source ON source.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id AND source.id=allocation.supplier_invoice_line_id AND source.supplier_invoice_id=header.supplier_invoice_id
      LEFT JOIN tax.tax_code_versions tax_version ON tax_version.id=line.tax_code_version_id
      LEFT JOIN reversal_input requested ON requested.item->>'line_id'=(source.id)::text
      LEFT JOIN reversal_output calculated ON calculated.item->>'line_id'=(source.id)::text
      LEFT JOIN original_output original_line ON original_line.item->>'line_id'=(source.id)::text
     WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
       AND (header.return_source_kind='invoiced') AND (requested.item IS NULL OR calculated.item IS NULL OR original_line.item IS NULL
         OR line.gst_tax_treatment IS DISTINCT FROM header.gst_tax_treatment
         OR requested.item->>'value_basis' IS DISTINCT FROM line.reversal_value_basis
         OR (requested.item->>'final_residual')::boolean IS DISTINCT FROM line.final_residual
         OR (requested.item->>'reversed_billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
         OR (requested.item->>'reversed_free_quantity')::numeric IS DISTINCT FROM line.free_quantity
         OR (requested.item->>'reversed_base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
         OR (requested.item->>'reversed_base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
         OR ROW((calculated.item->>'net_value_amount')::numeric,(calculated.item->>'gst_taxable_value')::numeric,
                (calculated.item->>'cgst_rate')::numeric,(calculated.item->>'sgst_rate')::numeric,
                (calculated.item->>'igst_rate')::numeric,(calculated.item->>'cess_rate')::numeric,
                (calculated.item->>'cgst_amount')::numeric,(calculated.item->>'sgst_amount')::numeric,
                (calculated.item->>'igst_amount')::numeric,(calculated.item->>'cess_amount')::numeric,
                (calculated.item->>'line_total')::numeric,(calculated.item->>'final_residual')::boolean)
           IS DISTINCT FROM ROW(line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,line.igst_rate,
                line.cess_rate,line.cgst_amount,line.sgst_amount,line.igst_amount,line.cess_amount,line.line_total,line.final_residual)
         OR ROW((original_line.item->>'net_value_amount')::numeric,(original_line.item->>'gst_taxable_value')::numeric,
                (original_line.item->>'cgst_rate')::numeric,(original_line.item->>'sgst_rate')::numeric,
                (original_line.item->>'igst_rate')::numeric,(original_line.item->>'cess_rate')::numeric,
                (original_line.item->>'cgst_amount')::numeric,(original_line.item->>'sgst_amount')::numeric,
                (original_line.item->>'igst_amount')::numeric,(original_line.item->>'cess_amount')::numeric,
                (original_line.item->>'line_total')::numeric)
           IS DISTINCT FROM ROW(source.net_value_amount,source.gst_taxable_value,source.cgst_rate,source.sgst_rate,source.igst_rate,
                source.cess_rate,source.cgst_amount,source.sgst_amount,source.igst_amount,source.cess_amount,source.line_total)

         OR source.id IS NULL
         OR source.product_id IS DISTINCT FROM line.product_id
         OR source.uom_conversion_factor IS DISTINCT FROM line.uom_conversion_factor
         OR source.quoted_unit_rate IS DISTINCT FROM line.quoted_unit_rate
         OR source.price_basis IS DISTINCT FROM line.price_basis
         OR source.free_supply_tax_treatment IS DISTINCT FROM line.free_supply_tax_treatment
         OR source.tax_classification_code_snapshot IS DISTINCT FROM line.hsn_code_snapshot
         OR source.tax_charge_mechanism IS DISTINCT FROM line.tax_charge_mechanism
         OR source.tax_code_version_id IS DISTINCT FROM line.tax_code_version_id
         OR source.taxability_snapshot IS DISTINCT FROM line.taxability_snapshot
         OR tax_version.id IS NULL OR tax_version.ruleset_version IS DISTINCT FROM header.calculation_ruleset_version
         OR original.supplier_invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND original.supplier_invoice_date>tax_version.effective_to)

         OR allocation.goods_receipt_line_id IS DISTINCT FROM line.goods_receipt_line_id
         OR receipt.id IS NULL OR return_location.id IS NULL
         OR return_location.branch_id IS DISTINCT FROM header.branch_id OR return_location.status<>'active'
         OR ROW(receipt.product_id,receipt.batch_id,receipt.location_id)
            IS DISTINCT FROM ROW(line.product_id,line.batch_id,line.from_location_id)
         OR line.base_billed_quantity>allocation.allocated_base_billed_quantity OR line.base_free_quantity>allocation.allocated_base_free_quantity);
    IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line differs from locked original'; END IF;

    IF header.return_source_kind='uninvoiced' THEN
      WITH reversal_input AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,products}')),
           reversal_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(output_doc->'lines')),
           original_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{original,lines}'))
      SELECT count(*) INTO bad_count
        FROM procurement.purchase_return_lines line
        JOIN procurement.goods_receipt_lines receipt
          ON receipt.org_id=line.org_id AND receipt.id=line.goods_receipt_line_id
        JOIN procurement.goods_receipts receipt_header
          ON receipt_header.org_id=receipt.org_id AND receipt_header.id=receipt.goods_receipt_id
        JOIN inventory.locations receipt_location
          ON receipt_location.org_id=receipt.org_id AND receipt_location.id=receipt.location_id
        LEFT JOIN procurement.supplier_invoice_receipt_allocations forbidden
          ON forbidden.org_id=line.org_id AND forbidden.id=line.supplier_invoice_receipt_allocation_id
        LEFT JOIN reversal_input requested ON requested.item->>'line_id'=line.goods_receipt_line_id::text
        LEFT JOIN reversal_output calculated ON calculated.item->>'line_id'=line.goods_receipt_line_id::text
        LEFT JOIN original_output original_line ON original_line.item->>'line_id'=line.goods_receipt_line_id::text
       WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
         AND (line.gst_tax_treatment IS DISTINCT FROM header.gst_tax_treatment
           OR forbidden.id IS NOT NULL OR requested.item IS NULL OR calculated.item IS NULL OR original_line.item IS NULL
           OR receipt_header.status<>'posted' OR receipt_header.branch_id IS DISTINCT FROM header.branch_id
           OR receipt_header.supplier_account_id IS DISTINCT FROM header.supplier_account_id
           OR receipt_location.status<>'active' OR receipt_location.branch_id IS DISTINCT FROM header.branch_id
           OR requested.item->>'value_basis' IS DISTINCT FROM line.reversal_value_basis
           OR (requested.item->>'final_residual')::boolean IS DISTINCT FROM line.final_residual
           OR (requested.item->>'reversed_billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
           OR (requested.item->>'reversed_free_quantity')::numeric IS DISTINCT FROM line.free_quantity
           OR (requested.item->>'reversed_base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
           OR (requested.item->>'reversed_base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
           OR ROW((calculated.item->>'net_value_amount')::numeric,(calculated.item->>'gst_taxable_value')::numeric,
                  (calculated.item->>'cgst_amount')::numeric,(calculated.item->>'sgst_amount')::numeric,
                  (calculated.item->>'igst_amount')::numeric,(calculated.item->>'cess_amount')::numeric,
                  (calculated.item->>'line_total')::numeric,(calculated.item->>'final_residual')::boolean)
              IS DISTINCT FROM ROW(line.net_value_amount,line.gst_taxable_value,line.cgst_amount,line.sgst_amount,line.igst_amount,line.cess_amount,line.line_total,line.final_residual)
           OR (original_line.item->>'net_value_amount')::numeric IS DISTINCT FROM receipt.extended_cost
           OR (original_line.item->>'gst_taxable_value')::numeric<>0 OR (original_line.item->>'cgst_amount')::numeric<>0
           OR (original_line.item->>'sgst_amount')::numeric<>0 OR (original_line.item->>'igst_amount')::numeric<>0
           OR (original_line.item->>'cess_amount')::numeric<>0 OR (original_line.item->>'line_total')::numeric IS DISTINCT FROM receipt.extended_cost
           OR line.product_id IS DISTINCT FROM receipt.product_id
           OR line.batch_id IS DISTINCT FROM receipt.batch_id OR line.from_location_id IS DISTINCT FROM receipt.location_id
           OR line.quoted_unit_rate IS DISTINCT FROM receipt.unit_cost
           OR (receipt.accepted_quantity>0 AND pg_catalog.round(receipt.accepted_quantity*line.uom_conversion_factor,6) IS DISTINCT FROM receipt.base_accepted_quantity)
           OR (receipt.free_quantity>0 AND pg_catalog.round(receipt.free_quantity*line.uom_conversion_factor,6) IS DISTINCT FROM receipt.base_free_quantity)
           OR line.gst_taxable_value<>0 OR line.cgst_amount<>0 OR line.sgst_amount<>0 OR line.igst_amount<>0 OR line.cess_amount<>0
           OR line.net_value_amount<>pg_catalog.round((line.base_billed_quantity+line.base_free_quantity)*receipt.unit_cost,2)
           OR line.line_total<>line.net_value_amount);
      IF bad_count<>0 OR header.gst_taxable_total<>0 OR header.cgst_total<>0 OR header.sgst_total<>0
         OR header.igst_total<>0 OR header.cess_total<>0 OR header.recipient_assessed_tax_total<>0
         OR header.rounding_adjustment<>0 OR header.grand_total<>header.net_value_total THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='uninvoiced purchase return differs from locked goods-receipt cost or carries GST';
      END IF;
    END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT count(*) INTO bad_count FROM (
            SELECT source.id source_id,max(source.base_billed_quantity) source_billed,max(source.base_free_quantity) source_free,
                   sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free,bool_or(current.final_residual) final_residual
                   ,sum(all_returns.net_value_amount) reversed_net,sum(all_returns.gst_taxable_value) reversed_taxable,
                   sum(all_returns.cgst_amount) reversed_cgst,sum(all_returns.sgst_amount) reversed_sgst,sum(all_returns.igst_amount) reversed_igst,sum(all_returns.cess_amount) reversed_cess,sum(all_returns.line_total) reversed_total,
                   max(source.net_value_amount) source_net,max(source.gst_taxable_value) source_taxable,max(source.cgst_amount) source_cgst,max(source.sgst_amount) source_sgst,max(source.igst_amount) source_igst,max(source.cess_amount) source_cess,max(source.line_total) source_total
              FROM procurement.purchase_return_lines current
              JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=current.org_id AND allocation.id=current.supplier_invoice_receipt_allocation_id
              JOIN procurement.supplier_invoice_lines source ON source.org_id=allocation.org_id AND source.id=allocation.supplier_invoice_line_id
              JOIN procurement.supplier_invoice_receipt_allocations all_source_allocations ON all_source_allocations.org_id=source.org_id AND all_source_allocations.supplier_invoice_line_id=source.id
              JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=all_source_allocations.org_id AND all_returns.supplier_invoice_receipt_allocation_id=all_source_allocations.id
              JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
             WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY source.id
          ) cumulative WHERE reversed_billed>source_billed OR reversed_free>source_free
             OR reversed_taxable>source_taxable OR reversed_cgst>source_cgst OR reversed_sgst>source_sgst OR reversed_igst>source_igst OR reversed_cess>source_cess OR reversed_total>source_total
             OR (final_residual AND (reversed_billed<>source_billed OR reversed_free<>source_free OR reversed_total<>source_total));
          IF bad_count=0 THEN
            SELECT count(*) INTO bad_count FROM (
              SELECT current.supplier_invoice_receipt_allocation_id allocation_id,
                     max(allocation.allocated_base_billed_quantity) source_billed,max(allocation.allocated_base_free_quantity) source_free,
                     sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free
                FROM procurement.purchase_return_lines current
                JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=current.org_id AND allocation.id=current.supplier_invoice_receipt_allocation_id
                JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=allocation.org_id AND all_returns.supplier_invoice_receipt_allocation_id=allocation.id
                JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
               WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
               GROUP BY current.supplier_invoice_receipt_allocation_id
            ) allocation_total WHERE reversed_billed>source_billed OR reversed_free>source_free;
          END IF;
        ELSE
          SELECT count(*) INTO bad_count FROM (
            SELECT current.goods_receipt_line_id source_id,max(receipt.base_accepted_quantity) source_billed,max(receipt.base_free_quantity) source_free,
                   sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free,bool_or(current.final_residual) final_residual,
                   max(receipt.extended_cost) source_net,sum(all_returns.net_value_amount) reversed_net
              FROM procurement.purchase_return_lines current
              JOIN procurement.goods_receipt_lines receipt ON receipt.org_id=current.org_id AND receipt.id=current.goods_receipt_line_id
              JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=current.org_id AND all_returns.goods_receipt_line_id=current.goods_receipt_line_id
              JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
             WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY current.goods_receipt_line_id
          ) cumulative WHERE reversed_billed>source_billed OR reversed_free>source_free OR reversed_net>source_net
             OR (final_residual AND (reversed_billed<>source_billed OR reversed_free<>source_free OR reversed_net<>source_net));
        END IF;
        IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative purchase return exceeds source or final residual is incomplete'; END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT count(*) INTO bad_count FROM finance.adjustment_note_lines adjustment_line
            JOIN finance.adjustment_notes adjustment ON adjustment.org_id=adjustment_line.org_id AND adjustment.id=adjustment_line.adjustment_note_id
            JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=adjustment_line.org_id AND allocation.supplier_invoice_line_id=adjustment_line.supplier_invoice_line_id
            JOIN procurement.purchase_return_lines current ON current.org_id=allocation.org_id AND current.supplier_invoice_receipt_allocation_id=allocation.id
           WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND adjustment.status='posted'
             AND adjustment.sales_return_id IS NULL AND adjustment.purchase_return_id IS NULL;
          IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return after a generic adjustment is blocked because the reversal artifact cannot encode an adjusted original basis'; END IF;
          WITH current_sources AS (
            SELECT DISTINCT allocation.supplier_invoice_line_id source_id FROM procurement.purchase_return_lines line
             JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
            WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
          ), returned AS (
            SELECT allocation.supplier_invoice_line_id source_id,sum(line.base_billed_quantity) billed,sum(line.base_free_quantity) free,
                   sum(line.net_value_amount) net,sum(line.gst_taxable_value) taxable,sum(line.cgst_amount) cgst,sum(line.sgst_amount) sgst,
                   sum(line.igst_amount) igst,sum(line.cess_amount) cess,sum(line.line_total) total
              FROM procurement.purchase_return_lines line JOIN procurement.purchase_returns parent ON parent.org_id=line.org_id AND parent.id=line.purchase_return_id
              JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
              JOIN current_sources current ON current.source_id=allocation.supplier_invoice_line_id
             WHERE line.org_id=organization_id AND (parent.status='posted' OR parent.id=resource_id) GROUP BY allocation.supplier_invoice_line_id
          ), adjusted AS (
            SELECT line.supplier_invoice_line_id source_id,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_billed_quantity) billed,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_free_quantity) free,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.net_value_amount) net,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.gst_taxable_value) taxable,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cgst_amount) cgst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.sgst_amount) sgst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.igst_amount) igst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cess_amount) cess,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.line_total) total
              FROM finance.adjustment_note_lines line JOIN finance.adjustment_notes note ON note.org_id=line.org_id AND note.id=line.adjustment_note_id
              JOIN current_sources current ON current.source_id=line.supplier_invoice_line_id
             WHERE line.org_id=organization_id AND note.status='posted' AND note.sales_return_id IS NULL AND note.purchase_return_id IS NULL
             GROUP BY line.supplier_invoice_line_id
          )
          SELECT count(*) INTO bad_count FROM current_sources current JOIN procurement.supplier_invoice_lines source ON source.org_id=organization_id AND source.id=current.source_id
            JOIN returned ON returned.source_id=current.source_id LEFT JOIN adjusted ON adjusted.source_id=current.source_id
           WHERE coalesce(adjusted.billed,0)-returned.billed < -source.base_billed_quantity
              OR coalesce(adjusted.free,0)-returned.free < -source.base_free_quantity OR coalesce(adjusted.net,0)-returned.net < -source.net_value_amount
              OR coalesce(adjusted.taxable,0)-returned.taxable < -source.gst_taxable_value OR coalesce(adjusted.cgst,0)-returned.cgst < -source.cgst_amount
              OR coalesce(adjusted.sgst,0)-returned.sgst < -source.sgst_amount OR coalesce(adjusted.igst,0)-returned.igst < -source.igst_amount
              OR coalesce(adjusted.cess,0)-returned.cess < -source.cess_amount OR coalesce(adjusted.total,0)-returned.total < -source.line_total;
          IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='combined purchase returns and generic adjustments exceed the original invoice'; END IF;
        END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT coalesce(sum(prior.grand_total),0),coalesce(sum(prior.rounding_adjustment),0) INTO cumulative_grand,cumulative_rounding
            FROM procurement.purchase_returns prior WHERE prior.org_id=organization_id AND prior.supplier_invoice_id=header.supplier_invoice_id
              AND (prior.status='posted' OR prior.id=resource_id);
          IF cumulative_grand>original.grand_total OR (original.rounding_adjustment>=0 AND (cumulative_rounding<0 OR cumulative_rounding>original.rounding_adjustment))
             OR (original.rounding_adjustment<0 AND (cumulative_rounding>0 OR cumulative_rounding<original.rounding_adjustment)) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative purchase return header exceeds original invoice'; END IF;
        END IF;
    WITH current_sources AS (
             SELECT DISTINCT CASE WHEN header.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END source_id
               FROM procurement.purchase_return_lines line
               LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
              WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
           ), prior_rows AS (
             SELECT CASE WHEN prior.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END source_id,
                    line.reversal_value_basis,line.billed_quantity,line.free_quantity,line.base_billed_quantity,line.base_free_quantity,calculated.item
               FROM procurement.purchase_return_lines line
               JOIN procurement.purchase_returns prior ON prior.org_id=line.org_id AND prior.id=line.purchase_return_id AND prior.status='posted' AND prior.id<>resource_id
               LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
               JOIN current_sources current ON current.source_id=CASE WHEN prior.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END
               JOIN calculation.artifacts artifact ON artifact.org_id=prior.org_id AND artifact.purchase_return_id=prior.id AND artifact.status='consumed'
               JOIN LATERAL pg_catalog.jsonb_array_elements(pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb->'lines') calculated(item)
                 ON calculated.item->>'line_id'=current.source_id::text
              WHERE line.org_id=organization_id AND prior.return_source_kind=header.return_source_kind
                AND (header.return_source_kind='uninvoiced' OR prior.supplier_invoice_id=header.supplier_invoice_id)
           ), expected AS (
             SELECT source_id,min(reversal_value_basis) value_basis,count(DISTINCT reversal_value_basis) basis_count,
                    sum(billed_quantity) billed_quantity,sum(free_quantity) free_quantity,sum(base_billed_quantity) base_billed_quantity,sum(base_free_quantity) base_free_quantity,
                    sum((item->>'gross_amount')::numeric) gross_amount,sum((item->>'line_discount_amount')::numeric) line_discount_amount,
                    sum((item->>'document_discount_amount')::numeric) document_discount_amount,sum((item->>'net_value_amount')::numeric) net_value_amount,
                    sum((item->>'gst_taxable_value')::numeric) gst_taxable_value,sum((item->>'cgst_amount')::numeric) cgst_amount,
                    sum((item->>'sgst_amount')::numeric) sgst_amount,sum((item->>'igst_amount')::numeric) igst_amount,sum((item->>'cess_amount')::numeric) cess_amount
               FROM prior_rows GROUP BY source_id
           ), provided AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,prior_state,products}'))
           SELECT count(*) INTO bad_count FROM expected FULL JOIN provided ON provided.item->>'line_id'=expected.source_id::text
            WHERE expected.source_id IS NULL OR provided.item IS NULL OR expected.basis_count<>1 OR provided.item->>'value_basis' IS DISTINCT FROM expected.value_basis
               OR ROW((provided.item->>'reversed_billed_quantity')::numeric,(provided.item->>'reversed_free_quantity')::numeric,(provided.item->>'reversed_base_billed_quantity')::numeric,
                      (provided.item->>'reversed_base_free_quantity')::numeric,(provided.item->>'gross_price_amount')::numeric,(provided.item->>'line_discount_amount')::numeric,
                      (provided.item->>'document_discount_amount')::numeric,(provided.item->>'net_value_amount')::numeric,(provided.item->>'gst_taxable_value')::numeric,
                      (provided.item->>'cgst_amount')::numeric,(provided.item->>'sgst_amount')::numeric,(provided.item->>'igst_amount')::numeric,(provided.item->>'cess_amount')::numeric)
                  IS DISTINCT FROM ROW(expected.billed_quantity,expected.free_quantity,expected.base_billed_quantity,expected.base_free_quantity,expected.gross_amount,
                      expected.line_discount_amount,expected.document_discount_amount,expected.net_value_amount,expected.gst_taxable_value,
                      expected.cgst_amount,expected.sgst_amount,expected.igst_amount,expected.cess_amount);
           IF bad_count<>0 OR (input_doc#>>'{reversal,prior_state,rounding_adjustment}')::numeric IS DISTINCT FROM
              (SELECT coalesce(sum(prior.rounding_adjustment),0) FROM procurement.purchase_returns prior WHERE prior.org_id=organization_id
                AND prior.status='posted' AND prior.id<>resource_id AND prior.return_source_kind=header.return_source_kind
                AND (header.return_source_kind='uninvoiced' OR prior.supplier_invoice_id=header.supplier_invoice_id)) THEN
             RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='artifact prior state differs from locked posted purchase returns'; END IF;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."assert_purchase_return_artifact"(uuid,uuid,jsonb,jsonb) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."assert_purchase_return_artifact"(uuid,uuid,jsonb,jsonb) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."post_purchase_return"(organization_id uuid, resource_id uuid, artifact_id uuid, actor_id uuid, request_id uuid, command_request_id uuid, adjustment_note_id uuid, adjustment_note_number varchar, tax_document_id uuid, journal_id uuid, journal_number varchar, event_id uuid, allocation_id uuid, residual_open_item_id uuid, inventory_document_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header procurement.purchase_returns%ROWTYPE; original procurement.supplier_invoices%ROWTYPE; artifact calculation.artifacts%ROWTYPE;
        original_tax tax.documents%ROWTYPE; original_open finance.open_items%ROWTYPE; posting_line record;
        adjustment_rule tax.gst_adjustment_rule_versions%ROWTYPE; supplier_portal_line tax.portal_document_lines%ROWTYPE;
        claim_id uuid; replay_id uuid; input_doc jsonb; output_doc jsonb; consumed bytea; party_id uuid; party_account uuid;
        posted_time timestamptz:=pg_catalog.transaction_timestamp(); invoiced boolean; inventory_required boolean; tax_required boolean;
        line_no integer:=1; component_amount numeric(20,2); role_account uuid; role_key varchar; debit_total numeric(20,2); credit_total numeric(20,2);
        eligible_cgst numeric(20,2):=0; eligible_sgst numeric(20,2):=0; eligible_igst numeric(20,2):=0; eligible_cess numeric(20,2):=0;
        inventory_value numeric(20,2):=0; inventory_entries bigint:=0; expected_inventory_value numeric(20,2):=0; variance_value numeric(20,2):=0;
        outstanding numeric(20,2); applied numeric(20,2); residual numeric(20,2); original_event_id uuid; adjustment_deadline date;
        registration_scope_count bigint;
BEGIN
    PERFORM erp_trade_commands.assert_context(organization_id,actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM request_id THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='commercial request context mismatch'; END IF;
    SELECT * INTO STRICT header FROM procurement.purchase_returns WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    IF header.status<>'approved' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return is not in the required posting state'; END IF;
    PERFORM erp_trade_commands.assert_permission('procurement.return.post',header.branch_id);
    IF NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='finance journal permission denied'; END IF;
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(organization_id,actor_id,'procurement.purchase_return.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN IF replay_id<>resource_id THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='commercial replay mismatch'; END IF; RETURN replay_id; END IF;
    invoiced:=header.return_source_kind='invoiced';
    IF invoiced THEN
      SELECT * INTO STRICT original FROM procurement.supplier_invoices WHERE org_id=organization_id AND id=header.supplier_invoice_id FOR UPDATE;
      SELECT * INTO STRICT original_tax FROM tax.documents WHERE org_id=organization_id AND supplier_invoice_id=header.supplier_invoice_id FOR SHARE;
    END IF;
    SELECT * INTO STRICT adjustment_rule FROM tax.gst_adjustment_rule_versions rule
     WHERE rule.id=header.gst_adjustment_rule_version_id AND rule.status='active'
       AND rule.side='purchase' AND rule.direction='debit'
       AND rule.document_effect='decrease' AND rule.reason_code=header.reason_code
       AND rule.effective_from<=header.return_date
       AND (rule.effective_to IS NULL OR rule.effective_to>=header.return_date) FOR SHARE;
    IF adjustment_rule.tax_effect IS DISTINCT FROM header.gst_tax_treatment THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return GST treatment differs from effective reviewed adjustment rule'; END IF;
    tax_required:=adjustment_rule.tax_effect='statutory';
    IF tax_required AND NOT invoiced THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='uninvoiced return cannot be a statutory GST adjustment'; END IF;
    IF NOT tax_required AND (header.gst_taxable_total<>0 OR header.cgst_total<>0 OR header.sgst_total<>0 OR header.igst_total<>0 OR header.cess_total<>0 OR header.recipient_assessed_tax_total<>0) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial-only return cannot alter GST'; END IF;
    IF invoiced AND adjustment_rule.deadline_policy='days_after_original' THEN
      adjustment_deadline:=original.supplier_invoice_date+adjustment_rule.deadline_days;
    ELSIF invoiced AND adjustment_rule.deadline_policy='november_30_following_fy' THEN
      adjustment_deadline:=pg_catalog.make_date((pg_catalog.date_part('year',original.supplier_invoice_date)::integer+
        CASE WHEN pg_catalog.date_part('month',original.supplier_invoice_date)>=4 THEN 1 ELSE 0 END),11,30);
      SELECT least(adjustment_deadline,min(filing.filed_at::date)) INTO adjustment_deadline
        FROM tax.returns filing JOIN tax.return_periods period ON period.org_id=filing.org_id AND period.id=filing.return_period_id
       WHERE filing.org_id=organization_id AND period.registration_id=original_tax.registration_id
         AND filing.return_type='gstr9' AND filing.status='filed'
         AND period.period_start<=original.supplier_invoice_date AND period.period_end>=original.supplier_invoice_date;
    END IF;
    IF tax_required AND adjustment_deadline IS NOT NULL AND header.return_date>adjustment_deadline THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='statutory GST adjustment is after the effective-rule deadline'; END IF;
    IF tax_required THEN
      SELECT portal_line.* INTO STRICT supplier_portal_line
        FROM tax.portal_document_lines portal_line
        JOIN tax.portal_documents portal_document ON portal_document.org_id=portal_line.org_id
          AND portal_document.id=portal_line.portal_document_id AND portal_document.status='parsed'
          AND portal_document.portal_document_type IN ('gstr2a','gstr2b')
       WHERE portal_line.org_id=organization_id AND portal_line.id=header.supplier_credit_note_portal_line_id
         AND portal_line.document_type='credit_note' FOR SHARE OF portal_line,portal_document;
      IF supplier_portal_line.supplier_gstin IS DISTINCT FROM original_tax.counterparty_gstin
         OR supplier_portal_line.place_of_supply_state_code IS DISTINCT FROM original_tax.place_of_supply_state_code
         OR ROW(supplier_portal_line.taxable_amount,supplier_portal_line.cgst_amount,supplier_portal_line.sgst_amount,
                supplier_portal_line.igst_amount,supplier_portal_line.cess_amount,supplier_portal_line.total_amount)
            IS DISTINCT FROM ROW(header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,
                header.cess_total,header.gst_taxable_total+header.cgst_total+header.sgst_total+header.igst_total+header.cess_total) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier GST credit-note portal evidence differs from purchase return'; END IF;
    END IF;
    IF tax_required THEN
      SELECT count(*) INTO registration_scope_count
        FROM tax.registrations registration
        JOIN tax.registration_branches association
          ON association.org_id=registration.org_id
         AND association.registration_id=registration.id
       WHERE registration.org_id=organization_id
         AND registration.id=original_tax.registration_id
         AND registration.status='active'
         AND registration.effective_from<=header.return_date
         AND (registration.effective_to IS NULL OR registration.effective_to>=header.return_date)
         AND association.branch_id=header.branch_id
         AND association.status='active'
         AND association.effective_from<=header.return_date
         AND (association.effective_to IS NULL OR association.effective_to>=header.return_date);
      IF registration_scope_count<>1 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='statutory return requires exactly one active branch GST registration association on return date';
      END IF;
      PERFORM 1
        FROM tax.registrations registration
        JOIN tax.registration_branches association
          ON association.org_id=registration.org_id
         AND association.registration_id=registration.id
       WHERE registration.org_id=organization_id
         AND registration.id=original_tax.registration_id
         AND registration.status='active'
         AND registration.effective_from<=header.return_date
         AND (registration.effective_to IS NULL OR registration.effective_to>=header.return_date)
         AND association.branch_id=header.branch_id
         AND association.status='active'
         AND association.effective_from<=header.return_date
         AND (association.effective_to IS NULL OR association.effective_to>=header.return_date)
       FOR SHARE OF registration,association;
    END IF;
    SELECT account.party_id INTO STRICT party_id FROM parties.supplier_accounts account WHERE account.org_id=organization_id AND account.id=header.supplier_account_id AND account.status='active' FOR SHARE;
    SELECT * INTO STRICT artifact FROM calculation.artifacts WHERE org_id=organization_id AND id=artifact_id FOR UPDATE;
    input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb; output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
    IF artifact.purchase_return_id IS DISTINCT FROM resource_id OR artifact.operation<>'procurement.purchase_return.post' OR artifact.aggregate_version<>header.row_version THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed return artifact metadata mismatch'; END IF;
    PERFORM erp_commercial_commands.assert_purchase_return_artifact(organization_id,resource_id,input_doc,output_doc);
    inventory_required:=true; IF inventory_document_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='purchase return inventory issue is required'; END IF;
    IF tax_required<>(tax_document_id IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return tax-document identity does not match statutory GST treatment'; END IF;
    IF inventory_document_id IS NOT NULL THEN
      PERFORM erp_commercial_commands.post_owned_inventory_document(
        organization_id,inventory_document_id,actor_id,'purchase_return',resource_id,header.branch_id);
      SELECT coalesce(sum(CASE WHEN entry.entry_kind='issue' THEN -entry.value_delta ELSE entry.value_delta END),0),count(*)
        INTO inventory_value,inventory_entries FROM inventory.stock_ledger_entries entry
       WHERE entry.org_id=organization_id AND entry.inventory_document_id=inventory_document_id
         AND entry.entry_kind IN ('issue');
      IF inventory_entries=0 OR inventory_value<=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return inventory document has no authoritative posted ledger value'; END IF;
    END IF;
    consumed:=erp_calculation_authority.consume_artifact(organization_id,artifact_id,'procurement.purchase_return.post','purchase_return',resource_id,header.row_version,request_id,command_request_id,claim_id);
    IF pg_catalog.convert_from(consumed,'UTF8')::jsonb IS DISTINCT FROM output_doc THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed return calculation changed'; END IF;
    IF invoiced THEN
      SELECT open_item.* INTO STRICT original_open FROM finance.accounting_events event JOIN finance.open_items open_item ON open_item.org_id=event.org_id AND open_item.accounting_event_id=event.id WHERE event.org_id=organization_id AND event.supplier_invoice_id=header.supplier_invoice_id FOR UPDATE OF open_item;
      original_event_id:=original_open.accounting_event_id;
      SELECT original_open.principal_amount-coalesce(sum(allocation.amount) FILTER (WHERE allocation.status='posted'
        AND NOT EXISTS (SELECT 1 FROM finance.allocations reversal WHERE reversal.org_id=allocation.org_id
          AND reversal.reversal_of_allocation_id=allocation.id)),0)
        INTO outstanding FROM finance.allocations allocation
       WHERE allocation.org_id=organization_id AND allocation.open_item_id=original_open.id;
      IF outstanding<0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='original open item is overallocated'; END IF;
    ELSE outstanding:=0; END IF;
    INSERT INTO finance.adjustment_notes(org_id,id,note_number,note_date,side,direction,party_id,sales_invoice_id,supplier_invoice_id,sales_return_id,purchase_return_id,adjusts_open_item_id,counterparty_portal_document_line_id,gst_adjustment_rule_version_id,gst_tax_treatment,recipient_itc_reversal_evidence_attachment_id,recipient_itc_reversal_confirmed_at,zero_rated_payment_mode,tax_charge_mechanism,currency_code,document_effect,rounding_policy,document_discount_kind,document_discount_basis,document_discount_value,calculation_ruleset_version,gross_price_amount,discount_amount,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,igst_amount,cess_amount,recipient_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,reason_code,reason,status,approved_at,approved_by_membership_id,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,adjustment_note_id,adjustment_note_number,header.return_date,'purchase','debit',party_id,NULL,header.supplier_invoice_id,NULL,resource_id,CASE WHEN invoiced THEN original_open.id ELSE NULL END,header.supplier_credit_note_portal_line_id,header.gst_adjustment_rule_version_id,header.gst_tax_treatment,NULL,NULL,header.zero_rated_payment_mode,header.tax_charge_mechanism,coalesce(original.currency_code,'INR'),'decrease',header.rounding_policy,'none','price_value',0,header.calculation_ruleset_version,(output_doc#>>'{totals,subtotal}')::numeric,(output_doc#>>'{totals,discount_total}')::numeric,header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,header.recipient_assessed_tax_total,header.rounding_adjustment,header.grand_total,header.reason_code,'Posted return','approved',posted_time,actor_id,actor_id,actor_id);
    INSERT INTO finance.adjustment_note_lines(org_id,id,adjustment_note_id,line_number,line_kind,product_id,account_id,sales_invoice_line_id,supplier_invoice_line_id,charge_code,quoted_amount,description,uom_code,billed_quantity,free_quantity,uom_conversion_factor,base_billed_quantity,base_free_quantity,free_supply_tax_treatment,quoted_unit_rate,price_basis,gross_amount,line_discount_kind,line_discount_basis,line_discount_value,document_discount_eligible,line_discount_amount,line_taxable_discount_amount,document_discount_amount,document_taxable_discount_amount,final_residual,gst_tax_treatment,discount_amount,net_value_amount,gst_taxable_value,hsn_sac_code,tax_code_version_id,taxability_snapshot,inventory_cost_treatment,itc_eligibility,tax_charge_mechanism,cgst_rate,sgst_rate,igst_rate,cess_rate,cgst_amount,sgst_amount,igst_amount,cess_amount,recipient_assessed_tax_amount,line_total,tax_ruleset_version,created_by_membership_id)
    SELECT organization_id,gen_random_uuid(),adjustment_note_id,return_adjustment_line.line_number,'product',return_adjustment_line.product_id,NULL,NULL,invoice_source.id,NULL,NULL,'Return adjustment',CASE WHEN invoiced THEN invoice_source.uom_code ELSE source.uom_code END,return_adjustment_line.billed_quantity,return_adjustment_line.free_quantity,return_adjustment_line.uom_conversion_factor,return_adjustment_line.base_billed_quantity,return_adjustment_line.base_free_quantity,return_adjustment_line.free_supply_tax_treatment,return_adjustment_line.quoted_unit_rate,return_adjustment_line.price_basis,(calculated.item->>'gross_amount')::numeric,'none','price_value',0,false,(calculated.item->>'line_discount_amount')::numeric,(calculated.item->>'line_taxable_discount_amount')::numeric,(calculated.item->>'document_discount_amount')::numeric,(calculated.item->>'document_taxable_discount_amount')::numeric,return_adjustment_line.final_residual,header.gst_tax_treatment,(calculated.item->>'line_discount_amount')::numeric+(calculated.item->>'document_discount_amount')::numeric,return_adjustment_line.net_value_amount,return_adjustment_line.gst_taxable_value,return_adjustment_line.hsn_code_snapshot,return_adjustment_line.tax_code_version_id,return_adjustment_line.taxability_snapshot,invoice_source.inventory_cost_treatment,invoice_source.itc_eligibility,return_adjustment_line.tax_charge_mechanism,return_adjustment_line.cgst_rate,return_adjustment_line.sgst_rate,return_adjustment_line.igst_rate,return_adjustment_line.cess_rate,return_adjustment_line.cgst_amount,return_adjustment_line.sgst_amount,return_adjustment_line.igst_amount,return_adjustment_line.cess_amount,CASE WHEN return_adjustment_line.tax_charge_mechanism='reverse_charge' THEN return_adjustment_line.cgst_amount+return_adjustment_line.sgst_amount+return_adjustment_line.igst_amount+return_adjustment_line.cess_amount ELSE 0 END,return_adjustment_line.line_total,header.calculation_ruleset_version,actor_id
      FROM procurement.purchase_return_lines return_adjustment_line
      JOIN pg_catalog.jsonb_array_elements(output_doc->'lines') calculated(item) ON calculated.item->>'line_id'=coalesce((SELECT allocation.supplier_invoice_line_id::text FROM procurement.supplier_invoice_receipt_allocations allocation WHERE allocation.org_id=return_adjustment_line.org_id AND allocation.id=return_adjustment_line.supplier_invoice_receipt_allocation_id),return_adjustment_line.goods_receipt_line_id::text)
      JOIN procurement.goods_receipt_lines source ON source.org_id=return_adjustment_line.org_id AND source.id=return_adjustment_line.goods_receipt_line_id
      LEFT JOIN procurement.supplier_invoice_receipt_allocations invoice_allocation ON invoice_allocation.org_id=return_adjustment_line.org_id AND invoice_allocation.id=return_adjustment_line.supplier_invoice_receipt_allocation_id LEFT JOIN procurement.supplier_invoice_lines invoice_source ON invoice_source.org_id=invoice_allocation.org_id AND invoice_source.id=invoice_allocation.supplier_invoice_line_id
     WHERE return_adjustment_line.org_id=organization_id AND return_adjustment_line.purchase_return_id=resource_id;
    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,transaction_currency,functional_currency,fx_rate,transaction_debit_total,transaction_credit_total,functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,header.return_date,'purchase_return',coalesce(original.currency_code,'INR'),'INR',1,header.grand_total,header.grand_total,header.grand_total,header.grand_total,'draft',actor_id,actor_id);
    IF invoiced THEN
      party_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'accounts_payable','liability',original.currency_code,true);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,party_account,header.branch_id,party_id,'Payable debit',header.grand_total,0,actor_id); line_no:=line_no+1;
      FOR posting_line IN SELECT return_line.net_value_amount,return_line.cgst_amount,return_line.sgst_amount,return_line.igst_amount,return_line.cess_amount,invoice_line.net_value_account_id,invoice_line.itc_eligibility,invoice_line.inventory_cost_treatment FROM procurement.purchase_return_lines return_line JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=return_line.org_id AND allocation.id=return_line.supplier_invoice_receipt_allocation_id JOIN procurement.supplier_invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.supplier_invoice_line_id WHERE return_line.org_id=organization_id AND return_line.purchase_return_id=resource_id ORDER BY return_line.line_number LOOP
        PERFORM erp_commercial_commands.assert_line_account(organization_id,posting_line.net_value_account_id,CASE WHEN posting_line.inventory_cost_treatment='capitalize' THEN 'asset' ELSE 'expense' END,original.currency_code);
        component_amount:=posting_line.net_value_amount+CASE WHEN posting_line.itc_eligibility='eligible' THEN 0 ELSE posting_line.cgst_amount+posting_line.sgst_amount+posting_line.igst_amount+posting_line.cess_amount END;
        IF posting_line.itc_eligibility='eligible' THEN eligible_cgst:=eligible_cgst+posting_line.cgst_amount; eligible_sgst:=eligible_sgst+posting_line.sgst_amount; eligible_igst:=eligible_igst+posting_line.igst_amount; eligible_cess:=eligible_cess+posting_line.cess_amount; END IF;
        IF posting_line.inventory_cost_treatment='capitalize' THEN
          role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'inventory_asset','asset',original.currency_code,false);
          IF posting_line.net_value_account_id<>role_account THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='capitalized supplier line is not mapped to inventory asset role'; END IF;
          expected_inventory_value:=expected_inventory_value+component_amount;
        ELSE
          PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,posting_line.net_value_account_id,header.branch_id,NULL,'Supplier expense reversal',0,component_amount,actor_id); line_no:=line_no+1;
        END IF;
      END LOOP;
      IF expected_inventory_value>0 THEN
        role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'inventory_asset','asset',original.currency_code,false);
        PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Returned inventory at posted MWA ledger value',0,inventory_value,actor_id); line_no:=line_no+1;
        variance_value:=expected_inventory_value-inventory_value;
        IF variance_value<>0 THEN role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'purchase_return_inventory_variance','expense',original.currency_code,false);
          PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Purchase return inventory variance',CASE WHEN variance_value<0 THEN abs(variance_value) ELSE 0 END,CASE WHEN variance_value>0 THEN variance_value ELSE 0 END,actor_id); line_no:=line_no+1;
        END IF;
      ELSIF inventory_value<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='expensed supplier return cannot silently move valued inventory'; END IF;
    ELSE
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'goods_received_not_invoiced','liability','INR',false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,party_id,'Uninvoiced receipt liability reversal',header.grand_total,0,actor_id); line_no:=line_no+1;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'inventory_asset','asset','INR',false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Inventory returned at posted MWA ledger value',0,inventory_value,actor_id); line_no:=line_no+1;
      variance_value:=header.grand_total-inventory_value;
      IF variance_value<>0 THEN role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'purchase_return_inventory_variance','expense','INR',false);
        PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Uninvoiced purchase return inventory variance',CASE WHEN variance_value<0 THEN abs(variance_value) ELSE 0 END,CASE WHEN variance_value>0 THEN variance_value ELSE 0 END,actor_id); line_no:=line_no+1;
      END IF;
    END IF;
    FOR role_key,component_amount IN SELECT * FROM (VALUES ('input_cgst'::varchar,eligible_cgst),('input_sgst'::varchar,eligible_sgst),('input_igst'::varchar,eligible_igst),('input_cess'::varchar,eligible_cess)) x(role_key,amount) LOOP
      IF invoiced AND component_amount>0 THEN
        role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,'asset',coalesce(original.currency_code,'INR'),false);
        PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Tax reversal',0,component_amount,actor_id); line_no:=line_no+1;
      END IF;
    END LOOP;
    IF invoiced AND header.tax_charge_mechanism='reverse_charge' THEN
      FOR role_key,component_amount IN SELECT * FROM (VALUES ('rcm_cgst_payable'::varchar,header.cgst_total),('rcm_sgst_payable'::varchar,header.sgst_total),('rcm_igst_payable'::varchar,header.igst_total),('rcm_cess_payable'::varchar,header.cess_total)) component(role_key,amount) LOOP
        IF component_amount>0 THEN role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,'liability',original.currency_code,false);
          PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Reverse-charge liability reversal',component_amount,0,actor_id); line_no:=line_no+1;
        END IF;
      END LOOP;
    END IF;
    IF invoiced AND header.rounding_adjustment<>0 THEN
      role_key:=CASE WHEN header.rounding_adjustment>0 THEN 'rounding_loss' ELSE 'rounding_gain' END;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,CASE WHEN role_key='rounding_gain' THEN 'income' ELSE 'expense' END,original.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Rounding reversal',
        CASE WHEN header.rounding_adjustment<0 THEN abs(header.rounding_adjustment) ELSE 0 END,
        CASE WHEN header.rounding_adjustment>0 THEN abs(header.rounding_adjustment) ELSE 0 END,actor_id); line_no:=line_no+1;
    END IF;
    SELECT coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0) INTO debit_total,credit_total FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=journal_id;
    IF debit_total<>credit_total OR debit_total=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return journal is not balanced'; END IF;
    UPDATE finance.journal_entries SET transaction_debit_total=debit_total,transaction_credit_total=credit_total,functional_debit_total=debit_total,functional_credit_total=credit_total,status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=journal_id;
    UPDATE procurement.purchase_returns SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=resource_id AND status='approved';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='return posting state changed'; END IF;
    UPDATE finance.adjustment_notes SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=adjustment_note_id;

    IF tax_required THEN
      INSERT INTO tax.documents(org_id,id,registration_id,adjustment_note_id,document_class,document_number,document_date,direction,
        counterparty_party_id,counterparty_gstin,place_of_supply_state_code,supply_type,zero_rated_payment_mode,tax_charge_mechanism,
        tax_liability_party,document_effect,adjusts_tax_document_id,currency_code,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,
        igst_amount,cess_amount,self_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,tax_ruleset_version,tax_ruleset_effective_date,
        source_hash,posted_at,created_by_membership_id)
      VALUES(organization_id,tax_document_id,original_tax.registration_id,adjustment_note_id,'adjustment_note',supplier_portal_line.invoice_number,supplier_portal_line.invoice_date,
        original_tax.direction,party_id,original_tax.counterparty_gstin,original_tax.place_of_supply_state_code,original_tax.supply_type,
        header.zero_rated_payment_mode,header.tax_charge_mechanism,original_tax.tax_liability_party,'decrease',original_tax.id,original_tax.currency_code,
        header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,
        CASE WHEN original_tax.direction='inward' AND header.tax_charge_mechanism='reverse_charge' THEN header.recipient_assessed_tax_total ELSE 0 END,
        header.rounding_adjustment,header.grand_total,header.calculation_ruleset_version,original_tax.tax_ruleset_effective_date,
        extensions.digest(pg_catalog.convert_to((output_doc||pg_catalog.jsonb_build_object('return_id',resource_id))::text,'UTF8'),'sha256'),posted_time,actor_id);
    ELSIF tax_document_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial-only return cannot create tax document'; END IF;
    INSERT INTO finance.accounting_events(org_id,id,event_type,adjustment_note_id,journal_entry_id,occurred_at,source_posted_at,created_by_membership_id) VALUES(organization_id,event_id,'adjustment_note',adjustment_note_id,journal_id,posted_time,posted_time,actor_id);
    IF invoiced THEN
      applied:=least(header.grand_total,outstanding); residual:=header.grand_total-applied;
      IF applied>0 THEN INSERT INTO finance.allocations(org_id,id,adjustment_note_id,open_item_id,allocation_date,currency_code,amount,functional_amount,status,created_by_membership_id) VALUES(organization_id,allocation_id,adjustment_note_id,original_open.id,header.return_date,original_open.currency_code,applied,applied,'posted',actor_id); END IF;
      IF applied=outstanding AND outstanding>0 THEN UPDATE finance.open_items SET status='settled',settled_at=posted_time WHERE org_id=organization_id AND id=original_open.id; END IF;
      IF residual>0 THEN INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,currency_code,principal_amount,functional_principal_amount,status,created_by_membership_id) VALUES(organization_id,residual_open_item_id,event_id,party_id,'receivable',adjustment_note_number,header.return_date,header.return_date,original_open.currency_code,residual,residual,'open',actor_id); END IF;
    END IF;
    PERFORM erp_trade_commands.finish_claim(organization_id,claim_id,'procurement.purchase_returns',resource_id);
    RETURN resource_id;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."post_purchase_return"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,varchar,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."post_purchase_return"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,varchar,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_commercial_commands"."post_purchase_return"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,varchar,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."guard_purchase_return_state"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
    IF TG_OP='DELETE' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return evidence is retained';
    END IF;
    IF TG_OP='INSERT' THEN
      IF NEW.status<>'draft' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='new return must start in draft'; END IF;
      RETURN NEW;
    END IF;
    IF OLD.status='posted' AND NEW.status='reversed' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return reversal requires a reviewed compensating command for tax, finance, allocation, and inventory effects';
    END IF;
    IF OLD.status IN ('posted','reversed','cancelled') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted or terminal return evidence is immutable';
    END IF;
    IF OLD.status<>NEW.status AND NOT ((OLD.status='draft' AND NEW.status IN ('submitted','cancelled')) OR (OLD.status='submitted' AND NEW.status IN ('approved','cancelled')) OR (OLD.status='approved' AND NEW.status IN ('posted','cancelled'))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invalid return lifecycle transition';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_purchase_return_state"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_purchase_return_state"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "guard_purchase_return_state_tr" BEFORE INSERT OR UPDATE OR DELETE ON "procurement"."purchase_returns" FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_purchase_return_state"();
CREATE FUNCTION "erp_commercial_commands"."guard_purchase_return_companions"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE artifact calculation.artifacts%ROWTYPE; note finance.adjustment_notes%ROWTYPE;
        companion_count bigint; event_id uuid; input_doc jsonb; output_doc jsonb; expected_tax bigint;
BEGIN
    IF TG_OP='DELETE' THEN
      IF OLD.status IN ('posted','reversed') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted return is retained'; END IF;
      RETURN OLD;
    END IF;
    IF NEW.status='posted' THEN
      SELECT count(*),(pg_catalog.array_agg(id))[1] INTO companion_count,artifact.id FROM calculation.artifacts
       WHERE org_id=NEW.org_id AND purchase_return_id=NEW.id AND operation='procurement.purchase_return.post' AND status='consumed';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted return requires exactly one consumed typed calculation artifact'; END IF;
      SELECT * INTO STRICT artifact FROM calculation.artifacts stored WHERE stored.org_id=NEW.org_id AND stored.id=artifact.id;
      input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb; output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
      PERFORM erp_commercial_commands.assert_purchase_return_artifact(NEW.org_id,NEW.id,input_doc,output_doc);
      SELECT count(*),(pg_catalog.array_agg(id))[1] INTO companion_count,note.id FROM finance.adjustment_notes
       WHERE org_id=NEW.org_id AND purchase_return_id=NEW.id AND status='posted';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted return requires exactly one typed posted adjustment note'; END IF;
      SELECT * INTO STRICT note FROM finance.adjustment_notes stored WHERE stored.org_id=NEW.org_id AND stored.id=note.id;
      IF ROW(note.net_value_amount,note.gst_taxable_value,note.cgst_amount,note.sgst_amount,note.igst_amount,note.cess_amount,
             note.recipient_assessed_tax_amount,note.rounding_adjustment,note.counterparty_payable_amount)
         IS DISTINCT FROM ROW(NEW.net_value_total,NEW.gst_taxable_total,NEW.cgst_total,NEW.sgst_total,NEW.igst_total,NEW.cess_total,
             NEW.recipient_assessed_tax_total,NEW.rounding_adjustment,NEW.grand_total) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return adjustment note totals differ'; END IF;
      IF ROW(note.gst_adjustment_rule_version_id,note.gst_tax_treatment,note.recipient_itc_reversal_evidence_attachment_id,
             note.recipient_itc_reversal_confirmed_at)
         IS DISTINCT FROM ROW(NEW.gst_adjustment_rule_version_id,NEW.gst_tax_treatment,
             NULL::uuid,NULL::timestamptz) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return adjustment note GST rule or evidence differs'; END IF;
      IF note.counterparty_portal_document_line_id IS DISTINCT FROM NEW.supplier_credit_note_portal_line_id THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return adjustment note portal lineage differs'; END IF;
      SELECT count(*) INTO companion_count FROM inventory.inventory_documents document
       WHERE document.org_id=NEW.org_id AND document.purchase_return_id=NEW.id
         AND document.document_type='purchase_return_issue' AND document.status='posted';
      IF companion_count<>(1) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return inventory-document ownership differs'; END IF;
      expected_tax:=CASE WHEN NEW.gst_tax_treatment='statutory' THEN 1 ELSE 0 END;
      SELECT count(*) INTO companion_count FROM tax.documents WHERE org_id=NEW.org_id AND adjustment_note_id=note.id AND document_class='adjustment_note';
      IF companion_count<>expected_tax THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return adjustment tax-document ownership differs'; END IF;
      SELECT count(*),(pg_catalog.array_agg(event.id))[1] INTO companion_count,event_id FROM finance.accounting_events event
       JOIN finance.journal_entries journal ON journal.org_id=event.org_id AND journal.id=event.journal_entry_id AND journal.status='posted'
       WHERE event.org_id=NEW.org_id AND event.adjustment_note_id=note.id AND event.event_type='adjustment_note';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return requires exactly one posted adjustment accounting event'; END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_purchase_return_companions"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_purchase_return_companions"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "guard_purchase_return_companions_ct" AFTER INSERT OR UPDATE OR DELETE ON "procurement"."purchase_returns" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_purchase_return_companions"();
-- Reviewed enforcement: procurement.supplier_invoice_lines:procurement_supplier_invoice_lines_invariant_1
CREATE FUNCTION "erp_commercial_commands"."guard_posted_supplier_invoice_lines"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_id uuid; parent_status text;
BEGIN
    parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.supplier_invoice_id ELSE NEW.supplier_invoice_id END;
    SELECT status INTO STRICT parent_status FROM procurement.supplier_invoices
     WHERE org_id=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
       AND id=parent_id FOR SHARE;
    IF parent_status IN ('posted','reversed') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved commercial lines are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_posted_supplier_invoice_lines"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_posted_supplier_invoice_lines"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "guard_posted_supplier_invoice_lines" BEFORE INSERT OR UPDATE OR DELETE ON "procurement"."supplier_invoice_lines" FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_posted_supplier_invoice_lines"();
-- Reviewed enforcement: procurement.supplier_invoice_receipt_allocations:procurement_supplier_invoice_receipt_allocations_invariant_1
CREATE FUNCTION "erp_trade_invariants"."guard_supplier_receipt_allocation"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    invoice_line procurement.supplier_invoice_lines%ROWTYPE;
    receipt_line procurement.goods_receipt_lines%ROWTYPE;
    invoice_status text;
    invoice_billed numeric(20,6);
    invoice_free numeric(20,6);
    receipt_billed numeric(20,6);
    receipt_free numeric(20,6);
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT invoice.status INTO invoice_status FROM procurement.supplier_invoice_lines line
        JOIN procurement.supplier_invoices invoice ON invoice.org_id=line.org_id AND invoice.id=line.supplier_invoice_id
        WHERE line.org_id=OLD.org_id AND line.id=OLD.supplier_invoice_line_id FOR SHARE OF invoice;
        IF invoice_status IN ('posted','reversed') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted supplier invoice allocation is immutable';
        END IF;
        RETURN OLD;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':supplier_invoice:' || NEW.supplier_invoice_line_id::text, 630195401));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':receipt:' || NEW.goods_receipt_line_id::text, 630195401));
    SELECT line.* INTO invoice_line FROM procurement.supplier_invoice_lines line
    JOIN procurement.supplier_invoices invoice ON invoice.org_id=line.org_id AND invoice.id=line.supplier_invoice_id
    WHERE line.org_id=NEW.org_id AND line.id=NEW.supplier_invoice_line_id FOR SHARE OF line, invoice;
    SELECT invoice.status INTO invoice_status FROM procurement.supplier_invoices invoice
    WHERE invoice.org_id=NEW.org_id AND invoice.id=invoice_line.supplier_invoice_id;
    SELECT * INTO receipt_line FROM procurement.goods_receipt_lines WHERE org_id=NEW.org_id AND id=NEW.goods_receipt_line_id FOR SHARE;
    IF invoice_status IN ('posted','reversed')
       AND (TG_OP = 'INSERT' OR NEW IS DISTINCT FROM OLD) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted supplier invoice allocation is immutable';
    END IF;
    IF invoice_line.id IS NULL OR receipt_line.id IS NULL
       OR invoice_line.line_kind <> 'product'
       OR invoice_line.product_id IS DISTINCT FROM receipt_line.product_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'supplier invoice allocation product mismatch';
    END IF;
    SELECT COALESCE(sum(allocated_base_billed_quantity),0), COALESCE(sum(allocated_base_free_quantity),0)
      INTO invoice_billed, invoice_free FROM procurement.supplier_invoice_receipt_allocations
     WHERE org_id=NEW.org_id AND supplier_invoice_line_id=NEW.supplier_invoice_line_id;
    SELECT COALESCE(sum(allocated_base_billed_quantity),0), COALESCE(sum(allocated_base_free_quantity),0)
      INTO receipt_billed, receipt_free FROM procurement.supplier_invoice_receipt_allocations
     WHERE org_id=NEW.org_id AND goods_receipt_line_id=NEW.goods_receipt_line_id;
    IF invoice_billed > invoice_line.base_billed_quantity OR invoice_free > invoice_line.base_free_quantity
       OR receipt_billed > receipt_line.base_accepted_quantity OR receipt_free > receipt_line.base_free_quantity THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'cumulative supplier-invoice/receipt allocation exceeds either source line';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_supplier_receipt_allocation"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_supplier_receipt_allocation"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "supplier_receipt_allocations_cap_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "procurement"."supplier_invoice_receipt_allocations" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_supplier_receipt_allocation"();
-- Reviewed enforcement: procurement.supplier_invoices:procurement_supplier_invoices_invariant_1
CREATE FUNCTION "erp_commercial_commands"."assert_supplier_invoice_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header procurement.supplier_invoices%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM procurement.supplier_invoices
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status NOT IN ('approved','posted') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated invoice is not in its postable or posted state';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'procurement.supplier_invoice.post'
       OR p_input->>'resource_type'<>'supplier_invoice'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'operation'<>'procurement.supplier_invoice.post'
       OR p_output->>'resource_type'<>'supplier_invoice'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted invoice';
    END IF;

    SELECT count(*) INTO expected_lines FROM procurement.supplier_invoice_lines
     WHERE org_id=p_org_id AND supplier_invoice_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM procurement.supplier_invoice_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.supplier_invoice_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR tax_version.ruleset_version IS DISTINCT FROM header.calculation_ruleset_version
         OR header.supplier_invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.supplier_invoice_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."assert_supplier_invoice_artifact"(uuid,uuid,jsonb,jsonb) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."assert_supplier_invoice_artifact"(uuid,uuid,jsonb,jsonb) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."post_supplier_invoice"(organization_id uuid, resource_id uuid, artifact_id uuid, actor_id uuid, request_id uuid, command_request_id uuid, tax_document_id uuid, journal_id uuid, journal_number varchar, event_id uuid, open_item_id uuid, inventory_document_id uuid, inventory_key_hash bytea, inventory_request_hash bytea, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header procurement.supplier_invoices%ROWTYPE; artifact calculation.artifacts%ROWTYPE; line record;
        claim_id uuid; replay_id uuid; input_doc jsonb; output_doc jsonb; consumed bytea;
        party_id uuid; party_account uuid; party_default_account uuid; posted_time timestamptz:=pg_catalog.transaction_timestamp();
        line_no integer:=2; component_amount numeric(20,2); role_account uuid; role_key varchar;
        total_debit numeric(20,2); total_credit numeric(20,2); tax_effective date; source_hash bytea; noncreditable_tax numeric(20,2);
        eligible_cgst numeric(20,2):=0; eligible_sgst numeric(20,2):=0; eligible_igst numeric(20,2):=0; eligible_cess numeric(20,2):=0;
        inventory_value numeric(20,2):=0; inventory_entries bigint:=0; product_lines boolean:=false; allocated_lines boolean:=false;
        line_snapshot jsonb; registration_scope_count bigint;
BEGIN
    PERFORM erp_trade_commands.assert_context(organization_id,actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM request_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='commercial request context mismatch'; END IF;
    SELECT * INTO STRICT header FROM procurement.supplier_invoices WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('procurement.invoice.post',header.branch_id);
    IF NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='finance journal permission denied'; END IF;
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      organization_id,actor_id,'procurement.supplier_invoice.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN IF replay_id<>resource_id THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='commercial replay mismatch'; END IF; RETURN replay_id; END IF;
    SELECT * INTO STRICT artifact FROM calculation.artifacts WHERE org_id=organization_id AND id=artifact_id FOR UPDATE;
    input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
    output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
    IF artifact.supplier_invoice_id IS DISTINCT FROM resource_id OR artifact.engine_version IS DISTINCT FROM output_doc->>'engine_version'
       OR artifact.ruleset_version IS DISTINCT FROM output_doc->>'ruleset_version' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed calculation artifact metadata mismatch'; END IF;
    PERFORM "erp_commercial_commands".assert_supplier_invoice_artifact(organization_id,resource_id,input_doc,output_doc);

    SELECT account.party_id,account.default_payable_account_id INTO party_id,party_default_account
      FROM parties.supplier_accounts account WHERE account.org_id=organization_id AND account.id=header.supplier_account_id AND account.status='active' FOR SHARE;
    IF party_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial party account is inactive'; END IF;
    party_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,'accounts_payable','liability',header.currency_code,true);
    IF party_default_account IS DISTINCT FROM party_account THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='party default ledger differs from active branch account-role mapping'; END IF;
    PERFORM 1 FROM tax.registrations registration WHERE registration.org_id=organization_id AND registration.id=header.buyer_tax_registration_id
      AND registration.status='active' AND registration.effective_from<=header.supplier_invoice_date
      AND (registration.effective_to IS NULL OR registration.effective_to>=header.supplier_invoice_date) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax registration is not active on document date'; END IF;
    SELECT count(*) INTO registration_scope_count FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.buyer_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.supplier_invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.supplier_invoice_date);
    IF registration_scope_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document requires exactly one effective branch registration association'; END IF;
    PERFORM 1 FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.buyer_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.supplier_invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.supplier_invoice_date) FOR SHARE;
    SELECT min(version.effective_from) INTO tax_effective FROM procurement.supplier_invoice_lines tax_line JOIN tax.tax_code_versions version ON version.id=tax_line.tax_code_version_id
      WHERE tax_line.org_id=organization_id AND tax_line.supplier_invoice_id=resource_id AND version.status='active'
        AND version.effective_from<=header.supplier_invoice_date AND (version.effective_to IS NULL OR version.effective_to>=header.supplier_invoice_date)
      HAVING count(DISTINCT version.ruleset_version)=1 AND min(version.ruleset_version)=header.calculation_ruleset_version
        AND count(*)=(SELECT count(*) FROM procurement.supplier_invoice_lines expected WHERE expected.org_id=organization_id AND expected.supplier_invoice_id=resource_id);
    IF tax_effective IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice tax ruleset is not uniform'; END IF;

    NULL;
    consumed:=erp_calculation_authority.consume_artifact(organization_id,artifact_id,'procurement.supplier_invoice.post','supplier_invoice',resource_id,
      header.row_version,request_id,command_request_id,claim_id);
    IF pg_catalog.convert_from(consumed,'UTF8')::jsonb IS DISTINCT FROM output_doc THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed calculation changed'; END IF;

    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,transaction_currency,functional_currency,fx_rate,
      transaction_debit_total,transaction_credit_total,functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,header.supplier_invoice_date,'supplier_invoice',header.currency_code,'INR',1,
      header.grand_total,header.grand_total,header.grand_total,header.grand_total,'draft',actor_id,actor_id);
    PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,1,party_account,header.branch_id,party_id,
      'Supplier payable',0,header.grand_total,actor_id);
    FOR line IN SELECT * FROM procurement.supplier_invoice_lines WHERE org_id=organization_id AND supplier_invoice_id=resource_id ORDER BY line_number,id LOOP
        PERFORM "erp_commercial_commands".assert_line_account(organization_id,line.net_value_account_id,CASE WHEN line.inventory_cost_treatment='capitalize' THEN 'asset' ELSE 'expense' END,header.currency_code);
        noncreditable_tax:=CASE WHEN line.itc_eligibility='eligible' THEN 0 ELSE line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount END;
        IF line.itc_eligibility='eligible' THEN
          eligible_cgst:=eligible_cgst+line.cgst_amount; eligible_sgst:=eligible_sgst+line.sgst_amount;
          eligible_igst:=eligible_igst+line.igst_amount; eligible_cess:=eligible_cess+line.cess_amount;
        END IF;
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,line.net_value_account_id,header.branch_id,NULL,
          'Supplier invoice net value and noncreditable tax',line.net_value_amount+noncreditable_tax,0,actor_id); line_no:=line_no+1;
    END LOOP;
    NULL;
    FOR role_key,component_amount IN SELECT * FROM (VALUES
      ('input_cgst'::varchar,eligible_cgst),
      ('input_sgst'::varchar,eligible_sgst),
      ('input_igst'::varchar,eligible_igst),
      ('input_cess'::varchar,eligible_cess)) AS component(role_key,amount)
    LOOP
      IF component_amount>0 AND component_amount>0 THEN
        role_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,role_key,'asset',header.currency_code,false);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Eligible input tax',component_amount,0,actor_id); line_no:=line_no+1;
      END IF;
    END LOOP;

    IF header.tax_charge_mechanism='reverse_charge' THEN
      FOR role_key,component_amount IN SELECT * FROM (VALUES
        ('rcm_cgst_payable'::varchar,header.cgst_total),('rcm_sgst_payable'::varchar,header.sgst_total),
        ('rcm_igst_payable'::varchar,header.igst_total),('rcm_cess_payable'::varchar,header.cess_total)) AS component(role_key,amount)
      LOOP
        IF component_amount>0 THEN role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,'liability',header.currency_code,false);
          PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Self-assessed reverse-charge liability',0,component_amount,actor_id); line_no:=line_no+1;
        END IF;
      END LOOP;
    END IF;

    IF header.rounding_adjustment<>0 THEN
      role_key:=CASE WHEN header.rounding_adjustment>0 THEN 'rounding_loss' ELSE 'rounding_gain' END;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,CASE WHEN role_key='rounding_gain' THEN 'income' ELSE 'expense' END,header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Signed rounding adjustment',
        CASE WHEN header.rounding_adjustment>0 THEN abs(header.rounding_adjustment) ELSE 0 END,
        CASE WHEN header.rounding_adjustment<0 THEN abs(header.rounding_adjustment) ELSE 0 END,actor_id); line_no:=line_no+1;
    END IF;
    SELECT coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0) INTO total_debit,total_credit
      FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=journal_id;
    IF total_debit<>total_credit OR total_debit=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial journal does not exactly balance'; END IF;
    UPDATE finance.journal_entries SET transaction_debit_total=total_debit,transaction_credit_total=total_credit,
      functional_debit_total=total_debit,functional_credit_total=total_credit,status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=journal_id;
    UPDATE procurement.supplier_invoices SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=resource_id AND status='approved';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='invoice posting state changed'; END IF;
    IF inventory_document_id IS NOT NULL THEN
          PERFORM erp_trade_commands_v2.post_landed_cost_adjustment(organization_id,inventory_document_id,actor_id,inventory_key_hash,inventory_request_hash,expires_at);
        END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source_line) ORDER BY source_line.line_number,source_line.id) INTO line_snapshot
      FROM procurement.supplier_invoice_lines source_line WHERE source_line.org_id=organization_id AND source_line.supplier_invoice_id=resource_id;
    source_hash:=extensions.digest(pg_catalog.convert_to((pg_catalog.to_jsonb(header)||pg_catalog.jsonb_build_object('lines',line_snapshot,'artifact',pg_catalog.encode(artifact.output_sha256,'hex')))::text,'UTF8'),'sha256');
    INSERT INTO tax.documents(org_id,id,registration_id,supplier_invoice_id,document_class,document_number,document_date,direction,
      counterparty_party_id,counterparty_gstin,place_of_supply_state_code,supply_type,zero_rated_payment_mode,tax_charge_mechanism,
      tax_liability_party,document_effect,currency_code,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,igst_amount,cess_amount,
      self_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,tax_ruleset_version,tax_ruleset_effective_date,source_hash,posted_at,created_by_membership_id)
    VALUES(organization_id,tax_document_id,header.buyer_tax_registration_id,resource_id,'supplier_invoice',header.supplier_invoice_number,header.supplier_invoice_date,'inward',
      party_id,header.supplier_gstin_snapshot,header.place_of_supply_state_code,header.supply_type,header.zero_rated_payment_mode,header.tax_charge_mechanism,
      CASE WHEN header.tax_charge_mechanism='normal' THEN 'supplier' ELSE 'recipient' END,'original',header.currency_code,
      header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,
      CASE WHEN 'inward'='inward' AND header.tax_charge_mechanism='reverse_charge' THEN header.recipient_assessed_tax_total ELSE 0 END,
      header.rounding_adjustment,header.grand_total,header.calculation_ruleset_version,tax_effective,source_hash,posted_time,actor_id);
    INSERT INTO finance.accounting_events(org_id,id,event_type,supplier_invoice_id,journal_entry_id,occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,event_id,'supplier_invoice',resource_id,journal_id,posted_time,posted_time,actor_id);
    INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,currency_code,
      principal_amount,functional_principal_amount,status,created_by_membership_id)
    VALUES(organization_id,open_item_id,event_id,party_id,'payable',header.supplier_invoice_number,header.supplier_invoice_date,
      header.due_date,header.currency_code,header.grand_total,header.grand_total,'open',actor_id);
    PERFORM erp_trade_commands.finish_claim(organization_id,claim_id,'procurement.supplier_invoices',resource_id);
    RETURN resource_id;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."post_supplier_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."post_supplier_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_commercial_commands"."post_supplier_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."guard_supplier_invoice_companions"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE artifact calculation.artifacts%ROWTYPE; companion_count bigint; event_id uuid;
        input_doc jsonb; output_doc jsonb;
BEGIN
    IF TG_OP='DELETE' THEN
      IF OLD.status IN ('posted','reversed') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice is retained'; END IF;
      RETURN OLD;
    END IF;
    IF NEW.status='posted' THEN
      SELECT count(*),(pg_catalog.array_agg(id))[1] INTO companion_count,artifact.id FROM calculation.artifacts
       WHERE org_id=NEW.org_id AND supplier_invoice_id=NEW.id AND operation='procurement.supplier_invoice.post' AND status='consumed';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one consumed typed calculation artifact'; END IF;
      SELECT * INTO STRICT artifact FROM calculation.artifacts stored WHERE stored.org_id=NEW.org_id AND stored.id=artifact.id;
      input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
      output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
      PERFORM erp_commercial_commands.assert_supplier_invoice_artifact(NEW.org_id,NEW.id,input_doc,output_doc);
      SELECT count(*) INTO companion_count FROM tax.documents WHERE org_id=NEW.org_id AND supplier_invoice_id=NEW.id AND document_class='supplier_invoice';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one typed tax document'; END IF;
      SELECT count(*),(pg_catalog.array_agg(event.id))[1] INTO companion_count,event_id FROM finance.accounting_events event
       JOIN finance.journal_entries journal ON journal.org_id=event.org_id AND journal.id=event.journal_entry_id AND journal.status='posted'
       WHERE event.org_id=NEW.org_id AND event.supplier_invoice_id=NEW.id AND event.event_type='supplier_invoice';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one posted accounting event'; END IF;
      SELECT count(*) INTO companion_count FROM finance.open_items WHERE org_id=NEW.org_id AND accounting_event_id=event_id;
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one open item'; END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_supplier_invoice_companions"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_supplier_invoice_companions"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "guard_supplier_invoice_companions_ct" AFTER INSERT OR UPDATE OR DELETE ON "procurement"."supplier_invoices" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_supplier_invoice_companions"();
-- Reviewed enforcement: sales.dispatch_lines:sales_dispatch_lines_invariant_1
CREATE FUNCTION "erp_trade_invariants"."guard_dispatch_line"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    source sales.order_lines%ROWTYPE;
    dispatch sales.dispatches%ROWTYPE;
    batch_product uuid;
    location_branch uuid;
    billed_total numeric(20,6);
    free_total numeric(20,6);
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT * INTO dispatch FROM sales.dispatches WHERE org_id=OLD.org_id AND id=OLD.dispatch_id FOR SHARE;
        IF dispatch.status IN ('posted','reversed') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted dispatch line is immutable';
        END IF;
        RETURN OLD;
    END IF;
    SELECT * INTO dispatch FROM sales.dispatches WHERE org_id=NEW.org_id AND id=NEW.dispatch_id FOR SHARE;
    IF dispatch.status IN ('posted','reversed')
       AND (TG_OP = 'INSERT' OR NEW IS DISTINCT FROM OLD) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted dispatch line is immutable';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':' || NEW.order_line_id::text, 193701063));
    SELECT * INTO source FROM sales.order_lines WHERE org_id=NEW.org_id AND id=NEW.order_line_id FOR SHARE;
    SELECT product_id INTO batch_product FROM inventory.batches WHERE org_id=NEW.org_id AND id=NEW.batch_id FOR SHARE;
    SELECT branch_id INTO location_branch FROM inventory.locations WHERE org_id=NEW.org_id AND id=NEW.from_location_id FOR SHARE;
    IF source.id IS NULL OR source.line_kind <> 'product'
       OR source.product_id IS DISTINCT FROM NEW.product_id
       OR batch_product IS DISTINCT FROM NEW.product_id
       OR location_branch IS DISTINCT FROM dispatch.branch_id
       OR source.uom_code IS DISTINCT FROM NEW.uom_code
       OR NEW.base_billed_quantity IS DISTINCT FROM round(NEW.billed_quantity * source.uom_conversion_factor, 6)
       OR NEW.base_free_quantity IS DISTINCT FROM round(NEW.free_quantity * source.uom_conversion_factor, 6) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'dispatch line does not match approved product, lot, branch, or UOM facts';
    END IF;
    SELECT COALESCE(sum(line.base_billed_quantity),0), COALESCE(sum(line.base_free_quantity),0)
      INTO billed_total, free_total
      FROM sales.dispatch_lines AS line
      JOIN sales.dispatches AS parent ON parent.org_id=line.org_id AND parent.id=line.dispatch_id
     WHERE line.org_id=NEW.org_id AND line.order_line_id=NEW.order_line_id AND parent.status<>'cancelled';
    IF billed_total > source.base_billed_quantity OR free_total > source.base_free_quantity THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'cumulative dispatch exceeds approved billed or free quantity';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_dispatch_line"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_dispatch_line"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "dispatch_lines_source_cap_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "sales"."dispatch_lines" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_dispatch_line"();
-- Reviewed enforcement: sales.dispatches:sales_dispatches_invariant_1
CREATE TRIGGER "dispatches_command_guard" BEFORE INSERT OR UPDATE OR DELETE ON "sales"."dispatches" FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands"."guard_typed_source_posting"();
CREATE FUNCTION "erp_trade_commands"."post_dispatch"(p_org_id uuid, p_dispatch_id uuid, p_inventory_document_id uuid, p_actor_id uuid, p_idempotency_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE claim_id uuid; replay_id uuid; source sales.dispatches%ROWTYPE;
BEGIN
    PERFORM erp_trade_commands.assert_context(p_org_id,p_actor_id);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      p_org_id,p_actor_id,'sales.dispatch.post',p_idempotency_key_hash,p_request_hash,p_expires_at
    );
    IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
    SELECT * INTO STRICT source FROM sales.dispatches WHERE org_id=p_org_id AND id=p_dispatch_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('sales.dispatch.post',source.branch_id);
    PERFORM erp_trade_commands.assert_permission('inventory.document.post',source.branch_id);
    IF source.status<>'draft' OR NOT EXISTS (
        SELECT 1 FROM inventory.inventory_documents doc WHERE doc.org_id=p_org_id AND doc.id=p_inventory_document_id
          AND doc.sales_dispatch_id=p_dispatch_id AND doc.document_type='sales_issue' AND doc.status='approved'
    ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='dispatch requires one approved typed inventory issue'; END IF;
    PERFORM erp_trade_commands.post_locked_document(p_org_id,p_inventory_document_id,p_actor_id);
    UPDATE sales.dispatches SET status='posted',posted_at=pg_catalog.transaction_timestamp(),posted_by_membership_id=p_actor_id,
      updated_at=pg_catalog.transaction_timestamp(),updated_by_membership_id=p_actor_id,row_version=row_version+1
      WHERE org_id=p_org_id AND id=p_dispatch_id AND status='draft';
    PERFORM erp_trade_commands.finish_claim(p_org_id,claim_id,'sales.dispatches',p_dispatch_id);
    RETURN p_dispatch_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands"."post_dispatch"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands"."post_dispatch"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_trade_commands"."post_dispatch"(uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
-- Reviewed enforcement: sales.invoice_dispatch_allocations:sales_invoice_dispatch_allocations_invariant_1
CREATE FUNCTION "erp_trade_invariants"."guard_invoice_dispatch_allocation"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    invoice_line sales.invoice_lines%ROWTYPE;
    dispatch_line sales.dispatch_lines%ROWTYPE;
    invoice_status text;
    invoice_billed numeric(20,6);
    invoice_free numeric(20,6);
    dispatch_billed numeric(20,6);
    dispatch_free numeric(20,6);
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT invoice.status INTO invoice_status FROM sales.invoice_lines line
        JOIN sales.invoices invoice ON invoice.org_id=line.org_id AND invoice.id=line.invoice_id
        WHERE line.org_id=OLD.org_id AND line.id=OLD.invoice_line_id FOR SHARE OF invoice;
        IF invoice_status IN ('posted','reversed') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted invoice allocation is immutable';
        END IF;
        RETURN OLD;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':invoice:' || NEW.invoice_line_id::text, 81957013));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(NEW.org_id::text || ':dispatch:' || NEW.dispatch_line_id::text, 81957013));
    SELECT line.* INTO invoice_line FROM sales.invoice_lines line
    JOIN sales.invoices invoice ON invoice.org_id=line.org_id AND invoice.id=line.invoice_id
    WHERE line.org_id=NEW.org_id AND line.id=NEW.invoice_line_id FOR SHARE OF line, invoice;
    SELECT invoice.status INTO invoice_status FROM sales.invoices invoice
    WHERE invoice.org_id=NEW.org_id AND invoice.id=invoice_line.invoice_id;
    SELECT * INTO dispatch_line FROM sales.dispatch_lines WHERE org_id=NEW.org_id AND id=NEW.dispatch_line_id FOR SHARE;
    IF invoice_status IN ('posted','reversed')
       AND (TG_OP = 'INSERT' OR NEW IS DISTINCT FROM OLD) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'posted invoice allocation is immutable';
    END IF;
    IF invoice_line.id IS NULL OR dispatch_line.id IS NULL
       OR invoice_line.line_kind <> 'product'
       OR invoice_line.product_id IS DISTINCT FROM dispatch_line.product_id
       OR invoice_line.order_line_id IS DISTINCT FROM dispatch_line.order_line_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invoice allocation source product or order line mismatch';
    END IF;
    SELECT COALESCE(sum(allocated_base_billed_quantity),0), COALESCE(sum(allocated_base_free_quantity),0)
      INTO invoice_billed, invoice_free FROM sales.invoice_dispatch_allocations
     WHERE org_id=NEW.org_id AND invoice_line_id=NEW.invoice_line_id;
    SELECT COALESCE(sum(allocated_base_billed_quantity),0), COALESCE(sum(allocated_base_free_quantity),0)
      INTO dispatch_billed, dispatch_free FROM sales.invoice_dispatch_allocations
     WHERE org_id=NEW.org_id AND dispatch_line_id=NEW.dispatch_line_id;
    IF invoice_billed > invoice_line.base_billed_quantity OR invoice_free > invoice_line.base_free_quantity
       OR dispatch_billed > dispatch_line.base_billed_quantity OR dispatch_free > dispatch_line.base_free_quantity THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'cumulative invoice/dispatch allocation exceeds either source line';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_invoice_dispatch_allocation"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_invoice_dispatch_allocation"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "invoice_dispatch_allocations_cap_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "sales"."invoice_dispatch_allocations" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_invoice_dispatch_allocation"();
-- Reviewed enforcement: sales.invoice_lines:sales_invoice_lines_invariant_1
CREATE FUNCTION "erp_commercial_commands"."guard_posted_sales_invoice_lines"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_id uuid; parent_status text;
BEGIN
    parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;
    SELECT status INTO STRICT parent_status FROM sales.invoices
     WHERE org_id=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
       AND id=parent_id FOR SHARE;
    IF parent_status IN ('posted','reversed') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved commercial lines are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_posted_sales_invoice_lines"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_posted_sales_invoice_lines"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "guard_posted_sales_invoice_lines" BEFORE INSERT OR UPDATE OR DELETE ON "sales"."invoice_lines" FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_posted_sales_invoice_lines"();
-- Reviewed enforcement: sales.invoices:sales_invoices_invariant_1
CREATE FUNCTION "erp_commercial_commands"."assert_sales_invoice_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header sales.invoices%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM sales.invoices
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status NOT IN ('draft','posted') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated invoice is not in its postable or posted state';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'sales.invoice.post'
       OR p_input->>'resource_type'<>'sales_invoice'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'operation'<>'sales.invoice.post'
       OR p_output->>'resource_type'<>'sales_invoice'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted invoice';
    END IF;

    SELECT count(*) INTO expected_lines FROM sales.invoice_lines
     WHERE org_id=p_org_id AND invoice_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM sales.invoice_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.invoice_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR tax_version.ruleset_version IS DISTINCT FROM header.calculation_ruleset_version
         OR header.invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.invoice_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."assert_sales_invoice_artifact"(uuid,uuid,jsonb,jsonb) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."assert_sales_invoice_artifact"(uuid,uuid,jsonb,jsonb) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."post_sales_invoice"(organization_id uuid, resource_id uuid, artifact_id uuid, actor_id uuid, request_id uuid, command_request_id uuid, tax_document_id uuid, journal_id uuid, journal_number varchar, event_id uuid, open_item_id uuid, inventory_document_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header sales.invoices%ROWTYPE; artifact calculation.artifacts%ROWTYPE; line record;
        claim_id uuid; replay_id uuid; input_doc jsonb; output_doc jsonb; consumed bytea;
        party_id uuid; party_account uuid; party_default_account uuid; posted_time timestamptz:=pg_catalog.transaction_timestamp();
        line_no integer:=2; component_amount numeric(20,2); role_account uuid; role_key varchar;
        total_debit numeric(20,2); total_credit numeric(20,2); tax_effective date; source_hash bytea; noncreditable_tax numeric(20,2);
        eligible_cgst numeric(20,2):=0; eligible_sgst numeric(20,2):=0; eligible_igst numeric(20,2):=0; eligible_cess numeric(20,2):=0;
        inventory_value numeric(20,2):=0; inventory_entries bigint:=0; product_lines boolean:=false; allocated_lines boolean:=false;
        line_snapshot jsonb; registration_scope_count bigint;
BEGIN
    PERFORM erp_trade_commands.assert_context(organization_id,actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM request_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='commercial request context mismatch'; END IF;
    SELECT * INTO STRICT header FROM sales.invoices WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('sales.invoice.post',header.branch_id);
    IF NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='finance journal permission denied'; END IF;
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      organization_id,actor_id,'sales.invoice.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN IF replay_id<>resource_id THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='commercial replay mismatch'; END IF; RETURN replay_id; END IF;
    SELECT * INTO STRICT artifact FROM calculation.artifacts WHERE org_id=organization_id AND id=artifact_id FOR UPDATE;
    input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
    output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
    IF artifact.sales_invoice_id IS DISTINCT FROM resource_id OR artifact.engine_version IS DISTINCT FROM output_doc->>'engine_version'
       OR artifact.ruleset_version IS DISTINCT FROM output_doc->>'ruleset_version' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed calculation artifact metadata mismatch'; END IF;
    PERFORM "erp_commercial_commands".assert_sales_invoice_artifact(organization_id,resource_id,input_doc,output_doc);

    SELECT account.party_id,account.default_receivable_account_id INTO party_id,party_default_account
      FROM parties.customer_accounts account WHERE account.org_id=organization_id AND account.id=header.customer_account_id AND account.status='active' FOR SHARE;
    IF party_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial party account is inactive'; END IF;
    party_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,'accounts_receivable','asset',header.currency_code,true);
    IF party_default_account IS DISTINCT FROM party_account THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='party default ledger differs from active branch account-role mapping'; END IF;
    PERFORM 1 FROM tax.registrations registration WHERE registration.org_id=organization_id AND registration.id=header.seller_tax_registration_id
      AND registration.status='active' AND registration.effective_from<=header.invoice_date
      AND (registration.effective_to IS NULL OR registration.effective_to>=header.invoice_date) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax registration is not active on document date'; END IF;
    SELECT count(*) INTO registration_scope_count FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.seller_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.invoice_date);
    IF registration_scope_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document requires exactly one effective branch registration association'; END IF;
    PERFORM 1 FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.seller_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.invoice_date) FOR SHARE;
    SELECT min(version.effective_from) INTO tax_effective FROM sales.invoice_lines tax_line JOIN tax.tax_code_versions version ON version.id=tax_line.tax_code_version_id
      WHERE tax_line.org_id=organization_id AND tax_line.invoice_id=resource_id AND version.status='active'
        AND version.effective_from<=header.invoice_date AND (version.effective_to IS NULL OR version.effective_to>=header.invoice_date)
      HAVING count(DISTINCT version.ruleset_version)=1 AND min(version.ruleset_version)=header.calculation_ruleset_version
        AND count(*)=(SELECT count(*) FROM sales.invoice_lines expected WHERE expected.org_id=organization_id AND expected.invoice_id=resource_id);
    IF tax_effective IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice tax ruleset is not uniform'; END IF;

    SELECT EXISTS(SELECT 1 FROM sales.invoice_lines invoice_product_line WHERE invoice_product_line.org_id=organization_id AND invoice_product_line.invoice_id=resource_id
                           AND invoice_product_line.line_kind='product' AND NOT EXISTS (
                             SELECT 1 FROM sales.invoice_dispatch_allocations allocation
                              WHERE allocation.org_id=invoice_product_line.org_id AND allocation.invoice_line_id=invoice_product_line.id)),
                 EXISTS(SELECT 1 FROM sales.invoice_dispatch_allocations allocation JOIN sales.invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.invoice_line_id WHERE invoice_line.org_id=organization_id AND invoice_line.invoice_id=resource_id)
            INTO product_lines,allocated_lines;
        IF product_lines<>(inventory_document_id IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct sales invoice inventory ownership mismatch'; END IF;
        IF allocated_lines AND EXISTS (
          SELECT 1 FROM sales.invoice_dispatch_allocations allocation
          JOIN sales.invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.invoice_line_id
          WHERE invoice_line.org_id=organization_id AND invoice_line.invoice_id=resource_id
            AND (SELECT count(*) FROM inventory.inventory_document_lines inventory_line
                 JOIN inventory.inventory_documents inventory_document ON inventory_document.org_id=inventory_line.org_id AND inventory_document.id=inventory_line.inventory_document_id AND inventory_document.status='posted'
                 JOIN finance.accounting_events event ON event.org_id=inventory_document.org_id AND event.inventory_document_id=inventory_document.id AND event.event_type='inventory_valuation'
                 WHERE inventory_line.org_id=allocation.org_id AND inventory_line.sales_dispatch_line_id=allocation.dispatch_line_id)<>1
        ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='allocated dispatch lacks exactly one posted inventory-valuation accounting event'; END IF;
        IF inventory_document_id IS NOT NULL THEN
          PERFORM erp_commercial_commands.post_owned_inventory_document(
            organization_id,inventory_document_id,actor_id,'sales_invoice',resource_id,header.branch_id);
          SELECT coalesce(sum(-entry.value_delta),0),count(*) INTO inventory_value,inventory_entries FROM inventory.stock_ledger_entries entry WHERE entry.org_id=organization_id AND entry.inventory_document_id=inventory_document_id AND entry.entry_kind='issue';
          IF inventory_entries=0 OR inventory_value<=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted sales issue has no authoritative ledger value'; END IF;
        END IF;
    consumed:=erp_calculation_authority.consume_artifact(organization_id,artifact_id,'sales.invoice.post','sales_invoice',resource_id,
      header.row_version,request_id,command_request_id,claim_id);
    IF pg_catalog.convert_from(consumed,'UTF8')::jsonb IS DISTINCT FROM output_doc THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed calculation changed'; END IF;

    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,transaction_currency,functional_currency,fx_rate,
      transaction_debit_total,transaction_credit_total,functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,header.invoice_date,'sales_invoice',header.currency_code,'INR',1,
      header.grand_total,header.grand_total,header.grand_total,header.grand_total,'draft',actor_id,actor_id);
    PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,1,party_account,header.branch_id,party_id,
      'Customer receivable',header.grand_total,0,actor_id);
    FOR line IN SELECT * FROM sales.invoice_lines WHERE org_id=organization_id AND invoice_id=resource_id ORDER BY line_number,id LOOP
        PERFORM "erp_commercial_commands".assert_line_account(organization_id,line.revenue_account_id,'income',header.currency_code);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,line.revenue_account_id,header.branch_id,NULL,
          'Invoice net value',0,line.net_value_amount,actor_id); line_no:=line_no+1;
    END LOOP;
    IF inventory_value>0 THEN
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'cost_of_goods_sold','expense',header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'COGS from posted stock ledger',inventory_value,0,actor_id); line_no:=line_no+1;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'inventory_asset','asset',header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Inventory issue from posted stock ledger',0,inventory_value,actor_id); line_no:=line_no+1;
    END IF;
    FOR role_key,component_amount IN SELECT * FROM (VALUES
      ('output_cgst'::varchar,header.cgst_total),
      ('output_sgst'::varchar,header.sgst_total),
      ('output_igst'::varchar,header.igst_total),
      ('output_cess'::varchar,header.cess_total)) AS component(role_key,amount)
    LOOP
      IF component_amount>0 AND header.tax_charge_mechanism='normal' THEN
        role_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,role_key,'liability',header.currency_code,false);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Output tax',0,component_amount,actor_id); line_no:=line_no+1;
      END IF;
    END LOOP;


    IF header.rounding_adjustment<>0 THEN
      role_key:=CASE WHEN header.rounding_adjustment>0 THEN 'rounding_gain' ELSE 'rounding_loss' END;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,CASE WHEN role_key='rounding_gain' THEN 'income' ELSE 'expense' END,header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Signed rounding adjustment',
        CASE WHEN header.rounding_adjustment<0 THEN abs(header.rounding_adjustment) ELSE 0 END,
        CASE WHEN header.rounding_adjustment>0 THEN abs(header.rounding_adjustment) ELSE 0 END,actor_id); line_no:=line_no+1;
    END IF;
    SELECT coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0) INTO total_debit,total_credit
      FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=journal_id;
    IF total_debit<>total_credit OR total_debit=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial journal does not exactly balance'; END IF;
    UPDATE finance.journal_entries SET transaction_debit_total=total_debit,transaction_credit_total=total_credit,
      functional_debit_total=total_debit,functional_credit_total=total_credit,status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=journal_id;
    UPDATE sales.invoices SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=resource_id AND status='draft';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='invoice posting state changed'; END IF;
    NULL;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source_line) ORDER BY source_line.line_number,source_line.id) INTO line_snapshot
      FROM sales.invoice_lines source_line WHERE source_line.org_id=organization_id AND source_line.invoice_id=resource_id;
    source_hash:=extensions.digest(pg_catalog.convert_to((pg_catalog.to_jsonb(header)||pg_catalog.jsonb_build_object('lines',line_snapshot,'artifact',pg_catalog.encode(artifact.output_sha256,'hex')))::text,'UTF8'),'sha256');
    INSERT INTO tax.documents(org_id,id,registration_id,sales_invoice_id,document_class,document_number,document_date,direction,
      counterparty_party_id,counterparty_gstin,place_of_supply_state_code,supply_type,zero_rated_payment_mode,tax_charge_mechanism,
      tax_liability_party,document_effect,currency_code,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,igst_amount,cess_amount,
      self_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,tax_ruleset_version,tax_ruleset_effective_date,source_hash,posted_at,created_by_membership_id)
    VALUES(organization_id,tax_document_id,header.seller_tax_registration_id,resource_id,'sales_invoice',header.invoice_number,header.invoice_date,'outward',
      party_id,header.buyer_gstin_snapshot,header.place_of_supply_state_code,header.supply_type,header.zero_rated_payment_mode,header.tax_charge_mechanism,
      CASE WHEN header.tax_charge_mechanism='normal' THEN 'supplier' ELSE 'recipient' END,'original',header.currency_code,
      header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,
      CASE WHEN 'outward'='inward' AND header.tax_charge_mechanism='reverse_charge' THEN header.recipient_assessed_tax_total ELSE 0 END,
      header.rounding_adjustment,header.grand_total,header.calculation_ruleset_version,tax_effective,source_hash,posted_time,actor_id);
    INSERT INTO finance.accounting_events(org_id,id,event_type,sales_invoice_id,journal_entry_id,occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,event_id,'sales_invoice',resource_id,journal_id,posted_time,posted_time,actor_id);
    INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,currency_code,
      principal_amount,functional_principal_amount,status,created_by_membership_id)
    VALUES(organization_id,open_item_id,event_id,party_id,'receivable',header.invoice_number,header.invoice_date,
      coalesce(header.due_date,header.invoice_date),header.currency_code,header.grand_total,header.grand_total,'open',actor_id);
    PERFORM erp_trade_commands.finish_claim(organization_id,claim_id,'sales.invoices',resource_id);
    RETURN resource_id;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."post_sales_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."post_sales_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_commercial_commands"."post_sales_invoice"(uuid,uuid,uuid,uuid,uuid,uuid,uuid,uuid,varchar,uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
CREATE FUNCTION "erp_commercial_commands"."guard_sales_invoice_companions"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE artifact calculation.artifacts%ROWTYPE; companion_count bigint; event_id uuid;
        input_doc jsonb; output_doc jsonb;
BEGIN
    IF TG_OP='DELETE' THEN
      IF OLD.status IN ('posted','reversed') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice is retained'; END IF;
      RETURN OLD;
    END IF;
    IF NEW.status='posted' THEN
      SELECT count(*),(pg_catalog.array_agg(id))[1] INTO companion_count,artifact.id FROM calculation.artifacts
       WHERE org_id=NEW.org_id AND sales_invoice_id=NEW.id AND operation='sales.invoice.post' AND status='consumed';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one consumed typed calculation artifact'; END IF;
      SELECT * INTO STRICT artifact FROM calculation.artifacts stored WHERE stored.org_id=NEW.org_id AND stored.id=artifact.id;
      input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
      output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
      PERFORM erp_commercial_commands.assert_sales_invoice_artifact(NEW.org_id,NEW.id,input_doc,output_doc);
      SELECT count(*) INTO companion_count FROM tax.documents WHERE org_id=NEW.org_id AND sales_invoice_id=NEW.id AND document_class='sales_invoice';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one typed tax document'; END IF;
      SELECT count(*),(pg_catalog.array_agg(event.id))[1] INTO companion_count,event_id FROM finance.accounting_events event
       JOIN finance.journal_entries journal ON journal.org_id=event.org_id AND journal.id=event.journal_entry_id AND journal.status='posted'
       WHERE event.org_id=NEW.org_id AND event.sales_invoice_id=NEW.id AND event.event_type='sales_invoice';
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one posted accounting event'; END IF;
      SELECT count(*) INTO companion_count FROM finance.open_items WHERE org_id=NEW.org_id AND accounting_event_id=event_id;
      IF companion_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted invoice requires exactly one open item'; END IF;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_commercial_commands"."guard_sales_invoice_companions"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_commercial_commands"."guard_sales_invoice_companions"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "guard_sales_invoice_companions_ct" AFTER INSERT OR UPDATE OR DELETE ON "sales"."invoices" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "erp_commercial_commands"."guard_sales_invoice_companions"();
-- Reviewed enforcement: sales.invoices:sales_invoices_invariant_2
CREATE FUNCTION "erp_trade_invariants"."guard_direct_invoice_issue"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
    target_invoice uuid;
    target_org uuid;
    invoice_branch uuid;
    direct_count bigint;
BEGIN
    IF TG_TABLE_NAME = 'inventory_documents' THEN
        target_invoice := CASE WHEN TG_OP='DELETE' THEN OLD.sales_invoice_id ELSE NEW.sales_invoice_id END;
        target_org := CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
    ELSE
        SELECT line.invoice_id, line.org_id INTO target_invoice, target_org
          FROM sales.invoice_lines AS line
         WHERE line.org_id = CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
           AND line.id = CASE WHEN TG_OP='DELETE' THEN OLD.invoice_line_id ELSE NEW.invoice_line_id END;
    END IF;
    IF target_invoice IS NULL THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(target_org::text || ':' || target_invoice::text, 470893037));
    SELECT branch_id INTO invoice_branch FROM sales.invoices WHERE org_id=target_org AND id=target_invoice FOR SHARE;
    SELECT count(*) INTO direct_count FROM inventory.inventory_documents
     WHERE org_id=target_org AND sales_invoice_id=target_invoice;
    IF direct_count > 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'invoice owns more than one direct inventory issue';
    END IF;
    IF EXISTS (
        SELECT 1 FROM sales.invoice_dispatch_allocations allocation
        JOIN sales.invoice_lines line ON line.org_id=allocation.org_id AND line.id=allocation.invoice_line_id
        JOIN inventory.inventory_document_lines issue_line
          ON issue_line.org_id=line.org_id AND issue_line.sales_invoice_line_id=line.id
        JOIN inventory.inventory_documents issue_document
          ON issue_document.org_id=issue_line.org_id AND issue_document.id=issue_line.inventory_document_id
         AND issue_document.sales_invoice_id=target_invoice
        WHERE line.org_id=target_org AND line.invoice_id=target_invoice
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'one invoice line cannot be both dispatch allocated and directly issued';
    END IF;
    IF TG_TABLE_NAME = 'inventory_documents' AND TG_OP <> 'DELETE' THEN
        IF NEW.sales_invoice_id IS NOT NULL
           AND (NEW.document_type <> 'sales_issue' OR NEW.branch_id IS DISTINCT FROM invoice_branch) THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'direct invoice stock document type or branch is invalid';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_invariants"."guard_direct_invoice_issue"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_invariants"."guard_direct_invoice_issue"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE CONSTRAINT TRIGGER "inventory_documents_direct_invoice_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "inventory"."inventory_documents" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_direct_invoice_issue"();
CREATE CONSTRAINT TRIGGER "invoice_allocations_direct_issue_guard_ct" AFTER INSERT OR UPDATE OR DELETE ON "sales"."invoice_dispatch_allocations" DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION "erp_trade_invariants"."guard_direct_invoice_issue"();
-- Reviewed enforcement: sales.order_lines:sales_order_lines_invariant_1
CREATE FUNCTION "erp_trade_commands_v2"."assert_sales_order_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header sales.orders%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM sales.orders
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status<>'submitted' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated order is no longer submitted';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'sales.order.approve'
       OR p_input->>'resource_type'<>'sales_order'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'operation'<>'sales.order.approve'
       OR p_output->>'resource_type'<>'sales_order'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted order';
    END IF;

    SELECT count(*) INTO expected_lines FROM sales.order_lines
     WHERE org_id=p_org_id AND order_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM sales.order_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.order_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR tax_version.ruleset_version IS DISTINCT FROM header.calculation_ruleset_version
         OR header.order_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.order_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."assert_sales_order_artifact"(uuid,uuid,jsonb,jsonb) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."assert_sales_order_artifact"(uuid,uuid,jsonb,jsonb) FROM PUBLIC, "erp_app", "erp_runtime";
CREATE FUNCTION "erp_trade_commands_v2"."guard_approved_sales_order_lines"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE parent_id uuid; parent_status text;
BEGIN
    parent_id := CASE WHEN TG_OP='DELETE' THEN OLD.order_id ELSE NEW.order_id END;
    SELECT status INTO STRICT parent_status FROM sales.orders
     WHERE org_id=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END
       AND id=parent_id FOR SHARE;
    IF parent_status IN ('approved','partially_fulfilled','fulfilled') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved commercial lines are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$;
