CREATE FUNCTION "erp_trade_commands_v2"."guard_sales_order_approval"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE actor_id uuid := NULLIF(pg_catalog.current_setting('app.membership_id',true),'')::uuid;
BEGIN
    IF TG_OP='INSERT' AND NEW.status IN ('approved','partially_fulfilled','fulfilled') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial approval requires the canonical calculation command';
    END IF;
    IF TG_OP='UPDATE' AND OLD.status NOT IN ('approved','partially_fulfilled','fulfilled') AND NEW.status IN ('approved','partially_fulfilled','fulfilled')
       AND NOT EXISTS (
           SELECT 1 FROM calculation.artifacts AS artifact
            WHERE artifact.org_id=NEW.org_id AND artifact.sales_order_id=NEW.id
              AND artifact.status='consumed' AND artifact.consumed_by_membership_id=actor_id
              AND artifact.consumed_at=pg_catalog.transaction_timestamp()
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial approval lacks a transaction-bound calculation artifact';
    END IF;
    IF TG_OP='UPDATE' AND OLD.status IN ('approved','partially_fulfilled','fulfilled')
       AND ROW(NEW.branch_id,NEW.customer_account_id,NEW.order_number,NEW.fiscal_year,NEW.order_date,NEW.requested_delivery_date,NEW.supply_type,NEW.zero_rated_payment_mode,NEW.tax_charge_mechanism,NEW.billing_address_id,NEW.shipping_address_id,NEW.customer_po_number,NEW.customer_po_date,NEW.currency_code,NEW.calculation_ruleset_version,NEW.document_discount_kind,NEW.document_discount_basis,NEW.document_discount_value,NEW.subtotal,NEW.discount_total,NEW.charges_total,NEW.net_value_total,NEW.gst_taxable_total,NEW.cgst_total,NEW.sgst_total,NEW.igst_total,NEW.cess_total,NEW.recipient_assessed_tax_total,NEW.rounding_policy,NEW.rounding_adjustment,NEW.grand_total) IS DISTINCT FROM ROW(OLD.branch_id,OLD.customer_account_id,OLD.order_number,OLD.fiscal_year,OLD.order_date,OLD.requested_delivery_date,OLD.supply_type,OLD.zero_rated_payment_mode,OLD.tax_charge_mechanism,OLD.billing_address_id,OLD.shipping_address_id,OLD.customer_po_number,OLD.customer_po_date,OLD.currency_code,OLD.calculation_ruleset_version,OLD.document_discount_kind,OLD.document_discount_basis,OLD.document_discount_value,OLD.subtotal,OLD.discount_total,OLD.charges_total,OLD.net_value_total,OLD.gst_taxable_total,OLD.cgst_total,OLD.sgst_total,OLD.igst_total,OLD.cess_total,OLD.recipient_assessed_tax_total,OLD.rounding_policy,OLD.rounding_adjustment,OLD.grand_total) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approved commercial terms are immutable';
    END IF;
    RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."guard_sales_order_approval"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."guard_sales_order_approval"() FROM PUBLIC, "erp_app", "erp_runtime";
CREATE TRIGGER "guard_sales_order_approval" BEFORE INSERT OR UPDATE ON "sales"."orders" FOR EACH ROW EXECUTE FUNCTION "erp_trade_commands_v2"."guard_sales_order_approval"();
CREATE FUNCTION "erp_trade_commands_v2"."approve_sales_order"(p_org_id uuid, p_resource_id uuid, p_artifact_id uuid, p_actor_id uuid, p_request_id uuid, p_command_request_id uuid, p_idempotency_key_hash bytea, p_request_hash bytea, p_expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header sales.orders%ROWTYPE;
        claim_id uuid;
        replay_id uuid;
        input_document jsonb;
        output_document jsonb;
        output_bytes bytea;
        command_time timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    PERFORM erp_trade_commands.assert_context(p_org_id,p_actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM p_request_id THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='approval request context differs from calculation artifact';
    END IF;
    SELECT * INTO STRICT header FROM sales.orders
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('sales.order.manage',header.branch_id);
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id
      FROM erp_trade_commands.claim(
        p_org_id,p_actor_id,'sales.order.approve',p_idempotency_key_hash,p_request_hash,p_expires_at
      );
    IF replay_id IS NOT NULL THEN
        IF replay_id IS DISTINCT FROM p_resource_id THEN
            RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='approval replay resource differs';
        END IF;
        RETURN replay_id;
    END IF;
    SELECT pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb,
           pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb
      INTO STRICT input_document,output_document
      FROM calculation.artifacts AS artifact
     WHERE artifact.org_id=p_org_id AND artifact.id=p_artifact_id FOR UPDATE;
    PERFORM erp_trade_commands_v2.assert_sales_order_artifact(p_org_id,p_resource_id,input_document,output_document);
    output_bytes := erp_calculation_authority.consume_artifact(
        p_org_id,p_artifact_id,'sales.order.approve','sales_order',p_resource_id,
        header.row_version,p_request_id,p_command_request_id,claim_id
    );
    IF pg_catalog.convert_from(output_bytes,'UTF8')::jsonb IS DISTINCT FROM output_document THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed calculation output changed after exact comparison';
    END IF;
    UPDATE sales.orders
       SET status='approved',approved_at=command_time,approved_by_membership_id=p_actor_id,
           updated_at=command_time,updated_by_membership_id=p_actor_id,row_version=row_version+1
     WHERE org_id=p_org_id AND id=p_resource_id AND status='submitted'
       AND row_version=header.row_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='approval aggregate changed during verification';
    END IF;
    PERFORM erp_trade_commands.finish_claim(p_org_id,claim_id,'sales.orders',p_resource_id);
    RETURN p_resource_id;
END
$function$;
ALTER FUNCTION "erp_trade_commands_v2"."approve_sales_order"(uuid,uuid,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_trade_commands_v2"."approve_sales_order"(uuid,uuid,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_trade_commands_v2"."approve_sales_order"(uuid,uuid,uuid,uuid,uuid,uuid,bytea,bytea,timestamptz) TO "erp_app", "erp_runtime";
