CREATE FUNCTION "erp_regulatory_commands"."guard_einvoice_rule_version"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'active' OR NOT "erp_regulatory_commands"."scope_active"('reference_import',NEW.release_id) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='einvoice_rule_versions requires verified exact-set import provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deployed einvoice_rule_versions rows are retained'; END IF;
  IF ROW(NEW.id,NEW.release_id,NEW.rule_code,NEW.rule_version,NEW.organization_person_type,NEW.organization_exemption_code,NEW.registration_type,NEW.document_class,NEW.supply_scope,NEW.minimum_prior_fy_turnover,NEW.reporting_window_days,NEW.effective_from,NEW.effective_to,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.release_id,OLD.rule_code,OLD.rule_version,OLD.organization_person_type,OLD.organization_exemption_code,OLD.registration_type,OLD.document_class,OLD.supply_scope,OLD.minimum_prior_fy_turnover,OLD.reporting_window_days,OLD.effective_from,OLD.effective_to,OLD.created_at)
     OR OLD.status<>'active' OR NEW.status<>'retired'
     OR NOT "erp_regulatory_commands"."scope_active"('reference_import',OLD.release_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='einvoice_rule_versions authority is immutable';
  END IF;
  RETURN NEW;
END
$function$;
