CREATE FUNCTION "erp_tax_provider_commands"."guard_einvoice"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider authority evidence is retained';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'requested'
       OR NOT "erp_tax_provider_commands"."scope_active"('provider_begin',NEW.id)
       OR NOT "erp_tax_provider_commands"."adapter_allowed"('einvoice',NEW.provider_name)
       OR NEW.request_media_type<>'application/vnd.aasopharma.einvoice-request+json'
       OR NEW.request_sha256<>extensions.digest(NEW.request_bytes,'sha256')
       OR NEW.response_bytes IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider attempt lacks canonical command provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status<>'requested' OR NEW.status NOT IN ('generated','failed','cancelled')
     OR NOT "erp_tax_provider_commands"."scope_active"('provider_complete',OLD.id)
     OR ROW(NEW.org_id,NEW.id,NEW.tax_document_id,NEW.rule_version_id,NEW.artifact_version,
            NEW.supersedes_artifact_id,NEW.request_media_type,NEW.request_bytes,
            NEW.request_sha256,NEW.provider_name,NEW.provider_request_id,
            NEW.created_at,NEW.created_by_membership_id)
        IS DISTINCT FROM
        ROW(OLD.org_id,OLD.id,OLD.tax_document_id,OLD.rule_version_id,OLD.artifact_version,
            OLD.supersedes_artifact_id,OLD.request_media_type,OLD.request_bytes,
            OLD.request_sha256,OLD.provider_name,OLD.provider_request_id,
            OLD.created_at,OLD.created_by_membership_id)
     OR OLD.response_bytes IS NOT NULL OR NEW.response_bytes IS NULL
     OR NEW.response_sha256<>extensions.digest(NEW.response_bytes,'sha256') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider evidence completion is invalid or mutable';
  END IF;
  RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_tax_provider_commands"."guard_einvoice"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_tax_provider_commands"."guard_einvoice"() FROM PUBLIC, "erp_app", "erp_runtime", "erp_tax_provider";
