REVOKE ALL ON FUNCTION "erp_tax_provider_commands"."complete_eway_bill"(organization_id uuid, artifact_id uuid, expected_adapter_name varchar, expected_provider_request_id varchar, expected_request_sha256 bytea, outcome text, response_media_type varchar, response_bytes bytea, response_sha256 bytea, eway_bill_number varchar, transport_mode text, vehicle_number varchar, transporter_id varchar, valid_from_at timestamptz, valid_until_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime", "erp_tax_provider";
GRANT EXECUTE ON FUNCTION "erp_tax_provider_commands"."complete_eway_bill"(organization_id uuid, artifact_id uuid, expected_adapter_name varchar, expected_provider_request_id varchar, expected_request_sha256 bytea, outcome text, response_media_type varchar, response_bytes bytea, response_sha256 bytea, eway_bill_number varchar, transport_mode text, vehicle_number varchar, transporter_id varchar, valid_from_at timestamptz, valid_until_at timestamptz) TO "erp_tax_provider";
