COMMENT ON TABLE "tax"."eway_bills" IS 'Provider evidence state machine is installed with the e-invoice authority mapping';
-- Reviewed enforcement: tax.gst_adjustment_rule_versions:gst_adjustment_rule_versions_release_authority
CREATE FUNCTION "erp_regulatory_commands"."guard_gst_adjustment_rule_version"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'active' OR NOT "erp_regulatory_commands"."scope_active"('reference_import',NEW.release_id) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='gst_adjustment_rule_versions requires verified exact-set import provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deployed gst_adjustment_rule_versions rows are retained'; END IF;
  IF ROW(NEW.id,NEW.release_id,NEW.rule_code,NEW.rule_version,NEW.side,NEW.direction,NEW.document_effect,NEW.reason_code,NEW.deadline_policy,NEW.deadline_days,NEW.portal_evidence_required,NEW.tax_effect,NEW.effective_from,NEW.effective_to,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.release_id,OLD.rule_code,OLD.rule_version,OLD.side,OLD.direction,OLD.document_effect,OLD.reason_code,OLD.deadline_policy,OLD.deadline_days,OLD.portal_evidence_required,OLD.tax_effect,OLD.effective_from,OLD.effective_to,OLD.created_at)
     OR OLD.status<>'active' OR NEW.status<>'retired'
     OR NOT "erp_regulatory_commands"."scope_active"('reference_import',OLD.release_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='gst_adjustment_rule_versions authority is immutable';
  END IF;
  RETURN NEW;
END
$function$;
ALTER FUNCTION "erp_regulatory_commands"."guard_gst_adjustment_rule_version"() OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_regulatory_commands"."guard_gst_adjustment_rule_version"() FROM PUBLIC, "erp_app", "erp_runtime", "erp_regulatory_importer";
CREATE TRIGGER "gst_adjustment_rule_versions_release_guard" BEFORE INSERT OR UPDATE OR DELETE ON "tax"."gst_adjustment_rule_versions" FOR EACH ROW EXECUTE FUNCTION "erp_regulatory_commands"."guard_gst_adjustment_rule_version"();
CREATE FUNCTION "erp_regulatory_commands"."import_gst_adjustment_rule_release"(p_release_id uuid, p_ruleset_version varchar, p_source_authority text, p_source_uri text, p_source_storage_bucket text, p_source_storage_object_path text, p_source_media_type varchar, p_source_bytes bytea, p_source_sha256 bytea, p_dataset_storage_bucket text, p_dataset_storage_object_path text, p_dataset_bytes bytea, p_dataset_sha256 bytea, p_publication_date date, p_effective_from date, p_effective_to date, p_reviewed_by_user_id uuid, p_reviewed_at timestamptz, p_request_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE prior_id uuid; item jsonb; supplied_count integer; dataset_rows jsonb;
BEGIN
  IF p_request_id IS NULL OR NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM p_request_id THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='gst_adjustment_rules import requires matching transaction-local request id';
  END IF;
  dataset_rows:=pg_catalog.convert_from(p_dataset_bytes,'UTF8')::jsonb;
  prior_id:="erp_regulatory_commands"."stage_release"(p_release_id,'gst_adjustment_rules',p_ruleset_version,
    p_source_authority,p_source_uri,p_source_storage_bucket,p_source_storage_object_path,
    p_source_media_type,p_source_bytes,p_source_sha256,p_dataset_storage_bucket,
    p_dataset_storage_object_path,p_dataset_bytes,p_dataset_sha256,p_publication_date,
    p_effective_from,p_effective_to,p_reviewed_by_user_id,p_reviewed_at);
  supplied_count:=pg_catalog.jsonb_array_length(dataset_rows);
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_array_elements(dataset_rows) AS row(value)
     WHERE pg_catalog.jsonb_typeof(value)<>'object'
        OR NOT value ?& ARRAY['id','rule_code','rule_version','side','direction','document_effect','reason_code','deadline_policy','deadline_days','portal_evidence_required','tax_effect','effective_from','effective_to']
        OR value - ARRAY['id','rule_code','rule_version','side','direction','document_effect','reason_code','deadline_policy','deadline_days','portal_evidence_required','tax_effect','effective_from','effective_to'] <> '{}'::jsonb
        OR pg_catalog.btrim(value->>'rule_code')=''
        OR pg_catalog.btrim(value->>'rule_version')=''
        OR (value->>'effective_from')::date<p_effective_from
        OR (p_effective_to IS NOT NULL AND COALESCE(NULLIF(value->>'effective_to','')::date,p_effective_to)>p_effective_to)
  ) OR (SELECT count(DISTINCT value->>'id') FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR (SELECT count(DISTINCT (value->>'rule_code',value->>'rule_version')) FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR EXISTS (
      SELECT 1
        FROM pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS left_row(value,ordinality)
        JOIN pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS right_row(value,ordinality)
          ON left_row.ordinality<right_row.ordinality
       WHERE left_row.value->>'side'=right_row.value->>'side' AND left_row.value->>'direction'=right_row.value->>'direction' AND left_row.value->>'document_effect'=right_row.value->>'document_effect' AND left_row.value->>'reason_code'=right_row.value->>'reason_code' AND left_row.value->>'tax_effect'=right_row.value->>'tax_effect'
         AND (left_row.value->>'effective_from')::date<=COALESCE(NULLIF(right_row.value->>'effective_to','')::date,'infinity'::date)
         AND (right_row.value->>'effective_from')::date<=COALESCE(NULLIF(left_row.value->>'effective_to','')::date,'infinity'::date)
    ) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='gst_adjustment_rules dataset is not one exact non-overlapping typed set';
  END IF;
  IF prior_id IS NOT NULL THEN UPDATE tax.gst_adjustment_rule_versions SET status='retired' WHERE release_id=prior_id AND status='active'; END IF;
  FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(dataset_rows) ORDER BY value->>'id' LOOP
    INSERT INTO tax.gst_adjustment_rule_versions(id,release_id,rule_code,rule_version,side,direction,document_effect,reason_code,deadline_policy,deadline_days,portal_evidence_required,tax_effect,effective_from,effective_to,status) VALUES((item->>'id')::uuid,p_release_id,item->>'rule_code',item->>'rule_version',item->>'side',item->>'direction',item->>'document_effect',item->>'reason_code',item->>'deadline_policy',NULLIF(item->>'deadline_days','')::integer,(item->>'portal_evidence_required')::boolean,item->>'tax_effect',(item->>'effective_from')::date,NULLIF(item->>'effective_to','')::date,'active');
  END LOOP;
  IF (SELECT count(*) FROM tax.gst_adjustment_rule_versions WHERE release_id=p_release_id)<>supplied_count THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='gst_adjustment_rules exact-set count mismatch';
  END IF;
  PERFORM "erp_regulatory_commands"."finish_release"(p_release_id,prior_id);
  RETURN p_release_id;
END
$function$;
