REVOKE ALL ON FUNCTION "erp_compliance_commands"."import_withholding_certificate"(organization_id uuid, certificate_id uuid, actor_id uuid, tax_regime text, registration_id uuid, counterparty_party_id uuid, fiscal_year_start_year smallint, period_start date, period_end date, form_code varchar, certificate_reference varchar, issued_on date, evidence_attachment_id uuid, correction_of_certificate_id uuid, certificate_lines jsonb, key_hash bytea, request_hash bytea, expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
