CREATE FUNCTION "erp_compliance_commands"."post_withholding_deposit"(organization_id uuid, deposit_id uuid, actor_id uuid, payment_id uuid, challan_reference varchar, deposited_on date, evidence_attachment_id uuid, reversal_of_deposit_id uuid, reversal_reason text, deposit_lines jsonb, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE claim_id uuid; replay_id uuid; payment finance.payments%ROWTYPE; evidence core.attachments%ROWTYPE;
 item jsonb; withholding tax.withholdings%ROWTYPE; original tax.withholding_deposits%ROWTYPE;
 original_line tax.withholding_deposit_lines%ROWTYPE;
 regime text; registration_id uuid; total numeric(20,2):=0; income_total numeric(20,2):=0;
 cgst_total numeric(20,2):=0; sgst_total numeric(20,2):=0; igst_total numeric(20,2):=0; already numeric(20,2);
BEGIN
 PERFORM "erp_compliance_commands"."assert_context"(organization_id,actor_id,'tax.withholding.manage',NULL::uuid);
 SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM "erp_compliance_commands"."claim"(
  organization_id,actor_id,'tax.withholding.deposit',key_hash,request_hash,expires_at);
 IF replay_id IS NOT NULL THEN RETURN replay_id; END IF;
 SELECT * INTO payment FROM finance.payments WHERE org_id=organization_id AND id=payment_id FOR UPDATE;
 SELECT * INTO evidence FROM core.attachments WHERE org_id=organization_id AND id=evidence_attachment_id FOR SHARE;
 IF payment.status<>'posted' OR payment.currency_code<>'INR' OR payment.payment_purpose<>'withholding_deposit'
    OR evidence.status NOT IN ('verified','retained')
    OR evidence.verified_at IS NULL OR pg_catalog.jsonb_typeof(deposit_lines)<>'array' OR pg_catalog.jsonb_array_length(deposit_lines)=0 THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deposit requires posted INR government payment and verified challan evidence'; END IF;
 IF reversal_of_deposit_id IS NULL AND payment.direction<>'disbursement' OR reversal_of_deposit_id IS NOT NULL AND payment.direction<>'receipt' THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deposit payment direction is invalid'; END IF;
 IF reversal_of_deposit_id IS NOT NULL THEN SELECT * INTO original FROM tax.withholding_deposits WHERE org_id=organization_id AND id=reversal_of_deposit_id FOR SHARE;
  IF original.status<>'posted' OR reversal_reason IS NULL
     OR EXISTS(SELECT 1 FROM tax.withholding_statement_lines statement_line
       JOIN tax.withholding_deposit_lines deposit_line ON deposit_line.org_id=statement_line.org_id
        AND deposit_line.id=statement_line.deposit_line_id
       WHERE deposit_line.org_id=organization_id AND deposit_line.deposit_id=original.id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deposit reversal requires unfiled immutable posted original and reason'; END IF; END IF;
 FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(deposit_lines) LOOP
  SELECT * INTO withholding FROM tax.withholdings WHERE org_id=organization_id AND id=(item->>'withholding_id')::uuid FOR UPDATE;
  IF withholding.status<>'deducted' OR EXISTS(SELECT 1 FROM tax.withholdings reversal
       WHERE reversal.org_id=organization_id AND reversal.reversal_of_withholding_id=withholding.id)
     OR (regime IS NOT NULL AND regime<>withholding.tax_regime)
     OR (registration_id IS NOT NULL AND registration_id IS DISTINCT FROM withholding.registration_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='challan lines must share one live regime and registration'; END IF;
  regime:=withholding.tax_regime; registration_id:=withholding.registration_id;
  SELECT coalesce(sum(line.deposited_amount),0) INTO already FROM tax.withholding_deposit_lines line
   JOIN tax.withholding_deposits deposit ON deposit.org_id=line.org_id AND deposit.id=line.deposit_id
   WHERE line.org_id=organization_id AND line.withholding_id=withholding.id AND deposit.status='posted'
     AND NOT EXISTS(SELECT 1 FROM tax.withholding_deposits reversal
       WHERE reversal.org_id=deposit.org_id AND reversal.reversal_of_deposit_id=deposit.id);
  IF reversal_of_deposit_id IS NULL THEN
    IF already<>0 OR ROW((item->>'income_tax_amount')::numeric,(item->>'cgst_amount')::numeric,
       (item->>'sgst_amount')::numeric,(item->>'igst_amount')::numeric,(item->>'deposited_amount')::numeric)
       IS DISTINCT FROM ROW(withholding.income_tax_amount,withholding.cgst_amount,withholding.sgst_amount,
       withholding.igst_amount,withholding.withheld_amount) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='challan must deposit each deduction and component exactly once'; END IF;
  ELSE
    SELECT line.* INTO original_line FROM tax.withholding_deposit_lines line
     WHERE line.org_id=organization_id AND line.deposit_id=original.id AND line.withholding_id=withholding.id FOR SHARE;
    IF original_line.id IS NULL OR ROW((item->>'income_tax_amount')::numeric,(item->>'cgst_amount')::numeric,
       (item->>'sgst_amount')::numeric,(item->>'igst_amount')::numeric,(item->>'deposited_amount')::numeric)
       IS DISTINCT FROM ROW(original_line.income_tax_amount,original_line.cgst_amount,original_line.sgst_amount,
       original_line.igst_amount,original_line.deposited_amount) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='deposit reversal must copy the original component allocation'; END IF;
  END IF;
  income_total:=income_total+(item->>'income_tax_amount')::numeric; cgst_total:=cgst_total+(item->>'cgst_amount')::numeric;
  sgst_total:=sgst_total+(item->>'sgst_amount')::numeric; igst_total:=igst_total+(item->>'igst_amount')::numeric;
  total:=total+(item->>'deposited_amount')::numeric;
 END LOOP;
 IF total<>payment.amount OR total<>income_total+cgst_total+sgst_total+igst_total THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='challan line components must equal exact payment'; END IF;
 INSERT INTO "erp_compliance_commands"."command_scopes" VALUES(pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'withholding_deposit',organization_id,deposit_id);
 INSERT INTO tax.withholding_deposits(org_id,id,tax_regime,registration_id,payment_id,challan_reference,deposited_on,
  deposited_amount,evidence_attachment_id,reversal_of_deposit_id,reversal_reason,status,created_by_membership_id)
 VALUES(organization_id,deposit_id,regime,registration_id,payment_id,challan_reference,deposited_on,total,evidence_attachment_id,
  reversal_of_deposit_id,reversal_reason,CASE WHEN reversal_of_deposit_id IS NULL THEN 'posted' ELSE 'reversed' END,actor_id);
 FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(deposit_lines) LOOP
  INSERT INTO tax.withholding_deposit_lines(org_id,id,deposit_id,withholding_id,income_tax_amount,cgst_amount,sgst_amount,igst_amount,deposited_amount,created_by_membership_id)
  VALUES(organization_id,(item->>'id')::uuid,deposit_id,(item->>'withholding_id')::uuid,(item->>'income_tax_amount')::numeric,
   (item->>'cgst_amount')::numeric,(item->>'sgst_amount')::numeric,(item->>'igst_amount')::numeric,(item->>'deposited_amount')::numeric,actor_id);
 END LOOP;
 DELETE FROM "erp_compliance_commands"."command_scopes" WHERE backend_pid=pg_catalog.pg_backend_pid() AND transaction_id=pg_catalog.txid_current() AND scope='withholding_deposit' AND org_id=organization_id AND entity_id=deposit_id;
 PERFORM "erp_compliance_commands"."finish_claim"(organization_id,claim_id,'tax.withholding_deposits',deposit_id); RETURN deposit_id;
END
$function$;
ALTER FUNCTION "erp_compliance_commands"."post_withholding_deposit"(organization_id uuid, deposit_id uuid, actor_id uuid, payment_id uuid, challan_reference varchar, deposited_on date, evidence_attachment_id uuid, reversal_of_deposit_id uuid, reversal_reason text, deposit_lines jsonb, key_hash bytea, request_hash bytea, expires_at timestamptz) OWNER TO "erp_migration_owner";
REVOKE ALL ON FUNCTION "erp_compliance_commands"."post_withholding_deposit"(organization_id uuid, deposit_id uuid, actor_id uuid, payment_id uuid, challan_reference varchar, deposited_on date, evidence_attachment_id uuid, reversal_of_deposit_id uuid, reversal_reason text, deposit_lines jsonb, key_hash bytea, request_hash bytea, expires_at timestamptz) FROM PUBLIC, "erp_app", "erp_runtime";
GRANT EXECUTE ON FUNCTION "erp_compliance_commands"."post_withholding_deposit"(organization_id uuid, deposit_id uuid, actor_id uuid, payment_id uuid, challan_reference varchar, deposited_on date, evidence_attachment_id uuid, reversal_of_deposit_id uuid, reversal_reason text, deposit_lines jsonb, key_hash bytea, request_hash bytea, expires_at timestamptz) TO "erp_app", "erp_runtime";
-- Reviewed enforcement: tax.withholding_rule_versions:withholding_rule_versions_release_authority
CREATE FUNCTION "erp_regulatory_commands"."import_withholding_release"(p_release_id uuid, p_ruleset_version varchar, p_source_authority text, p_source_uri text, p_source_storage_bucket text, p_source_storage_object_path text, p_source_media_type varchar, p_source_bytes bytea, p_source_sha256 bytea, p_dataset_storage_bucket text, p_dataset_storage_object_path text, p_dataset_bytes bytea, p_dataset_sha256 bytea, p_publication_date date, p_effective_from date, p_effective_to date, p_reviewed_by_user_id uuid, p_reviewed_at timestamptz, p_request_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE prior_id uuid; item jsonb; supplied_count integer; p_dataset_rows jsonb;
BEGIN
    IF p_request_id IS NULL
       OR NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM p_request_id THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='withholding import requires the matching transaction-local request id';
    END IF;
    p_dataset_rows:=pg_catalog.convert_from(p_dataset_bytes,'UTF8')::jsonb;
    prior_id:="erp_regulatory_commands"."stage_release"(p_release_id,'withholding_rules',p_ruleset_version,
      p_source_authority,p_source_uri,p_source_storage_bucket,p_source_storage_object_path,
      p_source_media_type,p_source_bytes,p_source_sha256,p_dataset_storage_bucket,
      p_dataset_storage_object_path,p_dataset_bytes,p_dataset_sha256,p_publication_date,
      p_effective_from,p_effective_to,p_reviewed_by_user_id,p_reviewed_at);
    supplied_count:=pg_catalog.jsonb_array_length(p_dataset_rows);
    IF EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_array_elements(p_dataset_rows) AS row(value)
       WHERE pg_catalog.jsonb_typeof(value)<>'object'
          OR NOT value ?& ARRAY['id','rule_code','version_number','tax_regime','governing_act_code','provision_code','fiscal_year_start_from','fiscal_year_start_to','effective_from','effective_to','deduction_trigger','source_kind','nature_code','deductor_person_type','deductee_person_type','deductee_residency','deductee_pan_status','organization_prior_fy_turnover_threshold','transaction_threshold','aggregation_scope','threshold_application','basis_mode','income_tax_rate','cgst_rate','sgst_rate','igst_rate','deposit_due_policy','deposit_month_offset','deposit_due_day','statement_form_code','certificate_form_code']
          OR value - ARRAY['id','rule_code','version_number','tax_regime','governing_act_code','provision_code','fiscal_year_start_from','fiscal_year_start_to','effective_from','effective_to','deduction_trigger','source_kind','nature_code','deductor_person_type','deductee_person_type','deductee_residency','deductee_pan_status','organization_prior_fy_turnover_threshold','transaction_threshold','aggregation_scope','threshold_application','basis_mode','income_tax_rate','cgst_rate','sgst_rate','igst_rate','deposit_due_policy','deposit_month_offset','deposit_due_day','statement_form_code','certificate_form_code'] <> '{}'::jsonb
          OR pg_catalog.btrim(value->>'rule_code')=''
          OR (value->>'version_number')::integer<=0
          OR value->>'tax_regime' NOT IN ('income_tax_tds','gst_tds')
          OR pg_catalog.btrim(value->>'governing_act_code')=''
          OR pg_catalog.btrim(value->>'provision_code')=''
          OR (value->>'fiscal_year_start_from')::integer NOT BETWEEN 2000 AND 9999
          OR (NULLIF(value->>'fiscal_year_start_to',''))::integer<(value->>'fiscal_year_start_from')::integer
          OR (value->>'effective_from')::date<p_effective_from
          OR (p_effective_to IS NOT NULL AND COALESCE(NULLIF(value->>'effective_to','')::date,p_effective_to)>p_effective_to)
          OR value->>'deduction_trigger' NOT IN ('credit','earlier_credit_or_payment')
          OR value->>'source_kind' NOT IN ('supplier_invoice','expense_claim')
          OR pg_catalog.btrim(value->>'nature_code')=''
          OR value->>'deductee_residency' NOT IN ('any','resident','non_resident')
          OR value->>'deductee_pan_status' NOT IN ('any','verified','inoperative','not_available','not_applicable')
          OR value->>'aggregation_scope' NOT IN ('party_rule_fiscal_year','contract')
          OR value->>'threshold_application' NOT IN ('excess_only','full_amount')
          OR value->>'basis_mode' NOT IN ('net_value','net_excluding_gst_cess','approved_amount')
          OR COALESCE(NULLIF(value->>'organization_prior_fy_turnover_threshold','')::numeric,0)<0
          OR (value->>'transaction_threshold')::numeric<0
          OR (value->>'income_tax_rate')::numeric<0 OR (value->>'cgst_rate')::numeric<0
          OR (value->>'sgst_rate')::numeric<0 OR (value->>'igst_rate')::numeric<0
          OR value->>'deposit_due_policy' NOT IN ('day_of_following_month','days_after_deduction','fixed_date_after_fy_end')
          OR (value->>'deposit_month_offset')::integer NOT BETWEEN 0 AND 24
          OR (value->>'deposit_due_day')::integer NOT BETWEEN 1 AND 31
    ) OR (SELECT count(DISTINCT value->>'id') FROM pg_catalog.jsonb_array_elements(p_dataset_rows))<>supplied_count
      OR (SELECT count(DISTINCT (value->>'rule_code',value->>'version_number')) FROM pg_catalog.jsonb_array_elements(p_dataset_rows))<>supplied_count
      OR EXISTS (
        SELECT 1
          FROM pg_catalog.jsonb_array_elements(p_dataset_rows) WITH ORDINALITY AS left_row(value,ordinality)
          JOIN pg_catalog.jsonb_array_elements(p_dataset_rows) WITH ORDINALITY AS right_row(value,ordinality)
            ON left_row.ordinality<right_row.ordinality
         WHERE left_row.value->>'rule_code'=right_row.value->>'rule_code'
           AND left_row.value->>'tax_regime'=right_row.value->>'tax_regime'
           AND left_row.value->>'source_kind'=right_row.value->>'source_kind'
           AND left_row.value->>'nature_code'=right_row.value->>'nature_code'
           AND left_row.value->>'deductor_person_type'=right_row.value->>'deductor_person_type'
           AND left_row.value->>'deductee_person_type'=right_row.value->>'deductee_person_type'
           AND left_row.value->>'deductee_residency'=right_row.value->>'deductee_residency'
           AND left_row.value->>'deductee_pan_status'=right_row.value->>'deductee_pan_status'
           AND (left_row.value->>'effective_from')::date<=COALESCE(NULLIF(right_row.value->>'effective_to','')::date,'infinity'::date)
           AND (right_row.value->>'effective_from')::date<=COALESCE(NULLIF(left_row.value->>'effective_to','')::date,'infinity'::date)
           AND (left_row.value->>'fiscal_year_start_from')::integer<=COALESCE(NULLIF(right_row.value->>'fiscal_year_start_to','')::integer,9999)
           AND (right_row.value->>'fiscal_year_start_from')::integer<=COALESCE(NULLIF(left_row.value->>'fiscal_year_start_to','')::integer,9999)
      ) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='withholding dataset is not one exact non-overlapping reviewed typed set';
    END IF;
    IF prior_id IS NOT NULL THEN
      UPDATE tax.withholding_rule_versions SET status='retired'
       WHERE release_id=prior_id AND status='active';
    END IF;
    FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(p_dataset_rows) ORDER BY value->>'id' LOOP
      INSERT INTO tax.withholding_rule_versions(
        id,release_id,rule_code,version_number,tax_regime,governing_act_code,provision_code,
        fiscal_year_start_from,fiscal_year_start_to,effective_from,effective_to,deduction_trigger,
        source_kind,nature_code,deductor_person_type,deductee_person_type,deductee_residency,
        deductee_pan_status,organization_prior_fy_turnover_threshold,transaction_threshold,
        aggregation_scope,threshold_application,basis_mode,income_tax_rate,cgst_rate,sgst_rate,
        igst_rate,deposit_due_policy,deposit_month_offset,deposit_due_day,statement_form_code,certificate_form_code,status)
      VALUES((item->>'id')::uuid,p_release_id,item->>'rule_code',(item->>'version_number')::integer,
        item->>'tax_regime',item->>'governing_act_code',item->>'provision_code',
        (item->>'fiscal_year_start_from')::smallint,NULLIF(item->>'fiscal_year_start_to','')::smallint,
        (item->>'effective_from')::date,NULLIF(item->>'effective_to','')::date,
        item->>'deduction_trigger',item->>'source_kind',item->>'nature_code',
        item->>'deductor_person_type',item->>'deductee_person_type',item->>'deductee_residency',
        item->>'deductee_pan_status',NULLIF(item->>'organization_prior_fy_turnover_threshold','')::numeric,
        (item->>'transaction_threshold')::numeric,item->>'aggregation_scope',
        item->>'threshold_application',item->>'basis_mode',(item->>'income_tax_rate')::numeric,
        (item->>'cgst_rate')::numeric,(item->>'sgst_rate')::numeric,(item->>'igst_rate')::numeric,
        item->>'deposit_due_policy',
        (item->>'deposit_month_offset')::smallint,(item->>'deposit_due_day')::smallint,
        item->>'statement_form_code',item->>'certificate_form_code','active');
    END LOOP;
    IF (SELECT count(*) FROM tax.withholding_rule_versions WHERE release_id=p_release_id)<>supplied_count THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='withholding exact-set count mismatch';
    END IF;
    PERFORM "erp_regulatory_commands"."finish_release"(p_release_id,prior_id);
    RETURN p_release_id;
END
$function$;
ALTER FUNCTION "erp_regulatory_commands"."import_withholding_release"(p_release_id uuid, p_ruleset_version varchar, p_source_authority text, p_source_uri text, p_source_storage_bucket text, p_source_storage_object_path text, p_source_media_type varchar, p_source_bytes bytea, p_source_sha256 bytea, p_dataset_storage_bucket text, p_dataset_storage_object_path text, p_dataset_bytes bytea, p_dataset_sha256 bytea, p_publication_date date, p_effective_from date, p_effective_to date, p_reviewed_by_user_id uuid, p_reviewed_at timestamptz, p_request_id uuid) OWNER TO "erp_migration_owner";
